async function inboxTask215AsyncChecks(): Promise<void> {
  const { createTaskFromThread } = await import("../src/lib/inbox-task-write");
  const { all: allCustomers215 } = await import("../src/lib/stores/customers");
  const { createFixture } = await import("./test-fixtures");
  const roster = await activeUsers();
  const cust = (await allCustomers215()).find((x) => (x.locations || []).some((l) => !!l.id));
  ok(!!cust && roster.length > 0, "#215 inbox setup: a customer with a venue and an active user exist");
  if (!cust || !roster.length) return;
  const loc = cust.locations.find((l) => !!l.id)!.id as string;
  const now = Date.now();
  const me = { id: roster[0].id, name: roster[0].name };
  const thread = {
    // #215 fix wave 1 — visibleTo(t, me.name) requires mailbox === "personal"
    // && mailboxUser === me.name; a fixture stamped with an arbitrary name
    // was never actually visible to `me`; the "missing thread" test below
    // used to pass for the wrong reason (createTaskFromThread only checked
    // `!thread`), which is exactly the gap fix wave 1 closes.
    id: "C-T215", mailbox: "personal", mailboxUser: me.name, unread: false, customerId: cust.id, customer: cust.name,
    contactName: "Pat Lee", contactEmail: "pat@example.com", subject: "Re: rigging bid", channel: "email", status: "waiting_us",
    assignedTo: "", link: { type: "survey", id: "S-T215", label: "S-T215 · Main hall" }, messages: [], createdAt: now, updatedAt: now,
    resolvedContactId: "ct-T215-a", linkedContactIds: ["ct-T215-a", "ct-T215-b"], siteId: loc,
  };
  await createFixture("comms", thread as never);
  const r = await createTaskFromThread(
    { threadId: "C-T215", title: "Send revised bid", notes: "From email", assigneeUserId: "", dueDate: "2026-10-05", linkKeys: ["contact:ct-T215-b", "customer", "site", "work", "contact:ct-forged"] },
    me
  );
  ok(r.ok, "#215 writer: a task is created from a thread");
  if (!r.ok) return;
  registerFixture("tasks", r.task.id);
  const t = await getTask(r.task.id);
  ok(
    t?.threadId === "C-T215" && t.customerId === cust.id && t.siteId === loc && JSON.stringify(t.contactIds) === '["ct-T215-b"]',
    "#215 writer: thread, company, venue and the ticked person are stored"
  );
  ok(
    t?.section === "Email" && t.createdBy === me.name && t.assigneeUserId === me.id &&
      t.notes === "From email\nLinked survey: S-T215 · Main hall" && t.dueAt === new Date(2026, 9, 5, 12).getTime(),
    "#215 writer: section Email, created by and assigned to me, survey as a notes line, due at noon"
  );
  ok((await tasksForThread215("C-T215")).some((x) => x.id === r.task.id), "#215 writer: the thread's reader finds it");
  await createFixture("comms", { ...thread, id: "C-T215-stale", siteId: "loc-not-this-customer" } as never);
  const r2 = await createTaskFromThread({ threadId: "C-T215-stale", title: "x", notes: "", assigneeUserId: "", dueDate: "", linkKeys: ["site"] }, me);
  if (r2.ok) registerFixture("tasks", r2.task.id);
  ok(r2.ok && r2.task.siteId === undefined, "#215 writer: a venue that isn't the company's is never linked");
  const r3 = await createTaskFromThread({ threadId: "C-T215-missing", title: "x", notes: "", assigneeUserId: "", dueDate: "", linkKeys: [] }, me);
  ok(!r3.ok, "#215 writer: a missing thread is refused");
  await createFixture("comms", { ...thread, id: "C-T215-notmine", mailboxUser: "Somebody Else" } as never);
  const r4 = await createTaskFromThread({ threadId: "C-T215-notmine", title: "x", notes: "", assigneeUserId: "", dueDate: "", linkKeys: [] }, me);
  ok(
    !r4.ok && r4.error === "That email thread no longer exists.",
    "#215 fix wave 1: another person's personal thread (visibleTo false) is refused the same as a missing one, not just a missing thread"
  );
}

{
  const rd215 = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const noStoreImport215 = (src: string) =>
    !/^import\s+(?!type\b)[^;]*from\s+"@\/(lib\/stores\/|db\b|db\/|lib\/users"|lib\/calendar-tasks-load"|lib\/inbox-task-write")/m.test(src);
  const dlg = rd215("src/app/(app)/inbox/task-dialog.tsx");
  const card = rd215("src/app/(app)/inbox/thread-tasks-card.tsx");
  ok(dlg.startsWith('"use client"') && card.startsWith('"use client"') && noStoreImport215(dlg) && noStoreImport215(card), "#215 inbox task UI imports no store, db or writer");
  const ta = rd215("src/app/(app)/inbox/task-actions.ts");
  ok(ta.startsWith('"use server"') && (ta.match(/await requireUser\(\)/g) || []).length === 2 && ta.includes("createTaskFromThread("), "#215 both inbox task actions require a user; create delegates to the writer");
  const reader = rd215("src/app/(app)/inbox/thread-reader.tsx");
  ok(reader.includes("Task…") && reader.includes("<TaskDialog") && reader.includes("onCreateTask"), "#215 the reader has Task… per message, mounts the dialog, and wires the link panel's Create task");
  ok(rd215("src/app/(app)/inbox/link-sidebar.tsx").includes("<ThreadTasksCard"), "#215 the link sidebar lists the thread's open tasks");
  const pg = rd215("src/app/(app)/inbox/page.tsx");
  ok(pg.includes("threadTaskLinkCandidates(") && pg.includes("tasksForThread(") && pg.includes("taskTeam:"), "#215 the Inbox page builds the dialog links, team and thread tasks");

  // #215 fix wave 1
  ok(!dlg.includes("autoFocus"), "#215 fix wave 1: the task dialog doesn't use the uncontrolled autoFocus attribute");
  ok(
    dlg.includes("openerRef.current = document.activeElement") &&
      dlg.includes("titleRef.current?.focus()") &&
      dlg.includes("opener.isConnected") &&
      dlg.includes("containerRef?.current"),
    "#215 fix wave 1: the mount effect records the opener and focuses the Title field via a ref; close restores focus only to a still-connected opener, else the reader's container"
  );
  ok(
    dlg.includes('t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT"') && dlg.includes("if (inField) return;"),
    "#215 fix wave 1: Escape in a field doesn't discard the task dialog's typed text"
  );
  ok(
    /onCreateTask=\{\s*vm\.isEmail/.test(reader),
    "#215 fix wave 1: the link panel's Create task is gated on vm.isEmail (Edit links itself isn't email-gated)"
  );
  ok(
    card.includes("isEmail") && card.includes("No open tasks on this thread.") && card.includes("Use “Task…” on a message to add one."),
    "#215 fix wave 1: the empty tasks-card hint only mentions Task… on an email thread"
  );
  ok(
    dlg.includes("(vm.subject || \"\").slice(0, THREAD_TASK_TITLE_MAX)"),
    "#215 fix wave 1: the pre-filled title (the subject) is capped to THREAD_TASK_TITLE_MAX"
  );
}

/* ====================================================================
   #217 T1 — service quotes round to $25, take a typed total and (flame) a
   typed per-venue testing cost. The pure finish module + the three engines.
   ==================================================================== */
import {
  PRICE_STEP as PRICE_STEP217,
  roundToStep as roundToStep217,
  normalizePriceOverride as normalizePriceOverride217,
  normalizeTestingOverride as normalizeTestingOverride217,
  finishPrice as finishPrice217,
  finishFlame as finishFlame217,
  finishRepair as finishRepair217,
  finishInspection as finishInspection217,
  typedPriceWarning as typedPriceWarning217,
  sliderPts as sliderPts217,
  fmtPts as fmtPts217,
  travelLineShare as travelLineShare217,
  seedPriceOverride as seedPriceOverride217,
} from "@/lib/service-pricing";
{
  const near217 = (a: number | undefined, b: number): boolean => a != null && Math.abs(a - b) < 1e-6;

  // ---- pure rules ----
  ok(PRICE_STEP217 === 25, "#217: the rounding step is $25");
  ok(roundToStep217(821.43) === 825 && roundToStep217(812.49) === 800 && roundToStep217(812.5) === 825 && roundToStep217(837.5) === 850,
    "#217 roundToStep: nearest $25, half rounds up");
  ok(roundToStep217(0) === 0 && roundToStep217(25) === 25 && roundToStep217(Number.NaN) === 0 && roundToStep217(14, 10) === 10 && roundToStep217(15, 10) === 20,
    "#217 roundToStep: exact multiples stay, NaN is 0, a custom step works");
  ok(roundToStep217(862.4999999999999) === 875, "#217 roundToStep: float noise just under a half still rounds up");
  ok(normalizePriceOverride217("1,234.40") === 1234 && normalizePriceOverride217("$900") === 900 && normalizePriceOverride217(950) === 950 && normalizePriceOverride217(10_000_000) === 10_000_000,
    "#217 priceOverride: whole dollars, $ and commas tolerated, up to $10,000,000");
  ok([0, -5, 10_000_001, "abc", "", null, undefined, true].every((v) => normalizePriceOverride217(v) === undefined),
    "#217 priceOverride: zero, negative, over the cap, junk and blank are no override");
  ok(normalizePriceOverride217("0x10") === undefined && normalizePriceOverride217("1e3") === undefined && normalizePriceOverride217("-0.4") === undefined,
    "#217 fix wave: hex, exponent and a leading minus are not plain digits — rejected, not silently parsed by Number()");
  ok(normalizeTestingOverride217("0") === 0 && normalizeTestingOverride217(" 120 ") === 120 && normalizeTestingOverride217("") === undefined && normalizeTestingOverride217(-1) === undefined,
    "#217 testingOverride: $0 is a real figure, blank is computed, negatives refused");
  ok(normalizeTestingOverride217(-0.4) === undefined && !Object.is(normalizeTestingOverride217(-0.4), -0) && !Object.is(normalizeTestingOverride217(-0), -0),
    "#217 fix wave 2: a raw negative number like -0.4 is refused (not silently rounded to -0 and passed as >= 0), and -0 itself never comes back as -0");
  ok(finishPrice217(1000, 500, "$900").total === 900 && finishPrice217(1000, 500, 0).total === 1000 && finishPrice217(1000, 500, -5).total === 1000 && finishPrice217(1000, 500, 20_000_000).total === 1000,
    "#217 fix wave: finishPrice normalizes priceOverride itself — a typed string works there directly, and zero/negative/over-cap fall back to auto");
  ok(typedPriceWarning217(500, 575, 1 - 575 / 500)?.kind === "below-cost" && typedPriceWarning217(600, 575, 1 - 575 / 600)?.kind === "low-margin" && typedPriceWarning217(800, 575, 1 - 575 / 800) === null,
    "#217 warning: below cost first, then under a 10% margin, otherwise none");
  ok(typedPriceWarning217(1200, 1100, 1 - 1100 / 1200, 1428.57)?.kind === "below parts price",
    "#217 fix wave warning: a typed total under the parts' own sell price warns distinctly, even though it still clears the whole job's raw cost");
  ok(typedPriceWarning217(1500, 1100, 1 - 1100 / 1500, 1428.57) === null,
    "#217 fix wave warning: once the typed total clears the parts sell, the cost and the 10% floor, there's no warning");
  ok(typedPriceWarning217(500, 575, 1 - 575 / 500, 100)?.kind === "below-cost",
    "#217 fix wave warning: below-cost still wins when parts sell isn't the binding constraint");
  ok(sliderPts217(0.05) === 10 && sliderPts217(0.62) === 50 && sliderPts217(0.3) === 30 && sliderPts217(0.28125) === 28,
    "#217 slider: the back-solved margin moves the slider, clamped to 10–50");
  ok(fmtPts217(0.28125) === "28.1" && fmtPts217(0.3) === "30", "#217: the margin label shows the true value to one decimal");
  const s1 = travelLineShare217({ flightTotal: 1765, total: 3600, cost: 2515, margin: 0.3 });
  ok(s1.travel === 2526 && s1.rest === 1074 && s1.travel + s1.rest === 3600,
    "#217 printed lines: the travel line is travel's share of the rounded total; the service part takes the rest");
  const s2 = travelLineShare217({ flightTotal: 1765, total: 1000, cost: 2515, margin: 0.3 });
  ok(s2.travel === 702 && s2.travel + s2.rest === 1000, "#217 printed lines: a typed total below cost scales the travel line with it");
  const s3 = travelLineShare217({ flightTotal: 1765, total: 3593, cost: null, margin: 0.3 });
  ok(s3.travel === 2521 && s3.rest === 3593 - 2521, "#217 printed lines: a legacy quote with no stored cost keeps the D283 figure");
  const s4 = travelLineShare217({ flightTotal: 1765, total: 1000, cost: null, margin: 0 });
  ok(s4.travel === 1000 && s4.rest === 0, "#217 printed lines: the travel line never exceeds the total");
  ok(seedPriceOverride217("sent", 821, undefined) === 821 && seedPriceOverride217("won", 821.4, null) === 821,
    "#217 D286 parity: a pre-#217 sent quote priced off the $25 grid reopens with that price typed in");
  ok(seedPriceOverride217("draft", 821, undefined) === null && seedPriceOverride217("sent", 825, undefined) === null && seedPriceOverride217("sent", 0, undefined) === null,
    "#217: drafts, on-grid prices and zero values reopen on auto");
  ok(seedPriceOverride217("draft", 825, 900) === 900 && seedPriceOverride217("sent", 821, "900") === 900,
    "#217: a saved typed total always reopens as typed");

  // ---- flame engine ----
  const fRates217 = { mileageRate: 1, laborRate: 75, curtainMinutes: 5, baseFee: 150, margin: 0.3, travelRoundMin: 15 };
  const fNear217: FTVenue = { id: "r217-near", label: "Near", curtains: 12, oneWayMiles: 100, oneWayMin: 120 };
  const fa = computeFlameQuote({ venues: [fNear217] }, fRates217);
  ok(near217(fa.totalRaw, 575 / 0.7) && fa.autoTotal === 825 && fa.total === 825 && !fa.overridden && fa.priceOverride === null,
    "#217 flame: the auto total rounds 821.43 → 825");
  ok(fa.marginAmount === 250 && near217(fa.effectiveMargin, 1 - 575 / 825) && fa.margin === 0.3,
    "#217 flame: margin amount = total − cost, the effective margin back-solves, the rate margin is unchanged");
  const fo = computeFlameQuote({ venues: [fNear217], priceOverride: 800 }, fRates217);
  ok(fo.total === 800 && fo.overridden && fo.priceOverride === 800 && fo.autoTotal === 825 && near217(fo.effectiveMargin, 1 - 575 / 800) && fo.marginAmount === 225,
    "#217 flame: a typed total is used exactly and the margin back-solves");
  ok(computeFlameQuote({ venues: [fNear217], priceOverride: 812 }, fRates217).total === 812,
    "#217 flame: a typed total off the $25 grid is not re-rounded");
  const fBad = computeFlameQuote({ venues: [fNear217], priceOverride: "abc" }, fRates217);
  ok(fBad.total === 825 && !fBad.overridden, "#217 flame: an invalid typed total prices at auto");
  const ft = computeFlameQuote({ venues: [{ ...fNear217, testingOverride: 100 }] }, fRates217);
  ok(ft.perVenue[0].laborCost === 100 && ft.perVenue[0].computedCost === 75 && ft.perVenue[0].testingOverride === 100 && ft.testingSubtotal === 100 && ft.rawCost === 600 && ft.total === 850,
    "#217 flame: a typed testing cost replaces that venue's labor and the auto total re-rounds (857.14 → 850)");
  const ftBlank = computeFlameQuote({ venues: [{ ...fNear217, testingOverride: "" }] }, fRates217);
  ok(ftBlank.perVenue[0].laborCost === 75 && ftBlank.perVenue[0].testingOverride === null, "#217 flame: a blank testing cost is computed");
  const fFloor = computeFlameQuote({ venues: [{ id: "r217-here", label: "Here", curtains: 1, oneWayMiles: 0, oneWayMin: 0 }] }, fRates217);
  ok(fFloor.baseApplied && fFloor.cost === 150 && fFloor.total === 225,
    "#217 flame: the base fee floors the cost first, then the total rounds (214.29 → 225)");
  const ff360 = finishFlame217({ rawCost: 50, baseFee: 360, margin: 0, priceOverride: null });
  ok(ff360.baseApplied && ff360.totalRaw === 360 && ff360.total === 375,
    "#217 fix wave floors: a $360 base fee floors the total, which rounds UP to $375, never down to $350");

  // ---- repair engine ----
  const rRates217 = { laborRate: 75, mileageRate: 1, minCallout: 350, partsMargin: 0.3, margin: 0.3, emergencyMult: 1.5, travelRoundMin: 15 };
  const rNear217 = [{ label: "Near", oneWayMiles: 60, oneWayMin: 70 }];
  const ra = trvRepairEstimate({ venues: rNear217, laborHours: 4 }, rRates217);
  ok(near217(ra.totalRaw, 607.5 / 0.7) && ra.total === 875 && ra.serviceSell === 875 && near217(ra.serviceMargin, 1 - 607.5 / 875),
    "#217 repair: the auto total rounds 867.86 → 875 and the service sell absorbs the difference");
  const rp = trvRepairEstimate({ venues: rNear217, laborHours: 4, parts: [{ name: "Cable", qty: 2, cost: 100 }] }, rRates217);
  ok(rp.total === 1150 && near217(rp.partsSell, 200 / 0.7) && near217(rp.serviceSell, 1150 - 200 / 0.7) && near217(rp.serviceSell + rp.partsSell, rp.total),
    "#217 repair: with parts the total rounds 1,153.57 → 1,150 and service + parts sell still sum to it");
  const ro = trvRepairEstimate({ venues: rNear217, laborHours: 4, parts: [{ name: "Cable", qty: 2, cost: 100 }], priceOverride: 1000 }, rRates217);
  ok(ro.total === 1000 && ro.overridden && near217(ro.partsSell, 200 / 0.7) && near217(ro.marginAmount, 1000 - 807.5) && near217(ro.serviceMargin, ro.effectiveMargin) && near217(ro.effectiveMargin, 1 - 807.5 / 1000),
    "#217 fix wave repair: a typed total reports the whole-job EFFECTIVE margin (never the service-only ratio) — parts still sell at their own markup");
  const rc = trvRepairEstimate({ venues: [{ label: "Here", oneWayMiles: 0, oneWayMin: 0 }], laborHours: 1 }, rRates217);
  ok(rc.calloutApplied && rc.total === 350, "#217 repair: the minimum call-out floors the service sell before rounding");
  const rf360 = finishRepair217({ serviceCost: 50, minCallout: 360, margin: 0, partsCost: 0, partsMargin: 0.3, priceOverride: null });
  ok(rf360.calloutApplied && rf360.totalRaw === 360 && rf360.total === 375,
    "#217 fix wave floors: a $360 minimum call-out floors the total, which rounds UP to $375, never down to $350");
  ok(finishRepair217({ serviceCost: 812, minCallout: 0, margin: 0, partsCost: 0, partsMargin: 0.3, priceOverride: null }).total === 800 &&
      finishPrice217(812, 500, null, true).total === 825,
    "#217 fix wave floors: the same raw total rounds to the NEAREST $25 with no floor applied, but rounds UP when a floor set the price");
  const rTyped1 = finishRepair217({ serviceCost: 100, minCallout: 0, margin: 0.3, partsCost: 1000, partsMargin: 0.3, priceOverride: 1200 });
  ok(rTyped1.total === 1200 && rTyped1.overridden && near217(rTyped1.serviceMargin, rTyped1.effectiveMargin) && near217(rTyped1.effectiveMargin, 1 - 1100 / 1200),
    "#217 fix wave repair margin: a $1,200 typed total (service $100 cost, $1,000 parts cost) reports the effective margin");
  const rTyped2 = finishRepair217({ serviceCost: 100, minCallout: 0, margin: 0.3, partsCost: 1000, partsMargin: 0.3, priceOverride: 1430 });
  ok(rTyped2.total === 1430 && rTyped2.serviceSell > 0 && near217(rTyped2.serviceMargin, rTyped2.effectiveMargin) && near217(rTyped2.effectiveMargin, 1 - 1100 / 1430),
    "#217 fix wave repair margin: even once the typed total lifts the service sell back to a thin positive sliver, it still reports the effective margin — no discontinuity near zero");
  const rAutoZero = finishRepair217({ serviceCost: 0, minCallout: 0, margin: 0.3, partsCost: 1000, partsMargin: 0.3, priceOverride: null });
  ok(!rAutoZero.overridden && rAutoZero.serviceSellAuto === 0 && near217(rAutoZero.serviceMargin, rAutoZero.effectiveMargin) && rAutoZero.serviceMargin > 0,
    "#217 fix wave repair margin: a parts-only auto job with no call-out floor (service sell $0) reports the effective margin instead of a flat 0");
  const rCliff = finishRepair217({ serviceCost: 1, minCallout: 0, margin: 0.3, partsCost: 1000, partsMargin: 0.3, priceOverride: null });
  ok(!rCliff.overridden && rCliff.serviceSellAuto > 0 && rCliff.serviceSell < 0 && near217(rCliff.serviceSell, -3.5714285714287) &&
      near217(rCliff.serviceMargin, rCliff.effectiveMargin) && rCliff.serviceMargin > 0.25,
    "#217 fix wave 2: serviceMargin gates on the FINAL serviceSell (post-rounding, total − partsSell), not the pre-rounding " +
      "serviceSellAuto — a positive serviceSellAuto (1.43) whose rounded serviceSell goes negative (-3.57) no longer cliffs " +
      "the margin to 0; it reports the whole-job effectiveMargin instead");
  ok(Math.abs(rCliff.serviceMargin - rAutoZero.serviceMargin) < 0.01,
    "#217 fix wave 2: serviceCost 0 vs 1 (same rounded $1,425 total) give close margins — no discontinuity right where " +
      "serviceSell crosses zero");

  // ---- inspection engine ----
  const iRates217 = { laborRate: 75, mileageRate: 1, lineSetMinutes: 15, baseHours: 2, level2Mult: 1.75, minFee: 650, margin: 0.3, travelRoundMin: 15 };
  const iNear217 = [{ id: "r217-i1", label: "Near", lineSets: 20, oneWayMiles: 60, oneWayMin: 70 }];
  const ia = trvInspectionEstimate({ venues: iNear217 }, iRates217);
  ok(near217(ia.totalRaw, 832.5 / 0.7) && ia.total === 1200 && near217(ia.effectiveMargin, 1 - 832.5 / 1200),
    "#217 inspection: the auto total rounds 1,189.29 → 1,200");
  const io = trvInspectionEstimate({ venues: iNear217, priceOverride: 1100 }, iRates217);
  ok(io.total === 1100 && io.overridden && io.autoTotal === 1200 && near217(io.effectiveMargin, 1 - 832.5 / 1100),
    "#217 inspection: a typed total is used exactly");
  const im = trvInspectionEstimate({ venues: [{ id: "r217-i2", label: "Here", lineSets: 0, oneWayMiles: 0, oneWayMin: 0 }] }, iRates217);
  ok(im.minApplied && im.total === 650, "#217 inspection: the minimum fee floors before rounding");
  const if660 = finishInspection217({ cost: 50, minFee: 660, margin: 0, priceOverride: null });
  ok(if660.minApplied && if660.totalRaw === 660 && if660.total === 675,
    "#217 fix wave floors: a $660 minimum fee floors the total, which rounds UP to $675, never down to $650");

  // ---- parity: each engine's finish IS the shared finish the builders will call ----
  const pf = finishFlame217({ rawCost: fa.rawCost, baseFee: 150, margin: 0.3, priceOverride: null });
  ok(pf.total === fa.total && pf.cost === fa.cost && pf.effectiveMargin === fa.effectiveMargin, "#217 parity: the flame engine finishes exactly like finishFlame()");
  const pr = finishRepair217({ serviceCost: rp.serviceCost, minCallout: 350, margin: 0.3, partsCost: rp.partsCost, partsMargin: 0.3, priceOverride: null });
  ok(pr.total === rp.total && pr.serviceSell === rp.serviceSell && pr.serviceMargin === rp.serviceMargin, "#217 parity: the repair engine finishes exactly like finishRepair()");
  const pi = finishInspection217({ cost: ia.cost, minFee: 650, margin: 0.3, priceOverride: null });
  ok(pi.total === ia.total && pi.effectiveMargin === ia.effectiveMargin, "#217 parity: the inspection engine finishes exactly like finishInspection()");
  for (const [f, fn] of [
    ["src/lib/flametest-engine.ts", "finishFlame"],
    ["src/lib/repair-engine.ts", "finishRepair"],
    ["src/lib/inspection-engine.ts", "finishInspection"],
  ] as const) {
    const s = readFileSync(join(process.cwd(), f), "utf8");
    const code = s.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, ""); // doc comments still quote the formula
    ok(code.includes(`${fn}(`) && /from "@\/lib\/service-pricing"/.test(code) && !/\/ \(1 - margin\)/.test(code),
      `#217: ${f} finishes its price through ${fn}() with no margin math of its own`);
  }
  const sp217 = readFileSync(join(process.cwd(), "src/lib/service-pricing.ts"), "utf8");
  ok(!/^\s*import\s/m.test(sp217), "#217: service-pricing.ts imports nothing — safe for the 'use client' builders");
  const formula217 = (key: string, id: string): string =>
    (PRICING_GROUPS.find((g) => g.key === key)!.items.find((it) => it.id === id) as { expr: string }).expr;
  ok(formula217("flame", "flame.total").includes("rounded to the nearest $25") &&
      formula217("repair", "repair.total").includes("rounded to the nearest $25") &&
      formula217("inspection", "inspection.total").includes("rounded to the nearest $25"),
    "#217: the Estimating Rules formulas say service totals round to the nearest $25");
}

/* ====================================================================
   #217 T2 — save paths persist the typed total / testing cost and the
   back-solved margin; renewals re-price without them and say when last
   year's price was hand-set; letters print travel's share of the final total.
   ==================================================================== */
import {
  priceParagraph as priceParagraph217,
  priorHandSetPrice as priorHandSetPrice217,
} from "@/lib/renewal-outreach";
{
  const src217 = (f: string): string => readFileSync(join(process.cwd(), f), "utf8");
  const typedIn = /const priceOverride = normalizePriceOverride\(formData\.get\("priceOverride"\)\);/;
  const storedTyped = /\.\.\.\(r\.priceOverride != null \? \{ priceOverride: r\.priceOverride \} : \{\}\)/;
  const storedAuto = /autoTotal: Math\.round\(r\.autoTotal\),/;

  const fa = src217("src/app/(app)/flame-tests/quote/actions.ts");
  ok(typedIn.test(fa) && /venues: venueInputs, travel: travelOverride, priceOverride \}/.test(fa),
    "#217 flame save: reads the typed total and prices with it");
  // #248 fix round 1: the venue-input mapping (incl. the typed testing-cost
  // validation below) moved out of this file into the shared
  // src/lib/service-quote-inputs.ts (also called by the portal's
  // builder-identical pricing) — this now asserts the builder calls that
  // shared helper AND that the helper itself still carries the
  // testingOverride mapping, so the same invariant (a venue's typed testing
  // cost is validated, priced and saved) stays guarded either way.
  const sqi217 = src217("src/lib/service-quote-inputs.ts");
  ok(/venueInputs: FlameTestVenueInput\[\] = flameVenueInputsFrom\(venues, cust\);/.test(fa) &&
      /testingOverride: normalizeTestingOverride\(v\.testingOverride\),/.test(sqi217) &&
      /\.\.\.\(v\.testingOverride != null \? \{ testingOverride: v\.testingOverride \} : \{\}\)/.test(fa),
    "#217 flame save: builds venue inputs through the shared service-quote-inputs.ts helper (which validates + prices each venue's typed testing cost), and still saves it on the venue");
  ok(/margin: r\.effectiveMargin,/.test(fa) && storedTyped.test(fa) && storedAuto.test(fa),
    "#217 flame save: stores the back-solved margin, the typed total (when set) and the auto figure");

  const ra = src217("src/app/(app)/repairs/quote/actions.ts");
  ok(typedIn.test(ra) && /travel: travelOverride,\n\s*priceOverride,\n/.test(ra) && /margin: r\.serviceMargin,/.test(ra) && storedTyped.test(ra) && storedAuto.test(ra),
    "#217 repair save: typed total in; service margin, typed total and auto figure out");

  const ia = src217("src/app/(app)/inspections/quote/actions.ts");
  ok(typedIn.test(ia) && /travel: travelOverride,\n\s*priceOverride,\n/.test(ia) && /margin: r\.effectiveMargin,/.test(ia) && storedTyped.test(ia) && storedAuto.test(ia),
    "#217 inspection save: typed total in; back-solved margin, typed total and auto figure out");

  const rn = src217("src/lib/renewal-outreach.ts");
  const fnBody = (name: string): string => {
    const at = rn.indexOf(`async function ${name}`);
    return at < 0 ? "" : rn.slice(at, rn.indexOf("\n}\n", at));
  };
  for (const fn of ["ensureFlameRenewalQuote", "ensureInspectionRenewalQuote"]) {
    const b = fnBody(fn);
    ok(b.length > 0 && !/priceOverride:/.test(b) && !/testingOverride/.test(b),
      `#217 renewal: ${fn} re-prices without last year's typed total or testing cost`);
    ok(/lastHandSet: priorHandSetPrice\(/.test(b) && /margin: r\.effectiveMargin,/.test(b) && storedAuto.test(b),
      `#217 renewal: ${fn} notes a hand-set prior price and stores the rounded price's margin`);
  }
  ok(priorHandSetPrice217({ priceOverride: 850 }) === 850 && priorHandSetPrice217({}) === null && priorHandSetPrice217(null) === null,
    "#217 renewal: last year's hand-set price is read from its priceOverride");
  type PP217 = Parameters<typeof priceParagraph217>[0];
  const para = priceParagraph217({ quote: { value: 900 }, lastPrice: 850, reasons: [], lastHandSet: 850 } as unknown as PP217, "inspection");
  ok(para.includes("Last year's price was hand-set at $850; this year's is priced at our current rates.") && para.includes("compared with $850 last year"),
    "#217 renewal: the draft body says last year's price was hand-set");
  const para2 = priceParagraph217({ quote: { value: 900 }, lastPrice: 850, reasons: [] } as unknown as PP217, "inspection");
  ok(!para2.includes("hand-set"), "#217 renewal: no hand-set sentence when last year's price was auto");

  for (const f of [
    "src/app/(app)/flame-tests/letter/letter-view.tsx",
    "src/app/(app)/inspections/letter/letter-view.tsx",
    "src/app/(app)/repairs/letter/letter-view.tsx",
    "src/lib/renewal-outreach.ts",
  ]) {
    const s = src217(f);
    ok(/travelLineShare\(\{/.test(s) && !/travelLineAmount\(/.test(s),
      `#217 printed lines: ${f} prints travel's share of the final total`);
  }
}

/* ====== #225 Consulting proposal document fixes ======
   Source-level checks against the proposal generator (kind=proposal) at
   design/engagements/letter/page.tsx: no duplicate header company/type
   lines, a Dear line addressed to the contact, a print @page scoped to
   this document (never the shared globals.css @page), bulleted
   assumptions, only the quote's own terms (never the template's canned
   termsBlock), no Anticipated phases block, and an acceptance block that
   signs the contact + estimator rather than the two companies. */
{
  const read225 = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const letter225 = read225("src/app/(app)/design/engagements/letter/page.tsx");

  ok(
    !letter225.includes("Consulting Proposal & Professional Services Agreement"),
    "#225: the old always-on header type line ('Consulting Proposal & Professional Services Agreement') is gone"
  );
  ok(
    /kind === "spec" && \([\s\S]{0,300}\{companyName\}/.test(letter225),
    "#225: the header-band company-name line only renders for the spec document, not the proposal"
  );

  ok(
    /Dear \{contact\?\.name \|\| "Sir or Madam"\}/.test(letter225),
    "#225: the proposal has a Dear line addressed to the contact (fallback 'Sir or Madam', matching repairs/letter)"
  );

  ok(
    /@media print[\s\S]{0,40}@page \{[\s\S]{0,60}margin: 0;/.test(letter225),
    "#225: the proposal document carries its own print @page rule with margin 0 (kills the browser header/footer gutter)"
  );
  ok(
    !/@page[\s\S]{0,80}margin: 0\.9in 1in/.test(letter225),
    "#225: the proposal's page-scoped CSS doesn't just restate the global 0.9in/1in @page — it actually overrides it to 0"
  );
  const globalPageCss225 = read225("src/app/globals.css");
  ok(
    /@page \{\s*size: letter;\s*margin: 0\.9in 1in;\s*\}/.test(globalPageCss225),
    "#225: the shared global @page in globals.css is untouched (still 0.9in 1in) — the override is scoped to this document only"
  );
  ok(
    letter225.includes("padding: 0.9in 1in !important"),
    "#225: print padding is restored inside the sheet (equivalent spacing) now that @page margin is 0"
  );

  ok(
    /<ul style=\{\{[^}]*listStyle: "disc"[^}]*\}\}>\s*\{assumptions\.map/.test(letter225),
    "#225: the assumptions <ul> sets listStyle: disc (Tailwind v4 resets list bullets)"
  );

  ok(
    !/renderField\(t, "consulting_proposal", "termsBlock", vars\)/.test(letter225),
    "#225: the proposal no longer prints the template's canned termsBlock boilerplate"
  );
  ok(
    /\{termsText && \(/.test(letter225) || /termsText &&[\s\S]{0,80}Terms<\/div>/.test(letter225),
    "#225: the Terms heading + block print only when the quote itself has terms"
  );
  const templates225 = read225("src/lib/templates.ts");
  ok(
    templates225.includes('id: "termsBlock"') && templates225.includes('label: "Standard terms"'),
    "#225: the termsBlock template field itself stays defined in templates.ts (unused by the proposal, not deleted)"
  );

  ok(
    !letter225.includes("Anticipated phases:"),
    "#225: the Anticipated phases line is removed from the proposal document"
  );

  ok(
    /\[contact\?\.name \|\| "Customer", quote\?\.owner \|\| "Jeff Chesebro"\]/.test(letter225),
    "#225: the acceptance block signs the contact (fallback Customer) and the estimator quote.owner (fallback Jeff Chesebro), not the two companies"
  );
  ok(
    !/\[customer \|\| "Customer", companyName\]/.test(letter225),
    "#225: the old company-vs-company acceptance pair is gone"
  );
}

/* ====== #224 Short lists on companies ======
   Pure helpers behind ShortList (src/lib/short-list.ts, src/components/
   short-list.tsx): visibleRows/filterRows/visibleGroupFlags, plus
   source-level checks that the company record no longer hard-slices Site
   visits, that the Companies + Venues directories page by `?n=`, and that
   the client ShortList component stays store/db-free. */
import { visibleRows as slVisibleRows, filterRows as slFilterRows, visibleGroupFlags } from "@/lib/short-list";
{
  ok(slVisibleRows(20, 5, false) === 5, "#224 short-list: collapsed shows `initial` rows");
  ok(slVisibleRows(3, 5, false) === 3, "#224 short-list: collapsed never shows more than `total` rows");
  ok(slVisibleRows(20, 5, true) === 20, "#224 short-list: expanded shows every row");
  ok(slVisibleRows(0, 5, false) === 0 && slVisibleRows(0, 5, true) === 0, "#224 short-list: zero rows is zero either way");
  ok(slVisibleRows(20, -3, false) === 0, "#224 short-list: a negative `initial` clamps to zero, not a negative slice length");
  ok(slVisibleRows(-5, 5, true) === 0, "#224 short-list: a negative `total` clamps to zero");

  const rows = ["Riverside Playhouse", "Main Street Theater", "riverside high school", "Downtown Arena"];
  ok(
    slFilterRows(rows, "riverside", (r) => r).length === 2,
    "#224 short-list: filterRows matches case-insensitively across every row"
  );
  ok(
    slFilterRows(rows, "  ", (r) => r).length === rows.length &&
      slFilterRows(rows, "", (r) => r).length === rows.length,
    "#224 short-list: an empty (or whitespace-only) query returns every row, trimmed first"
  );
  ok(
    slFilterRows(rows, "RIVERSIDE", (r) => r).every((r) => r.toLowerCase().includes("riverside")),
    "#224 short-list: the query itself is case-insensitive too"
  );
  ok(
    slFilterRows(rows, "zzz-no-match", (r) => r).length === 0,
    "#224 short-list: no matches yields an empty array, not the unfiltered list"
  );
  const orderCheck = slFilterRows([3, 1, 2, 4], "", () => "x");
  ok(orderCheck[0] === 3 && orderCheck[3] === 4, "#224 short-list: filterRows preserves row order (a pass, not a re-sort)");

  // visibleGroupFlags: Activity's date-group headers ride with their rows —
  // a header shows only while at least one of its (post-filter) rows is
  // still within the flattened visible count.
  ok(
    JSON.stringify(visibleGroupFlags([2, 3, 1], 4)) === JSON.stringify([true, true, false]),
    "#224 short-list: a group past the visible cutoff (all its rows beyond visibleCount) is hidden"
  );
  ok(
    JSON.stringify(visibleGroupFlags([2, 3, 1], 6)) === JSON.stringify([true, true, true]),
    "#224 short-list: once visibleCount covers every row, every non-empty group shows"
  );
  ok(
    JSON.stringify(visibleGroupFlags([0, 3], 2)) === JSON.stringify([false, true]),
    "#224 short-list: an empty (fully filtered-out) group never shows its header even at index 0"
  );
  ok(
    JSON.stringify(visibleGroupFlags([], 0)) === JSON.stringify([]),
    "#224 short-list: no groups is an empty flag list, not an error"
  );

  const read224 = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const companyPage224 = read224("src/app/(app)/companies/[id]/page.tsx");
  ok(!companyPage224.includes("slice(0, 6)"), "#224: the company record's Site visits card no longer hard-slices to 6");
  ok(companyPage224.includes("ShortList"), "#224: the company record renders cards through ShortList");

  const directory224 = read224("src/app/(app)/companies/page.tsx");
  ok(/sp\.n\b/.test(directory224) && directory224.includes('params.set("n"'), "#224: the Companies directory reads and writes the `?n=` page-size param");
  ok(/showMoreHref|Show more/.test(directory224), "#224: the Companies directory has a Show-more control");

  const venues224 = read224("src/app/(app)/venues/page.tsx");
  ok(/sp\.n\b/.test(venues224) && venues224.includes('p.set("n"'), "#224: the Venues directory reads and writes the `?n=` page-size param");
  ok(!/const PAGE = 200/.test(venues224), "#224: the old hard 200-row cap is gone from Venues");
  ok(/Show more/.test(venues224), "#224: the Venues directory has a Show-more control");

  const shortListComp224 = read224("src/components/short-list.tsx");
  ok(shortListComp224.startsWith('"use client"'), "#224: ShortList is a client component");
  ok(!/@\/lib\/stores\/|@\/db\//.test(shortListComp224), "#224: the client ShortList component imports no store/db module");
}

/* ====== #219 Daylite calendar import — Task 1: parser, classifier, keys, bodies, owners (pure) ======
   Fixture: 11 rows copied from Dropbox "Calendar Events.tsv" (meeting-link
   URLs and a phone number redacted) plus 2 synthetic bad rows. Physical
   lines: header 1; Weekly Sales Meeting ×4 = 2–5; Jena 6; Christmas 7;
   Lincoln 8; RCA 9; Oshkosh 10; Mike 11; Sauk 12; bad date 13; bad duration 14. */
import {
  parseCalendarTsv as dc219Parse,
  splitTsv as dc219Split,
  parseStart as dc219Start,
  classify as dc219Classify,
  eventKey as dc219Key,
  googleEventId as dc219GId,
  googleEventFor as dc219Body,
  matchOwner as dc219Match,
  todayYmdIn as dc219Today,
  addMinutes as dc219Add,
  type DayliteEvent as DC219Event,
} from "@/lib/daylite/calendar-events";

const DC219_FIXTURE =
  [
    "Duration (HH:MM)\t\tCategory\tStart Date\tStatus\tName\t\tDuration\tLinked\tOwner\tDetails\t",
    '01:00\t\t\t"12/25/28, 9:00\u202fAM"\tConfirmed\t"Weekly Sales Meeting"\t\t"1 hour"\t\t"Jeff Chesebro"\thttps://meet.google.com/redacted\t',
    '01:00\t\t\t"12/18/28, 9:00\u202fAM"\tConfirmed\t"Weekly Sales Meeting"\t\t"1 hour"\t\t"Jeff Chesebro"\thttps://meet.google.com/redacted\t',
    '01:00\t\t\t"12/11/28, 9:00\u202fAM"\tConfirmed\t"Weekly Sales Meeting"\t\t"1 hour"\t\t"Jeff Chesebro"\thttps://meet.google.com/redacted\t',
    '01:00\t\t\t"12/4/28, 9:00\u202fAM"\tConfirmed\t"Weekly Sales Meeting"\t\t"1 hour"\t\t"Jeff Chesebro"\thttps://meet.google.com/redacted\t',
    '24:00\t\tPTO\t"9/25/26, 12:00\u202fAM"\tConfirmed\t"Jena Off"\t\t"1 day"\t\t"Jena Tolksdorf"\t\t',
    '48:00\t\t\t"12/24/26, 12:00\u202fAM"\tConfirmed\t"Christmas Holiday"\t\t"2 days"\t\t"Jason Keagy"\t\t',
    '00:30\t\t\t"9/16/26, 2:00\u202fPM"\tConfirmed\t"Lincoln Academy Submittal Review"\t\t"30 minutes"\t"LINCOLN  ACADEMY BELOIT (via MainStage) - Gymnatorium AV, LINCOLN  ACADEMY BELOIT (via MainStage) - Gymnatorium AV"\t"Jason Keagy"\thttps://teams.microsoft.com/meet/redacted\t',
    '32:00\t\tInstall\t"2/11/26, 8:00\u202fAM"\tConfirmed\t"RCA Wire Pulls (Mark, Paul, AJ, Nelson)"\t\t"1 day 8 hours"\t"RICHLAND CENTER HS (via Nexus Solutions) - Auditorium AV"\t"Andrew Herschleb"\t\t',
    '01:30\t\t\t"2/11/26, 12:30\u202fPM"\tConfirmed\t"Oshkosh North Aud & Black Box Projects - First AV Conversation including \\"Shelby\\""\t\t"1 hour 30 minutes"\t"BRAY ARCHITECTS - OSHKOSH NORTH HS - Auditorium & Black Box AV"\t"Jason Keagy"\thttps://teams.microsoft.com/meet/redacted\t',
    '01:00\t\t"Service Call"\t"5/18/26, 8:00\u202fAM"\tConfirmed\t"Mike to Cross Of Christ 8:00 am"\t\t"1 hour"\t\t"Mike Mundth"\t\t',
    '01:00\t\t"Service Call"\t"9/16/26, 9:00\u202fAM"\tConfirmed\t"Sauk Trail Elementary, Middleton HS "\t\t"1 hour"\t\t"Isaac Mittlesteadt"\t"Elementary - mute/unmute passcode   HS - Bluetooth issue, confirm replacement"\t',
    '01:00\t\t\t"13/45/26, 9:00\u202fAM"\tConfirmed\t"Broken date"\t\t"1 hour"\t\t"Jeff Chesebro"\t\t',
    'soon\t\t\t"9/1/26, 9:00\u202fAM"\tConfirmed\t"Broken duration"\t\t""\t\t"Jeff Chesebro"\t\t',
  ].join("\n") + "\n";

{
  const j = (v: unknown) => JSON.stringify(v);

  // splitTsv — tabs inside quotes, "" and \" escapes, physical line numbers.
  const t1 = dc219Split('a\t"b\tc"\n"x ""y"" \\"z\\""\tw\n"p\nq"\tr\ns\tt\n');
  ok(j(t1.map((r) => r.cells)) === j([["a", "b\tc"], ['x "y" "z"', "w"], ["p\nq", "r"], ["s", "t"]]), "#219 splitTsv: tabs in quotes, doubled and backslash-escaped quotes");
  ok(j(t1.map((r) => r.line)) === j([1, 2, 3, 5]), "#219 splitTsv: a quoted newline advances the physical line number");
  ok(dc219Split("﻿h1\th2\n\n").length === 1, "#219 splitTsv: BOM stripped, blank lines dropped");

  // parseStart — U+202F and plain spaces, 12 AM/PM, bad dates.
  ok(j(dc219Start("12/25/28, 9:00\u202fAM")) === j({ y: 2028, m: 12, d: 25, hh: 9, mm: 0 }), "#219 parseStart: U+202F before AM");
  ok(dc219Start("12/25/28, 9:00 AM") !== null, "#219 parseStart: a plain ASCII space before AM also still works");
  ok(dc219Start("12/25/28, 12:00\u202fPM")?.hh === 12 && dc219Start("1/2/25, 12:05\u202fAM")?.hh === 0, "#219 parseStart: 12 PM is noon, 12 AM is midnight");
  ok(j(dc219Start("3/1/2027, 7:15\u202fpm")) === j({ y: 2027, m: 3, d: 1, hh: 19, mm: 15 }), "#219 parseStart: four-digit year and lowercase pm");
  ok(dc219Start("2/30/26, 9:00\u202fAM") === null && dc219Start("13/45/26, 9:00\u202fAM") === null && dc219Start("") === null, "#219 parseStart: impossible dates are null");
  ok(DC219_FIXTURE.includes("\u202f"), "#219 fixture carries the real U+202F");

  // parseCalendarTsv over the fixture.
  const p = dc219Parse(DC219_FIXTURE);
  ok(p.rows.length === 11 && p.errors.length === 2, "#219 parse: 11 readable rows, 2 errors");
  ok(j(p.errors.map((e) => e.line)) === "[13,14]" && /start date/.test(p.errors[0].reason) && /duration/.test(p.errors[1].reason), "#219 parse: bad rows reported with their line and reason");
  const byName = (s: string) => p.rows.find((r) => r.name.startsWith(s))!;
  const jena = byName("Jena Off");
  ok(jena.allDay && jena.durationMin === 1440 && jena.category === "PTO" && jena.line === 6 && j(jena.start) === j({ y: 2026, m: 9, d: 25, hh: 0, mm: 0 }), "#219 parse: 24:00 at midnight is a one-day all-day event");
  const xmas = byName("Christmas");
  ok(xmas.allDay && xmas.durationMin === 2880, "#219 parse: 48:00 at midnight is a multi-day all-day event");
  const lincoln = byName("Lincoln Academy");
  ok(!lincoln.allDay && lincoln.durationMin === 30 && lincoln.start.hh === 14 && lincoln.linked.startsWith("LINCOLN  ACADEMY") && lincoln.category === "", "#219 parse: a timed 30-minute row with Linked kept verbatim and a blank Category");
  const rca = byName("RCA Wire Pulls");
  ok(!rca.allDay && rca.durationMin === 1920 && rca.category === "Install", "#219 parse: 32:00 from 8 AM stays a timed event (not midnight)");
  ok(byName("Oshkosh").name.endsWith('including "Shelby"'), "#219 parse: Daylite's \\\" escape becomes a plain quote");
  ok(byName("Mike to Cross").category === "Service Call" && byName("Mike to Cross").owner === "Mike Mundth", "#219 parse: a quoted Category is unquoted");
  const sauk = byName("Sauk Trail");
  ok(sauk.name === "Sauk Trail Elementary, Middleton HS" && sauk.details.includes("passcode   HS"), "#219 parse: cells trimmed, inner spacing in Details kept");
  const missing = dc219Parse("Start Date\tName\n1/1/26, 9:00 AM\tX\n");
  ok(missing.rows.length === 0 && missing.errors.length === 1 && /Owner/.test(missing.errors[0].reason), "#219 parse: a file without the required columns is refused by name");

  // classify — the series threshold.
  const c = dc219Classify(p.rows);
  ok(c.series.length === 1 && j(c.series[0]) === j({ owner: "Jeff Chesebro", name: "Weekly Sales Meeting", count: 4 }) && c.oneOffs.length === 7, "#219 classify: 4 × same owner + name is a series; the other 7 are one-offs");
  const ev = (over: Partial<DC219Event>): DC219Event => ({ line: 0, owner: "Pat Lee", name: "Payroll", category: "", start: { y: 2026, m: 1, d: 1, hh: 9, mm: 0 }, durationMin: 60, allDay: false, linked: "", details: "", status: "", ...over });
  const three = [ev({}), ev({ name: "payroll" }), ev({ name: " PAYROLL " })];
  ok(dc219Classify(three).series.length === 0 && dc219Classify(three).oneOffs.length === 3, "#219 classify: 3 occurrences is not a series");
  const four = [...three, ev({ owner: "pat  lee" })];
  ok(dc219Classify(four).series.length === 1 && dc219Classify(four).oneOffs.length === 0, "#219 classify: the 4th occurrence (case/space-insensitive owner + name) makes all four a series");

  // eventKey — stable, normalized, 24 hex; the Google id is base32hex.
  const weekly = p.rows.find((r) => r.name === "Weekly Sales Meeting" && r.start.d === 25)!;
  ok(dc219Key(weekly) === "07afd50421a5cd9d115777d1", "#219 eventKey: golden value (sha256 of owner|name|start|durationMin, normalized) — never change it, the dedup blob depends on it");
  ok(dc219Key({ ...weekly, name: "  weekly  SALES meeting " }) === dc219Key(weekly), "#219 eventKey: name case and spacing do not change the key");
  ok(dc219Key({ ...weekly, durationMin: 90 }) !== dc219Key(weekly) && dc219Key({ ...weekly, owner: "Jason Keagy" }) !== dc219Key(weekly) && dc219Key({ ...weekly, start: { ...weekly.start, mm: 30 } }) !== dc219Key(weekly), "#219 eventKey: owner, start and duration each change the key");
  ok(/^[a-v0-9]{5,1024}$/.test(dc219GId(dc219Key(weekly))) && dc219GId("abc").startsWith("dlc"), "#219 googleEventId: dlc + key is a valid Google event id");

  // addMinutes — wall-clock arithmetic, no zone applied.
  ok(j(dc219Add({ y: 2026, m: 3, d: 8, hh: 1, mm: 30 }, 60)) === j({ y: 2026, m: 3, d: 8, hh: 2, mm: 30 }), "#219 addMinutes: wall-clock math ignores the DST jump (Google applies the zone)");
  ok(j(dc219Add({ y: 2025, m: 12, d: 31, hh: 23, mm: 30 }, 60)) === j({ y: 2026, m: 1, d: 1, hh: 0, mm: 30 }), "#219 addMinutes: crosses a year boundary");

  // googleEventFor — summary, description, all-day vs timed.
  const bJena = dc219Body(jena);
  ok(j(bJena.start) === j({ date: "2026-09-25" }) && j(bJena.end) === j({ date: "2026-09-26" }) && bJena.summary === "[PTO] Jena Off" && bJena.description === "Imported from Daylite", "#219 body: one-day all-day, exclusive end date, [Category] prefix");
  ok(j(dc219Body(xmas).end) === j({ date: "2026-12-26" }), "#219 body: a 2-day all-day event ends (exclusive) two days later");
  const bLin = dc219Body(lincoln);
  ok(j(bLin.start) === j({ dateTime: "2026-09-16T14:00:00", timeZone: "America/Chicago" }) && j(bLin.end) === j({ dateTime: "2026-09-16T14:30:00", timeZone: "America/Chicago" }), "#219 body: timed events are local wall-clock + America/Chicago, never UTC");
  ok(bLin.summary === "Lincoln Academy Submittal Review" && bLin.description === lincoln.details + "\n\nLinked: " + lincoln.linked + "\n\nImported from Daylite", "#219 body: no category → no prefix; description = details, Linked, footer");
  ok(bLin.id === "dlc" + dc219Key(lincoln), "#219 body: carries the deterministic Google id");
  ok(dc219Body(rca).end && j(dc219Body(rca).end) === j({ dateTime: "2026-02-12T16:00:00", timeZone: "America/Chicago" }), "#219 body: a 32-hour timed event ends the next day at 16:00");

  // matchOwner — exact, then first + last, never ambiguous.
  const roster = [
    { id: "u1", name: "Jeff Chesebro" },
    { id: "u2", name: "Jason M. Keagy" },
    { id: "u3", name: "Chris Mittlesteadt" },
    { id: "u4", name: "Isaac Mittlesteadt" },
  ];
  const m1 = dc219Match("jeff  chesebro", roster);
  ok(m1.ok && m1.user.id === "u1", "#219 matchOwner: exact full name, case/space-insensitive");
  const m2 = dc219Match("Jason Keagy", roster);
  ok(m2.ok && m2.user.id === "u2", "#219 matchOwner: first + last token when the roster has a middle initial");
  const m3 = dc219Match("Isaac Mittlesteadt", roster);
  ok(m3.ok && m3.user.id === "u4", "#219 matchOwner: a shared last name does not confuse two people");
  const m4 = dc219Match("Mike Mundth", roster);
  ok(!m4.ok && /No team member/.test(m4.reason), "#219 matchOwner: no user → reported, not guessed");
  const m5 = dc219Match("Pat Lee", [{ id: "a", name: "Pat Lee" }, { id: "b", name: "pat lee" }]);
  ok(!m5.ok && /More than one/.test(m5.reason), "#219 matchOwner: two matches is a refusal, never a pick");

  // todayYmdIn — the business-zone date, not the server's.
  ok(dc219Today(Date.UTC(2026, 8, 26, 3, 0)) === "2026-09-25", "#219 todayYmdIn: 03:00 UTC is still the previous day in Chicago");
}

/* ====== #219 Daylite calendar import — Task 2: preview, pending selection, batch runner (fake insert), admin gate ======
   runCalendarBatch never touches Google here: insert/record/now are fakes.
   The DB half (previewCalendarImport / importCalendarBatch) runs on the
   harness's scratch PGlite with the seeded roster and no mailbox
   connections, so nothing can be written anywhere. */
import {
  DAYLITE_CALENDAR_BLOB as DC219_BLOB,
  OWNER_STOP_AFTER as DC219_STOP_AFTER,
  buildPreview as dc219Preview,
  isAlreadyExists as dc219Is409,
  isQuotaStop as dc219IsQuota,
  runCalendarBatch as dc219Run,
  sanitizeImported as dc219Sanitize,
  selectPending as dc219Select,
  type BatchDeps as DC219Deps,
  type ImportedMap as DC219Map,
  type PendingEvent as DC219Pending,
} from "@/lib/daylite/calendar-batch";
import { importCalendarBatch as dc219ImportBatch, previewCalendarImport as dc219PreviewDb } from "@/lib/daylite/calendar-import";
import { setBlob as setBlob219 } from "@/db/doc-store";

async function dayliteCalendarAsyncChecks219(): Promise<void> {
  const j = (v: unknown) => JSON.stringify(v);
  const read = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const parsed = dc219Parse(DC219_FIXTURE);
  const users = [
    { id: "u1", name: "Jeff Chesebro" },
    { id: "u5", name: "Jason Keagy" },
    { id: "u6", name: "Isaac Mittlesteadt" },
    { id: "u7", name: "Jena Tolksdorf" },
  ];
  const keyOf = (prefix: string) => dc219Key(parsed.rows.find((r) => r.name.startsWith(prefix))!);
  const lincolnKey = keyOf("Lincoln Academy");

  // --- buildPreview (pure)
  const pv = dc219Preview(parsed, users, { u1: "not-connected", u5: "connected", u6: "no-calendar", u7: "gmail-off" }, { [lincolnKey]: { eventId: "x", owner: "Jason Keagy", at: 1 } }, { fromYmd: null });
  const own = (name: string) => pv.owners.find((o) => o.owner === name)!;
  ok(j(pv.owners.map((o) => o.owner)) === j(["Andrew Herschleb", "Isaac Mittlesteadt", "Jason Keagy", "Jeff Chesebro", "Jena Tolksdorf", "Mike Mundth"]), "#219 preview: one row per owner, sorted");
  ok(own("Jason Keagy").oneOffs === 3 && own("Jason Keagy").alreadyImported === 1 && own("Jason Keagy").toImport === 2 && own("Jason Keagy").defaultInclude, "#219 preview: already-imported keys counted; connected owner included by default");
  ok(own("Isaac Mittlesteadt").calendar === "no-calendar" && !own("Isaac Mittlesteadt").defaultInclude, "#219 preview: a mailbox without calendar scope is not included");
  ok(own("Jeff Chesebro").oneOffs === 0 && own("Jeff Chesebro").seriesRows === 4 && j(own("Jeff Chesebro").series) === j([{ name: "Weekly Sales Meeting", count: 4 }]), "#219 preview: series listed with counts per owner");
  ok(own("Mike Mundth").calendar === "no-user" && own("Mike Mundth").userId === null && /No team member/.test(own("Mike Mundth").matchNote), "#219 preview: an unmatched owner is reported");
  ok(pv.totals.seriesCount === 1 && pv.totals.seriesRows === 4 && pv.totals.oneOffs === 7 && pv.totals.alreadyImported === 1 && pv.errors.length === 2, "#219 preview: totals and parse errors");
  const pvToday = dc219Preview(parsed, users, {}, {}, { fromYmd: "2026-09-01" });
  ok(pvToday.totals.oneOffs === 4 && pvToday.fromYmd === "2026-09-01", "#219 preview: 'from today on' drops earlier one-offs (Jena, Christmas, Lincoln, Sauk remain)");

  // --- selectPending (pure) — only the owner's own connected mailbox.
  const mailboxes = { u5: "personal:u5", u6: "personal:u6" };
  const all = dc219Select(parsed, users, mailboxes, {}, { fromYmd: null, owners: ["Jason Keagy", "Isaac Mittlesteadt", "Jena Tolksdorf", "Mike Mundth"], skipKeys: [] });
  ok(j(all.map((p) => p.body.summary)) === j(["Christmas Holiday", "Lincoln Academy Submittal Review", "Oshkosh North Aud & Black Box Projects - First AV Conversation including \"Shelby\"", "[Service Call] Sauk Trail Elementary, Middleton HS"]), "#219 pending: one-offs of included owners with a connected calendar, file order");
  ok(all.every((p) => p.mailboxKey === (p.owner === "Jason Keagy" ? "personal:u5" : "personal:u6")), "#219 pending: each event targets its own owner's mailbox — never someone else's");
  ok(dc219Select(parsed, users, mailboxes, {}, { fromYmd: null, owners: ["isaac  mittlesteadt"], skipKeys: [] }).length === 1, "#219 pending: the owners filter is case/space-insensitive");
  ok(dc219Select(parsed, users, mailboxes, {}, { fromYmd: "2026-09-01", owners: ["Jason Keagy", "Isaac Mittlesteadt"], skipKeys: [] }).length === 3, "#219 pending: the date filter applies");
  ok(dc219Select(parsed, users, mailboxes, {}, { fromYmd: null, owners: ["Jason Keagy"], skipKeys: [lincolnKey] }).length === 2, "#219 pending: skipKeys (failed this run) are left out");

  // --- runCalendarBatch with fakes
  const clock = { t: 0 };
  const make = (insert: DC219Deps["insert"], store: DC219Map): DC219Deps => ({
    insert,
    record: async (patch) => {
      Object.assign(store, patch);
    },
    now: () => clock.t,
  });
  const calls: { mailboxKey: string; id: string; start: unknown }[] = [];
  const okInsert: DC219Deps["insert"] = async (mailboxKey, body) => {
    calls.push({ mailboxKey, id: body.id, start: body.start });
    clock.t += 100;
    return { id: "g-" + calls.length };
  };

  const store1: DC219Map = {};
  const r1 = await dc219Run(all, make(okInsert, store1));
  ok(r1.stoppedFor === "done" && r1.written === 4 && r1.remaining === 0 && r1.pendingAtStart === 4 && Object.keys(store1).length === 4, "#219 batch: writes every pending event and records each key");
  ok(store1[lincolnKey]?.eventId === "g-2" && store1[lincolnKey]?.owner === "Jason Keagy", "#219 batch: the record maps key → Google event id + owner");
  ok(calls.every((c) => /^dlc[0-9a-f]{24}$/.test(c.id)) && j(calls[1].start) === j({ dateTime: "2026-09-16T14:00:00", timeZone: "America/Chicago" }), "#219 batch: bodies carry the deterministic id and wall-clock Chicago times");
  const rerun = dc219Select(parsed, users, mailboxes, store1, { fromYmd: null, owners: ["Jason Keagy", "Isaac Mittlesteadt"], skipKeys: [] });
  ok(rerun.length === 0, "#219 batch: a re-run over the recorded map selects nothing — importing twice never duplicates");

  const store409: DC219Map = {};
  const r409 = await dc219Run(all.slice(0, 1), make(async () => {
    throw new Error('Calendar API /calendars/primary/events?sendUpdates=none → 409 {"error":{"code":409,"message":"The requested identifier already exists."}}');
  }, store409));
  ok(r409.alreadyThere === 1 && r409.failed === 0 && store409[all[0].key]?.eventId === all[0].body.id, "#219 batch: a 409 on our deterministic id is recorded as already in Google");

  let n = 0;
  const storeQ: DC219Map = {};
  const rq = await dc219Run(all, make(async () => {
    n++;
    if (n === 2) throw new Error('Calendar API /calendars/primary/events?sendUpdates=none → 403 {"error":{"errors":[{"reason":"rateLimitExceeded"}]}}');
    return { id: "g" + n };
  }, storeQ));
  ok(rq.stoppedFor === "quota" && rq.written === 1 && rq.remaining === 3 && rq.failed === 0 && rq.failedKeys.length === 0 && Object.keys(storeQ).length === 1 && rq.quotaMessage.includes("rateLimitExceeded"), "#219 batch: a rate-limit error stops the batch; the event stays pending, not failed");
  ok(dc219IsQuota(new Error('→ 403 {"error":{"errors":[{"reason":"quotaExceeded","message":"Calendar usage limits exceeded."}]}}')) && dc219IsQuota(new Error("→ 429 Too Many Requests")) && !dc219IsQuota(new Error("→ 500 backend")), "#219 isQuotaStop: quotaExceeded / usage limits / 429 stop; a 500 does not");
  ok(dc219IsQuota(new Error('→ 403 {"error":{"errors":[{"reason":"userRateLimitExceeded"}]}}')), "#219 isQuotaStop: userRateLimitExceeded also stops for quota");
  ok(!dc219IsQuota(new Error('→ 403 {"error":{"errors":[{"domain":"usageLimits","reason":"accessNotConfigured","message":"Calendar API has not been used in this project."}]}}')) && !dc219IsQuota(new Error('→ 403 {"error":{"errors":[{"domain":"usageLimits","reason":"dailyLimitExceededUnreg"}]}}')), "#219 isQuotaStop: accessNotConfigured / dailyLimitExceededUnreg (also domain usageLimits) are per-owner failures, not a quota pause");
  ok(dc219Is409(new Error("Calendar API x → 409 {}")) && !dc219Is409(new Error("Calendar API x → 404 {}")), "#219 isAlreadyExists: matches only a 409");

  clock.t = 0;
  const slow: DC219Deps["insert"] = async () => {
    clock.t += 5_000;
    return { id: "s" };
  };
  const rb = await dc219Run(all, make(slow, {}), 20_000);
  ok(rb.stoppedFor === "budget" && rb.written === 3 && rb.remaining === 1, "#219 batch: stops starting inserts when a worst-case insert no longer fits the budget");
  clock.t = 0;
  const rb1 = await dc219Run(all, make(slow, {}), 1_000);
  ok(rb1.written === 1 && rb1.stoppedFor === "budget" && rb1.remaining === 3, "#219 batch: the first insert always runs (forward progress)");

  const storeF: DC219Map = {};
  const rf = await dc219Run(all, make(async (_k, body) => {
    if (body.summary.startsWith("Lincoln")) throw new Error("Calendar API x → 500 backendError");
    return { id: "ok" };
  }, storeF));
  ok(rf.written === 3 && rf.failed === 1 && j(rf.failedKeys) === j([lincolnKey]) && rf.byOwner["Jason Keagy"].failed === 1 && rf.byOwner["Jason Keagy"].lastError.includes("500") && !storeF[lincolnKey], "#219 batch: a non-quota error is counted per owner, not recorded, and its key returned for skipKeys");

  const synth = (owner: string, i: number): DC219Pending => ({
    key: i.toString(16).padStart(24, "0"),
    owner,
    mailboxKey: "personal:" + owner,
    body: { id: "dlc" + i.toString(16).padStart(24, "0"), summary: owner + i, description: "", start: { date: "2026-01-01" }, end: { date: "2026-01-02" } },
  });
  const mixed = [...Array.from({ length: 7 }, (_, i) => synth("X", i)), synth("Y", 99)];
  const rs = await dc219Run(mixed, make(async (mailboxKey) => {
    if (mailboxKey === "personal:X") throw new Error("Mailbox not connected: personal:X");
    return { id: "y" };
  }, {}));
  ok(rs.failed === DC219_STOP_AFTER && j(rs.stoppedOwners) === j(["X"]) && rs.written === 1 && rs.stoppedFor === "done" && rs.remaining === 0, "#219 batch: 5 consecutive failures stop that owner; other owners carry on");

  let threw = false;
  try {
    await dc219Run(all.slice(0, 1), { insert: async () => ({ id: "z" }), record: async () => { throw new Error("db down"); }, now: () => 0 });
  } catch {
    threw = true;
  }
  ok(threw, "#219 batch: a failed blob write aborts the batch (a resume re-inserts → 409 → recorded)");

  ok(j(Object.keys(dc219Sanitize({ a: { eventId: "e", owner: "o", at: 1 }, b: null, c: { owner: "x" }, d: "junk" }))) === j(["a"]), "#219 sanitizeImported: drops cleared (null) and malformed entries");

  // --- DB half: the seeded roster, no mailbox connections.
  await setBlob219(DC219_BLOB, { [lincolnKey]: { eventId: "dlc-test", owner: "Jason Keagy", at: 1 } });
  const live = await dc219PreviewDb(DC219_FIXTURE, { fromToday: false });
  const jason = live.owners.find((o) => o.owner === "Jason Keagy")!;
  ok(jason.userName === "Jason Keagy" && jason.alreadyImported === 1 && ["gmail-off", "not-connected"].includes(jason.calendar) && !jason.defaultInclude, "#219 previewCalendarImport: matches the seeded roster, reads the blob, and reports no calendar");
  ok(live.owners.find((o) => o.owner === "Mike Mundth")!.calendar === "no-user", "#219 previewCalendarImport: an owner outside the roster is no-user");
  let inserted = 0;
  const liveRun = await dc219ImportBatch(DC219_FIXTURE, { fromToday: false, owners: ["Jason Keagy", "Isaac Mittlesteadt"], skipKeys: [] }, {
    insert: async () => {
      inserted++;
      return { id: "never" };
    },
    record: async () => {},
    now: () => 0,
  });
  ok(liveRun.pendingAtStart === 0 && inserted === 0 && liveRun.stoppedFor === "done", "#219 importCalendarBatch: no connected calendar → nothing is written anywhere");
  await setBlob219(DC219_BLOB, { [lincolnKey]: null });

  // --- source checks: the zoned insert and the admin gate.
  const cal = read("src/lib/google/calendar.ts");
  ok(/export async function insertZonedEvent\(\s*mailboxKey: string,\s*body: ZonedEventBody\s*\)/.test(cal) && cal.includes('"/calendars/primary/events?sendUpdates=none"'), "#219 insertZonedEvent: primary calendar, no invite emails");
  const act = read("src/app/(app)/import/daylite/calendar/actions.ts");
  ok(act.startsWith('"use server"'), "#219 actions: a server-action module");
  ok(
    (act.match(/export async function \w+\([^)]*\)[^{]*\{\s*await requirePerm\("manage_users"\);/g) || []).length === 2 &&
      (act.match(/^export async function/gm) || []).length === 2,
    "#219 actions: both actions call requirePerm(\"manage_users\") first, outside any try"
  );
  const glue = read("src/lib/daylite/calendar-import.ts");
  ok(glue.includes('if (states[u.id] === "connected") mailboxByUserId[u.id] = personalKey(u.id);'), "#219 import: only a connected owner's OWN personal mailbox is ever targeted");
}

/* ====== #219 Daylite calendar import — Task 3: the screen (source checks) ====== */
{
  const read = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const page = read("src/app/(app)/import/daylite/calendar/page.tsx");
  ok(page.includes('await requirePerm("manage_users")') && page.includes("export const maxDuration = 60"), "#219 T3: the page is admin-gated and gets the 60 s server-action ceiling");
  const client = read("src/app/(app)/import/daylite/calendar/calendar-client.tsx");
  ok(client.startsWith('"use client"'), "#219 T3: the import screen is a client component");
  const valueImports = [...client.matchAll(/^import (?!type )[^;]*?from "([^"]+)"/gm)].map((m) => m[1]);
  ok(valueImports.length > 0 && valueImports.every((s) => s === "react" || s === "./actions"), "#219 T3: the client imports values only from react and its own actions — no store, db or server module");
  ok(client.includes("skipKeys: skipRef.current") && client.includes('b.stoppedFor === "quota"') && client.includes("b.stoppedOwners"), "#219 T3: the loop re-posts with failed keys skipped, pauses on quota, drops stopped owners");
  ok(client.includes("Only events from today on") && client.includes("Repeating series skipped"), "#219 T3: the from-today option and the skipped-series list are on the page");
  const hist = read("src/app/(app)/import/daylite/page.tsx");
  ok(hist.includes('href="/import/daylite/calendar"'), "#219 T3: /import/daylite links to the calendar import");
}

/* ======================================================================
   #226 Grid device types — Task 1: the pure model (seeds, suggestion
   rules on realistic raw categories incl. the dealer-sheet per-brand
   defaults, the map rules, review rows, list helpers, the scope fix).
   ====================================================================== */
import {
  SEED_DEVICE_TYPES as dt226Seed, DEFAULT_TYPE_ICONS as dt226Icons, deviceTypesFrom as dt226From, slugOf as dt226Slug,
  normalizeRawCategory as dt226Norm, suggestDeviceType as dt226Suggest, typeOfPart as dt226TypeOf, scopeOfType as dt226ScopeOf,
  keywordScopeOf as dt226Keyword, autoTypeEntries as dt226Auto, sanitizeTypeMap as dt226Sanitize, typeReviewRows as dt226Rows,
  acceptSuggestionEntries as dt226Accept, assignEntries as dt226Assign, mergeTypeEntries as dt226Merge,
  cleanDeviceTypesInput as dt226Clean, typeLayerRows as dt226Layers, typeKeyOfPart as dt226KeyOf, typeLabel as dt226Label,
  deviceTypeIcons as dt226TypeIcons, withTypeIcons as dt226WithIcons, cleanIdList as dt226Ids, withRecent as dt226Recent,
  toggleInList as dt226Toggle, UNMAPPED_TYPE as DT226_UNMAPPED, ASSEMBLY_TYPE as DT226_ASM, type TypeMap as DT226Map,
  mapKeyOf as dt226MapKey,
} from "@/lib/design/device-types";
import { gridPartsFrom as dt226Parts } from "@/lib/design/grid-parts";
import { scopeOfPart as dt226ScopeOfPart } from "@/lib/design/grid-scopes";
import { isGridIconId as dt226IsIcon } from "@/lib/design/grid-icons";

{
  const j = (x: unknown) => JSON.stringify(x);
  ok(dt226Seed.length === 25 && new Set(dt226Seed.map((t) => t.key)).size === 25, "#226 model: 25 seeded device types with unique keys");
  ok(
    dt226Seed.map((t) => t.key).join(",") ===
      "fixtures,dimming-power,control-networking,lighting-accessories,hoists-motors,truss-pipe,rigging-hardware,rigging-control,drapery,tracks-hardware,speakers,microphones,mixing-processing,amplifiers,assistive-listening,intercom,displays-projectors,screens-lifts,cameras,switching-distribution,cable-connectors,racks-cases,power-distribution,networking,parts-consumables",
    "#226 model: seed keys are slugs of the labels, in the spec's order"
  );
  ok(dt226Seed.filter((t) => t.scope === "Unscoped").map((t) => t.label).join("|") === "Cable & Connectors|Racks & Cases|Power Distribution|Networking|Parts & Consumables",
    "#226 model: the General five are Unscoped");
  ok(dt226Seed.every((t) => dt226IsIcon(dt226Icons[t.key])), "#226 model: every seeded type has a registered default icon");
  ok(dt226Slug("Dimming & Power") === "dimming-power" && dt226Slug("  A/V  Racks!! ") === "a-v-racks", "#226 model: slugOf");
  ok(dt226Norm("  Motorized   HOIST ") === "motorized hoist" && dt226Norm(null) === "" && dt226Norm("__proto__") === "",
    "#226 model: normalizeRawCategory trims, lowercases, collapses whitespace (and refuses __proto__)");

  // seed / sanitize / merge
  ok(j(dt226From(undefined)) === j(dt226Seed) && dt226From(undefined) !== dt226From(undefined), "#226 model: absent → fresh seed copies");
  const stored = dt226From([
    { key: "fixtures", label: "Luminaires", scope: "Lighting", order: 5, icon: "wash" },
    { key: "fixtures", label: "Dup", scope: "Lighting", order: 1 },
    { key: "Bad Key", label: "x", scope: "Lighting", order: 1 },
    { key: "fog", label: "Fog & Haze", scope: "Lighting", order: 900, archived: true },
    { key: "x", label: "", scope: "Lighting", order: 2 },
    { key: "y", label: "Y", scope: "Nope", order: 2 },
  ]);
  ok(stored[0].key === "fixtures" && stored[0].label === "Luminaires" && stored[0].icon === "wash", "#226 model: a stored type keeps its rename and icon");
  ok(stored.filter((t) => t.key === "fixtures").length === 1 && !stored.some((t) => ["Bad Key", "x", "y"].includes(t.key)),
    "#226 model: duplicate keys, bad keys, blank labels and unknown scopes are dropped");
  ok(stored.length === 26 && stored.some((t) => t.key === "fog" && t.archived) && stored.some((t) => t.key === "parts-consumables"),
    "#226 model: seeds missing from a stored list are merged back in; archived customs stay");

  // suggestion rules — realistic raw categories (scripts/catalog-import-data.json,
  // the dealer-sheet BRAND_CATEGORY defaults in scripts/convert-dealer-sheets.py,
  // and common vendor-sheet section names)
  const CASES: Array<[string, string | null, "high" | "low" | null]> = [
    ["Fixtures", "fixtures", "high"], ["Track", "tracks-hardware", "low"], ["Pipe", "truss-pipe", "high"],
    ["Loftblocks", "rigging-hardware", "high"], ["Headblocks", "rigging-hardware", "high"], ["Mule Block", "rigging-hardware", "high"],
    ["Arbor", "rigging-hardware", "high"], ["Standard Arbor", "rigging-hardware", "high"], ["Front Arbor", "rigging-hardware", "high"],
    ["Floor Block", "rigging-hardware", "high"], ["Manual Hoist", "hoists-motors", "high"], ["Motorized Hoist", "hoists-motors", "high"],
    ["Rope Lock", "rigging-hardware", "high"], ["Shoes", "rigging-hardware", "high"],
    // fix wave 2 (#226): "Hardware" alone is as generic as bare "Mounts" —
    // "Mounting Hardware", "Curtain Hardware" name no device — so it's low,
    // same as the pre-existing bare "Rigging" row below, not the stale
    // "high" this row used to assert.
    ["Hardware", "rigging-hardware", "low"],
    ["Wire Mesh Strain Reliefs", "rigging-hardware", "high"], ["Curtains", "drapery", "high"],
    ["Networking", "networking", "high"], ["Racks", "racks-cases", "high"], ["Rack Accessories", "racks-cases", "high"],
    ["Rack Options", "racks-cases", "high"], ["Connectors", "cable-connectors", "high"], ["Cable Assemblies", "cable-connectors", "high"],
    ["Lighting Controls", "control-networking", "high"], ["Video Controls", "switching-distribution", "high"], ["Speakers", "speakers", "high"],
    ["Audio Controls", "mixing-processing", "high"], ["Power Distribution", "power-distribution", "high"], ["Power Controls", "dimming-power", "high"],
    ["Cable", "cable-connectors", "high"], ["Lamp", "parts-consumables", "high"],
    // fix wave 2 (#226): "Cases" and "Parts" are the same generic-container
    // class as "Mounts"/"Hardware" — "Speaker Cases", "Rigging Parts" name
    // no device by the container word alone — so both are low, not the
    // stale "high" these two rows used to assert. "Carts" is unchanged: a
    // cart is a specific enough object, not a modifier-dependent container.
    ["Cases", "racks-cases", "low"], ["Carts", "racks-cases", "high"],
    ["Parts", "parts-consumables", "low"], ["Distro Boxes", "power-distribution", "high"], ["Cable Crossovers", "cable-connectors", "high"],
    ["Wire", "cable-connectors", "high"], ["Control", "control-networking", "low"], ["Architectural", "fixtures", "low"],
    ["Uncategorized", null, null], ["Accessory", null, null], ["Atmospherics", null, null], ["Fabric", null, null], ["Labor", null, null],
    // dealer-sheet per-brand defaults
    ["Audio", null, null], ["AV Control", null, null], ["Networked AV", null, null], ["Video", null, null],
    ["Displays", "displays-projectors", "high"], ["LED Video", "displays-projectors", "high"], ["Screens & Lifts", "screens-lifts", "high"],
    ["AV Distribution", "switching-distribution", "high"], ["AV Infrastructure", null, null], ["Power", "power-distribution", "low"],
    ["Assistive Listening", "assistive-listening", "high"], ["Comms", "intercom", "high"], ["Stage Accessories", null, null],
    ["Rigging", "rigging-hardware", "low"], ["Staging", null, null], ["Lighting Control", "control-networking", "high"], ["Lighting", "fixtures", "low"],
    // common section names
    ["Moving Lights", "fixtures", "high"], ["Wireless Microphones", "microphones", "high"], ["Wireless", "microphones", "low"],
    ["Wireless Access Points", "networking", "high"], ["Power Amplifiers", "amplifiers", "high"], ["Digital Mixing Consoles", "mixing-processing", "high"],
    ["Lighting Consoles", "control-networking", "high"], ["PTZ Cameras", "cameras", "high"], ["Projection Screens", "screens-lifts", "high"],
    ["HDBaseT Extenders", "switching-distribution", "high"], ["Dimmers", "dimming-power", "high"], ["Chain Hoists", "hoists-motors", "high"],
    ["Motor Controllers", "rigging-control", "high"], ["Truss", "truss-pipe", "high"], ["Velour Curtains", "drapery", "high"],
    ["Travelers", "tracks-hardware", "high"], ["Clear-Com", "intercom", "high"], ["Gobos", "lighting-accessories", "high"],
    ["Clamps", "lighting-accessories", "low"], ["Network Switches", "networking", "high"], ["Stage Monitors", "speakers", "high"],
    ["Monitors", "displays-projectors", "low"], ["  motorized   HOIST ", "hoists-motors", "high"],
    // fix wave #226: head-noun precedence — a cable/connector/adapter word
    // always wins, whatever else the category names
    ["DMX Cable", "cable-connectors", "high"], ["5-Pin DMX Cable", "cable-connectors", "high"],
    ["Speaker Cable", "cable-connectors", "high"], ["HDMI Cable", "cable-connectors", "high"],
    ["XLR Adapters", "cable-connectors", "high"], ["Power Cable", "cable-connectors", "high"],
    ["Cat6 Cable", "cable-connectors", "high"], ["Speakon Connectors", "cable-connectors", "high"],
    // fix wave #226: a specific phrase still resolves correctly (regression
    // guard — these already worked, this locks them in)
    ["Lighting Console", "control-networking", "high"], ["Audio Console", "mixing-processing", "high"],
    ["Mixing Console", "mixing-processing", "high"], ["Rigging Hardware", "rigging-hardware", "high"],
    ["Curtain Track", "tracks-hardware", "high"], ["Motor Control", "rigging-control", "high"],
    ["Hoist Controller", "rigging-control", "high"],
    // fix wave #226: ambiguous head nouns alone are never confidently wrong
    ["Console", "control-networking", "low"], ["Clamp", "lighting-accessories", "low"],
    ["Controls", "control-networking", "low"], ["Accessories", null, null],
    // fix wave 2 (#226): a mount/bracket is a hookup accessory for some
    // OTHER device, never a device of its own — the modifier says which
    // device, and even a good modifier match stays low (never the "high"
    // the old bare-"mounts?" rigging-hardware rule wrongly gave every one
    // of these). Bare "Mounts"/"Mount"/"Rigid Mount"/"Brackets" carry no
    // device information at all and get no suggestion.
    ["Mounts", null, null], ["Mount", null, null], ["Rigid Mount", null, null], ["Brackets", null, null],
    ["Speaker Mounts", "speakers", "low"], ["Projector Mounts", "displays-projectors", "low"],
    ["TV Mounts", "displays-projectors", "low"], ["Display Mounts", "displays-projectors", "low"],
    ["Monitor Mounts", "displays-projectors", "low"], ["Camera Mounts", "cameras", "low"],
    ["Truss Mounts", "truss-pipe", "low"], ["Pipe Mounts", "truss-pipe", "low"],
    ["Fixture Mounts", "lighting-accessories", "low"], ["Light Mounts", "lighting-accessories", "low"],
    // only an explicit rigging word keeps a mount in rigging-hardware, and
    // still only at low confidence, never high
    ["Rigging Mounts", "rigging-hardware", "low"], ["Beam Clamps & Mounts", "rigging-hardware", "low"],
    // regression guard: "Truss Clamps" is untouched by the mount/bracket
    // fix (no "mount"/"bracket" word) and stays truss-pipe high — a truss
    // clamp genuinely is truss/rigging hardware, domain-plausible even
    // though "clamps" (not "truss") is the grammatical head noun.
    ["Truss Clamps", "truss-pipe", "high"],
  ];
  for (const [cat, key, conf] of CASES) {
    const s = dt226Suggest(cat);
    ok(key === null ? s === null : s?.typeKey === key && s.confidence === conf,
      `#226 suggest: "${cat}" → ${key ?? "null"}${conf ? ` (${conf})` : ""} (got ${j(s)})`);
  }
  const lightingTrack = dt226Suggest("Lighting Track");
  ok(!(lightingTrack?.typeKey === "tracks-hardware" && lightingTrack.confidence === "high"),
    `#226 suggest: "Lighting Track" is never confidently mis-typed as curtain-track hardware (low tracks-hardware or a lighting type is fine; got ${j(lightingTrack)})`);
  ok(j(dt226Suggest("Audio", ["QSC K12.2 powered loudspeaker", "QSC KS118 subwoofer", "Shure SM58 microphone"])) === j({ typeKey: "speakers", confidence: "low" }),
    "#226 suggest: sample descriptions vote a LOW-confidence type when the category says nothing");
  ok(dt226Suggest("Uncategorized", ["ETC Source Four ellipsoidal"]) === null && dt226Suggest("Fabric", ["velour"]) === null,
    "#226 suggest: generic and excluded categories never get a suggestion, whatever the parts say");
  ok(j(dt226Suggest("Fixtures", ["QSC loudspeaker"])) === j({ typeKey: "fixtures", confidence: "high" }), "#226 suggest: a category match beats the descriptions");

  // typeOfPart / scopes
  const types = dt226From(undefined);
  const map: DT226Map = {
    "motorized hoist": { typeKey: "hoists-motors", by: "auto", at: 1 },
    widgets: { typeKey: null, by: "admin", at: 2 },
    gone: { typeKey: "no-such-type", by: "admin", at: 3 },
  };
  ok(dt226TypeOf({ category: " Motorized  Hoist" }, map, types) === "hoists-motors", "#226 typeOfPart: matches the normalized category");
  ok(dt226TypeOf({ category: "Widgets" }, map, types) === null && dt226TypeOf({ category: "Gone" }, map, types) === null && dt226TypeOf({ category: "Nothing" }, map, types) === null,
    "#226 typeOfPart: an admin 'unmapped', an unknown type and no entry are all null");
  ok(dt226TypeOf({ category: "Motorized Hoist" }, map, types.map((t) => (t.key === "hoists-motors" ? { ...t, archived: true } : t))) === null,
    "#226 typeOfPart: an archived type maps nothing");
  ok(dt226TypeOf({ category: "Fabric" }, { fabric: { typeKey: "drapery", by: "admin", at: 1 } }, types) === null, "#226 typeOfPart: Fabric/Labor never take a device type");
  ok(dt226ScopeOf("hoists-motors", types) === "Rigging" && dt226ScopeOf("networking", types) === "Unscoped" && dt226ScopeOf(null, types) === "Unscoped" && dt226ScopeOf("nope", types) === "Unscoped",
    "#226 scopeOfType: the type's scope; unmapped → Unscoped");
  ok(dt226Keyword({ category: "Widgets", desc: "Blue thing" }) === "Unscoped" && dt226Keyword({ category: "X", desc: "Velour curtain" }) === "Curtains" && dt226Keyword({ category: "Speakers", desc: "" }) === "Audio",
    "#226 scope fix: the keyword fallback ends in Unscoped, not Lighting");
  ok(
    dt226Keyword({ category: "Rigid Mount" }) === "Unscoped" &&
      dt226Keyword({ category: "Rigging Hardware" }) === "Rigging" &&
      dt226Keyword({ category: "Truss" }) === "Rigging",
    "#226 fix wave: keywordScopeOf matches 'rig' as a word/prefix of rigging, not a bare substring — 'Rigid Mount' isn't Rigging"
  );
  const gc226 = readFileSync(join(process.cwd(), "src/lib/stores/grid-catalog.ts"), "utf8");
  ok(gc226.includes("keywordScopeOf(") && !/return "Lighting";/.test(gc226), "#226 scope fix: grid-catalog's scopeFor delegates to keywordScopeOf (no Lighting fallback)");

  // the map
  ok(j(dt226Sanitize({ "  Motorized HOIST ": { typeKey: "hoists-motors", by: "auto", at: 5 }, a: { typeKey: "Bad Key", by: "admin", at: 1 }, b: { typeKey: "speakers", by: "robot", at: 1 }, c: null, d: { typeKey: null, by: "admin" } }))
      === j({ "motorized hoist": { typeKey: "hoists-motors", by: "auto", at: 5 }, d: { typeKey: null, by: "admin", at: 0 } }),
    "#226 map: sanitizeTypeMap normalizes keys, keeps admin 'unmapped', drops bad entries");
  const auto = dt226Auto([{ category: "Truss" }, { category: "truss " }, { category: "Motorized Hoist" }, { category: "Control" }, { category: "Uncategorized" }, { category: "Widgets" }], map, types, 1000);
  ok(j(auto) === j({ truss: { typeKey: "truss-pipe", by: "auto", at: 1000 } }),
    "#226 auto: only unmapped categories with a HIGH suggestion become auto entries (existing entries — even an admin 'unmapped' — untouched; low/none skipped)");
  ok(j(dt226Auto([{ category: "Truss" }], {}, types.map((t) => (t.key === "truss-pipe" ? { ...t, archived: true } : t)), 1)) === "{}", "#226 auto: never auto-maps to an archived type");

  // #226 fix wave 3: mapKeyOf gates every map writer/reader against the
  // 120-char key limit sanitizeTypeMap enforces on read, so a too-long
  // category is never silently re-written on every read.
  ok(
    dt226MapKey("  Motorized  Hoist ") === "motorized hoist" &&
      dt226MapKey("Fabric") === null &&
      dt226MapKey("Labor") === null &&
      dt226MapKey("") === null &&
      dt226MapKey("x".repeat(121)) === null &&
      dt226MapKey("x".repeat(120)) === "x".repeat(120),
    "#226 mapKeyOf: normalizes; null for blank, excluded (fabric/labor) and >120 chars; exactly 120 is fine"
  );
  const longTruss = `Truss ${"x".repeat(130)}`; // > 120 chars; would be a HIGH truss-pipe match were the cap not enforced
  ok(j(dt226Auto([{ category: longTruss }], {}, types, 1000)) === "{}", "#226 auto: a >120-char category is never auto-mapped, even on a HIGH match (mapKeyOf gate)");
  ok(j(dt226Auto([{ category: "Fabric" }, { category: "Labor" }], {}, types, 1)) === "{}", "#226 auto: Fabric/Labor are gated out directly by mapKeyOf, not just by suggestDeviceType returning null");

  // review rows + accept
  const rows = dt226Rows([
    { category: "Truss", desc: "12in box truss" }, { category: "Truss", desc: "Corner block" },
    { category: "Motorized Hoist", desc: "CM Lodestar" },
    { category: "Audio", desc: "QSC loudspeaker" },
    { category: "Widgets", desc: "Loudspeaker stand" },
    { category: "Rigging", desc: "Shackle" },
    { category: "Fabric", desc: "Velour" }, { category: "", desc: "blank" },
  ], { ...map, truss: { typeKey: "truss-pipe", by: "admin", at: 9 } }, types);
  ok(rows.map((r) => r.category).join("|") === "Audio|Rigging|Widgets|Motorized Hoist|Truss", "#226 review: unmapped first, then auto, then admin; Fabric and blanks left out");
  const audio = rows.find((r) => r.category === "Audio")!;
  ok(audio.status === "unmapped" && j(audio.suggestion) === j({ typeKey: "speakers", confidence: "low" }) && audio.entry === null, "#226 review: an unmapped row carries its (description-voted) suggestion");
  ok(rows.find((r) => r.category === "Truss")!.count === 2 && rows.find((r) => r.category === "Motorized Hoist")!.status === "auto", "#226 review: counts parts per category; auto entries flagged");
  ok(j(dt226Accept(rows, types, 77)) === j({ audio: { typeKey: "speakers", by: "admin", at: 77 }, rigging: { typeKey: "rigging-hardware", by: "admin", at: 77 } }),
    "#226 review: Accept all suggestions writes admin entries for unmapped rows with any suggestion — never over an admin 'unmapped' (Widgets)");

  // #226 fix wave 3: a >120-char category is a read-only "toolong" review
  // row, not a perpetually "unmapped" one, and accept refuses it even if it
  // were somehow handed one marked "unmapped".
  const longCat = `Widgets ${"z".repeat(130)}`;
  const rowsWithLong = dt226Rows([{ category: longCat, desc: "x" }, { category: "Audio", desc: "QSC loudspeaker" }], map, types);
  const longRow = rowsWithLong.find((r) => r.category.startsWith("Widgets "))!;
  ok(longRow.status === "toolong" && longRow.suggestion === null && longRow.entry === null && longRow.typeKey === null,
    "#226 review: a >120-char category is a read-only 'too long to map' row, never unmapped/auto/admin");
  const fakeUnmappedLongRow = { ...longRow, status: "unmapped" as const, suggestion: { typeKey: "speakers", confidence: "low" as const } };
  ok(j(dt226Accept([fakeUnmappedLongRow], types, 5)) === "{}", "#226 accept: mapKeyOf refuses a >120-char key even if a row is somehow marked unmapped");

  // assign / merge / type-list edits
  ok(j(dt226Assign([" Widgets ", "", "Labor", "Gizmos"], "speakers", 5)) === j({ widgets: { typeKey: "speakers", by: "admin", at: 5 }, gizmos: { typeKey: "speakers", by: "admin", at: 5 } }),
    "#226 assign: normalized keys, admin entries, blanks/Labor skipped");
  ok(j(dt226Assign(["Widgets"], null, 5)) === j({ widgets: { typeKey: null, by: "admin", at: 5 } }), "#226 assign: null = deliberately unmapped (auto never re-maps it)");
  ok(j(dt226Assign(["x".repeat(130)], "speakers", 5)) === "{}", "#226 assign: a >120-char category is refused (mapKeyOf)");
  ok(j(dt226Merge({ a: { typeKey: "speakers", by: "auto", at: 1 }, b: { typeKey: "amplifiers", by: "admin", at: 1 }, c: { typeKey: "speakers", by: "admin", at: 1 } }, "speakers", "amplifiers", 9))
      === j({ a: { typeKey: "amplifiers", by: "admin", at: 9 }, c: { typeKey: "amplifiers", by: "admin", at: 9 } }),
    "#226 merge: every category of the merged type moves to the target as an admin entry");
  const edited = dt226Clean(
    [
      ...types.filter((t) => t.key !== "intercom").map((t) => (t.key === "speakers" ? { ...t, label: "Loudspeakers" } : t)),
      { label: "Fog & Haze", scope: "Lighting" },
      { label: "Speakers", scope: "Audio" },
    ],
    types.map((t) => (t.key === "fixtures" ? { ...t, icon: "wash" } : t))
  );
  ok(edited.ok && edited.types.find((t) => t.key === "speakers")!.label === "Loudspeakers" && edited.types.find((t) => t.key === "fog-haze")?.scope === "Lighting",
    "#226 types: rename keeps the key; a new type gets a slug key");
  ok(edited.ok && edited.types.some((t) => t.key === "speakers-2") && edited.types.find((t) => t.key === "intercom")?.archived === true && edited.types.find((t) => t.key === "fixtures")?.icon === "wash",
    "#226 types: a colliding slug gets a suffix; a dropped type is archived, never deleted; icons survive a list save");
  ok(edited.ok && edited.types.map((t) => t.order).slice(0, 3).join() === "10,20,30", "#226 types: order follows the submitted list");
  ok(!dt226Clean([{ label: "A", scope: "Lighting" }, { label: "a", scope: "Audio" }], []).ok && !dt226Clean([{ label: " ", scope: "Lighting" }], []).ok && !dt226Clean([{ label: "A", scope: "Nope" }], []).ok,
    "#226 types: duplicate names, blank names and unknown scopes are refused");

  // icons, labels, layer rows
  const tIcons = dt226TypeIcons(dt226WithIcons(types, { speakers: "horn", amplifiers: null }).map((t) => (t.key === "cameras" ? { ...t, archived: true } : t)));
  ok(tIcons.speakers === "horn" && tIcons.amplifiers === "amplifier" && !("cameras" in tIcons), "#226 icons: a type's own icon wins over the default; archived types have none");
  ok(dt226KeyOf({ id: "GASM-1", kind: "assembly" }) === DT226_ASM && dt226KeyOf({ id: "asm:fa-1" }) === DT226_ASM && dt226KeyOf({ id: "x", deviceType: "speakers" }) === "speakers"
      && dt226KeyOf({ id: "y", deviceType: null }) === DT226_UNMAPPED && dt226KeyOf(undefined) === DT226_UNMAPPED,
    "#226 typeKeyOfPart: assemblies, typed parts, unmapped");
  ok(dt226Label(DT226_UNMAPPED, types) === "Unmapped" && dt226Label("speakers", types) === "Speakers", "#226 typeLabel");
  const lr = dt226Layers([
    { scope: "Audio", typeKey: "amplifiers" }, { scope: "Audio", typeKey: DT226_UNMAPPED, sub: "Speakers" },
    { scope: "Audio", typeKey: "speakers" }, { scope: "Audio", typeKey: "speakers" }, { scope: "Audio", typeKey: DT226_UNMAPPED, sub: "Speakers" },
  ], types);
  ok(j(lr.get("Audio")) === j([{ key: "speakers", label: "Speakers", count: 2, subs: [] }, { key: "amplifiers", label: "Amplifiers", count: 1, subs: [] }, { key: DT226_UNMAPPED, label: "Unmapped", count: 2, subs: ["Speakers"] }]),
    "#226 layers: rows in type order, Unmapped last with its seeded categories as sub-labels");

  // favorites / recent list rules
  ok(j(dt226Ids(["a", "a", "", 5, "b", "x".repeat(121)], 10)) === j(["a", "b"]) && j(dt226Ids(null, 3)) === "[]", "#226 lists: cleanIdList dedupes and drops junk");
  ok(j(dt226Recent(["b", "a", "c"], "a", 3)) === j(["a", "b", "c"]) && j(dt226Recent(["a", "b", "c"], "d", 3)) === j(["d", "a", "b"]), "#226 recent: moves to the front, capped");
  const t1 = dt226Toggle(["a"], "b", 3);
  const t2 = dt226Toggle(["b", "a"], "a", 3);
  const t3 = dt226Toggle(["a", "b", "c"], "d", 3);
  ok(t1.ok && t1.on && j(t1.list) === j(["b", "a"]) && t2.ok && !t2.on && j(t2.list) === j(["b"]) && !t3.ok && /3 favorites/.test(t3.error),
    "#226 favorites: toggle adds to the front, removes, and refuses past the cap");

  // gridPartsFrom stamps the type and the type's scope
  const dtCtx = { types, map: { fixtures: { typeKey: "fixtures", by: "auto", at: 1 } } as DT226Map };
  const sym226 = (id: string, scope: string, category: string, kind?: "assembly") => ({
    id, name: id, manufacturer: "ETC", modelNumber: id, scope, category, width: 40, height: 30, ports: [],
    pricingPartId: kind ? null : id, kind: kind ?? "device", createdBy: "t", createdAt: 1, updatedAt: 1,
  });
  const cat226 = [
    { id: "P-FIX", sku: "P-FIX", desc: "Source Four", category: "Fixtures", unit: "ea", list: 1, cost: 1 },
    { id: "P-WID", sku: "P-WID", desc: "Blue widget", category: "Widgets", unit: "ea", list: 1, cost: 1 },
  ];
  const lib226 = dt226Parts([sym226("P-FIX", "Lighting", "Fixtures"), sym226("P-WID", "Lighting", "Widgets"), sym226("GASM-1", "Audio", "Assembly", "assembly")] as never, cat226 as never, {}, { deviceTypes: dtCtx });
  const by226 = new Map(lib226.map((p) => [p.id, p]));
  ok(by226.get("P-FIX")!.deviceType === "fixtures" && by226.get("P-FIX")!.deviceTypeLabel === "Fixtures" && dt226ScopeOfPart(by226.get("P-FIX")) === "Lighting",
    "#226 parts: a mapped part carries its type and the type's scope");
  ok(by226.get("P-WID")!.deviceType === null && dt226ScopeOfPart(by226.get("P-WID")) === "Unscoped",
    "#226 scope fix: an unmapped part stored with the old Lighting fallback now resolves Unscoped");
  ok(by226.get("GASM-1")!.deviceType === null && dt226ScopeOfPart(by226.get("GASM-1")) === "Audio", "#226 parts: an assembly keeps its own scope");
  ok(dt226Parts([sym226("P-WID", "Lighting", "Widgets")] as never, cat226 as never, {})[0].deviceType === undefined, "#226 parts: without a device-type context nothing changes (back-compat callers)");
}

/* ======================================================================
   #226 Grid device types — Task 2: the store (auto-apply on read, admin
   entries never overwritten, idempotent re-read, preview guard, merge,
   accept, favorites/recent caps) and the Catalog → Device types screen.
   Blob fixtures are snapshotted and put back in the async function's
   finally (blobs aren't CollectionName docs, so no fixture sweep).
   ====================================================================== */
{
  const read = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const page = read("src/app/(app)/catalog/device-types/page.tsx");
  const client = read("src/app/(app)/catalog/device-types/device-types-client.tsx");
  const acts = read("src/app/(app)/catalog/device-types/actions.ts");
  const clientImports = [...client.matchAll(/from\s+"([^"]+)"/g)].map((m) => m[1]);
  ok(page.includes('can("manage_users", user.roles)') && page.includes("loadDeviceTypeContext(") && page.includes("typeReviewRows("),
    "#226 screen: Catalog → Device types is admin-gated and reads through the auto-applying context");
  ok(client.startsWith('"use client"') && clientImports.every((s) => !s.startsWith("@/lib/stores/") && !s.startsWith("@/db")),
    "#226 screen: the client imports no store");
  ok(["saveDeviceTypesAction", "assignDeviceTypeAction", "acceptAllSuggestionsAction", "mergeDeviceTypeAction"].every((n) => {
    const i = acts.indexOf(`export async function ${n}`);
    return i >= 0 && acts.slice(i, acts.indexOf("\n}\n", i)).includes('await requirePerm("manage_users")');
  }), "#226 screen: every mapping action requires manage_users");
  ok(client.includes("Accept all suggestions") && client.includes('r.status === "auto"') && client.includes("mergeDeviceTypeAction("),
    "#226 screen: bulk accept, the auto chip and merge are on the screen");
  ok(read("src/app/(app)/catalog/page.tsx").includes('href="/catalog/device-types"') && read("src/app/(app)/catalog/taxonomy-card.tsx").includes("Estimating groups &amp; trades"),
    "#226 screen: Catalog links to Device types; the group/trade card is now 'Estimating groups & trades'");
  ok(read("scripts/smoke-routes.ts").includes('"/catalog/device-types"'), "#226 screen: the route is in the smoke list");

  // #226 fix wave 3: bulk assign starts with no choice and can't fire until
  // one is made; an explicit Unmap option is confirmed before it acts; a
  // too-long category is read-only; the table caps at 200 rendered rows.
  ok(client.includes('<option value="">Choose a type…</option>') && client.includes('<option value={UNMAP_CHOICE}>Unmap</option>'),
    "#226 screen: bulk assign starts unset (no default type or Unmap) and offers an explicit Unmap option");
  ok(client.includes("disabled={!picked.length || !bulkChoice || pending}") && client.includes("window.confirm("),
    "#226 screen: the Assign/Unmap button stays disabled until a choice is made, and Unmap is confirmed first");
  ok(client.includes('Unmap ${picked.length} selected') && client.includes("scopeKey !== pickedScope") && client.includes("`${show}|${filter}`"),
    "#226 screen: the button reads 'Unmap N selected' for the Unmap choice, and picked resets when the filter or tab changes");
  ok(client.includes('status === "toolong"') && client.includes("too long to map"),
    "#226 screen: a too-long category shows as read-only 'too long to map', never an assignable select");
  ok(client.includes("const ROW_CAP = 200") && client.includes("Showing {ROW_CAP} of") && client.includes("narrow the filter."),
    "#226 screen: the mapping table caps at 200 rendered rows with a 'Showing 200 of N — narrow the filter' notice");
}

async function deviceTypesAsyncChecks(): Promise<void> {
  const DT = await import("../src/lib/stores/device-types");
  const { getBlob, setBlob, setBlobKeysIfAbsent } = await import("../src/db/doc-store");
  const { getDb: getDb226 } = await import("../src/db");
  const { blobs: blobs226 } = await import("../src/db/doc-tables");
  const { inArray, eq } = await import("drizzle-orm");
  const U = "TEST226-user";
  const ids = ["gridTypeMap", "gridDeviceTypes", `gridFavorites:${U}`, `gridRecent:${U}`];
  const db = await getDb226();
  const snapshot = await db.select().from(blobs226).where(inArray(blobs226.id, ids));
  const typeMapRow = async () => (await db.select().from(blobs226).where(eq(blobs226.id, "gridTypeMap")))[0] as { updatedAt?: number } | undefined;
  try {
    await db.delete(blobs226).where(inArray(blobs226.id, ids));
    // #226 fix wave 3: LONG_CAT is a real (would-be-HIGH) truss match padded
    // past the map's 120-char key limit — before the fix this got auto-mapped,
    // silently dropped by sanitizeTypeMap on read, and auto-mapped again on
    // every single call (never idempotent, even though the visible map never
    // seemed to change).
    const LONG_CAT = `Truss ${"x".repeat(130)}`;
    const parts = [{ category: "Truss" }, { category: "Motorized Hoist" }, { category: "Control" }, { category: "Uncategorized" }, { category: "Widgets" }, { category: LONG_CAT }];

    await DT.assignDeviceType(["Motorized Hoist"], "speakers", 500);
    const first = await DT.loadDeviceTypeContext(parts, 1000);
    const raw1 = await getBlob<Record<string, unknown>>("gridTypeMap", {});
    // Field by field: jsonb re-orders object keys, so never compare a stored
    // entry to a literal with JSON.stringify.
    const t1raw = raw1.truss as { typeKey?: string; by?: string; at?: number } | undefined;
    ok(t1raw?.typeKey === "truss-pipe" && t1raw.by === "auto" && t1raw.at === 1000,
      "#226 store: reading the map writes a HIGH-confidence auto entry for an unmapped category");
    ok(first.map["motorized hoist"]?.typeKey === "speakers" && first.map["motorized hoist"]?.by === "admin",
      "#226 store: an admin entry is never overwritten by auto (Motorized Hoist would auto-map to Hoists & Motors)");
    ok(!("control" in raw1) && !("uncategorized" in raw1) && !("widgets" in raw1), "#226 store: low-confidence and unsuggested categories stay unmapped for review");
    ok(Object.keys(raw1).every((k) => k.length <= 120), "#226 store: a >120-char category (LONG_CAT) is never written to the map, even on a HIGH match");
    const rowBeforeSecond = await typeMapRow();
    const second = await DT.loadDeviceTypeContext(parts, 2000);
    const rowAfterSecond = await typeMapRow();
    const raw2 = await getBlob<Record<string, unknown>>("gridTypeMap", {});
    ok(JSON.stringify(raw2) === JSON.stringify(raw1) && second.map.truss?.at === 1000 && Object.keys(raw2).every((k) => k.length <= 120),
      "#226 store: a second read writes nothing (idempotent — the auto entry keeps its first timestamp; LONG_CAT still absent)");
    ok(rowBeforeSecond !== undefined && rowBeforeSecond.updatedAt === rowAfterSecond?.updatedAt,
      "#226 store: a second loadDeviceTypeContext performs NO blob write at all — the row's updatedAt doesn't move, including with a >120-char fixture category");

    await setBlobKeysIfAbsent("gridTypeMap", { "motorized hoist": { typeKey: "hoists-motors", by: "auto", at: 3000 }, pipe: { typeKey: "truss-pipe", by: "auto", at: 3000 } });
    const raw3 = await getBlob<Record<string, { typeKey: string; by: string }>>("gridTypeMap", {});
    ok(raw3["motorized hoist"].by === "admin" && raw3.pipe?.typeKey === "truss-pipe",
      "#226 store: setBlobKeysIfAbsent fills missing keys and never replaces an existing one (the atomic guard auto-apply writes through)");

    const prevEnv = process.env.VERCEL_ENV;
    process.env.VERCEL_ENV = "preview";
    try {
      const pv = await DT.loadDeviceTypeContext([{ category: "Dimmers" }], 4000);
      const rawPv = await getBlob<Record<string, unknown>>("gridTypeMap", {});
      ok(pv.map.dimmers?.typeKey === "dimming-power" && !("dimmers" in rawPv),
        "#226 store: a Vercel preview applies auto matches in memory but never writes them (previews share production's DB)");
    } finally {
      if (prevEnv === undefined) delete process.env.VERCEL_ENV;
      else process.env.VERCEL_ENV = prevEnv;
    }

    const cleared = await DT.assignDeviceType(["Truss"], null, 5000);
    const afterClear = await DT.loadDeviceTypeContext(parts, 6000);
    ok(cleared.ok && afterClear.map.truss?.typeKey === null && afterClear.map.truss?.by === "admin", "#226 store: an admin 'unmapped' sticks — auto never re-maps it");
    ok(!(await DT.assignDeviceType(["Truss"], "no-such-type")).ok && !(await DT.assignDeviceType([], "speakers")).ok,
      "#226 store: assign refuses an unknown type or an empty selection");

    await DT.assignDeviceType(["Gizmos", "Widgets"], "amplifiers", 7000);
    const merged = await DT.mergeDeviceType("amplifiers", "speakers", 8000);
    const mm = await DT.getTypeMap();
    const mt = await DT.getDeviceTypes();
    ok(merged.ok && merged.moved === 2 && mm.gizmos?.typeKey === "speakers" && mm.widgets?.typeKey === "speakers" && mt.find((t) => t.key === "amplifiers")?.archived === true,
      "#226 store: merge moves every category of a type to the target and archives the merged type");
    ok(!(await DT.mergeDeviceType("speakers", "speakers")).ok && !(await DT.mergeDeviceType("speakers", "amplifiers")).ok,
      "#226 store: merge refuses the same type or an archived target");

    const acc = await DT.acceptAllSuggestions([{ category: "Control", desc: "ETC Ion" }, { category: "Architectural", desc: "x" }], 9000);
    const ma = await DT.getTypeMap();
    ok(acc === 2 && ma.control?.typeKey === "control-networking" && ma.control?.by === "admin" && ma.architectural?.typeKey === "fixtures",
      "#226 store: Accept all suggestions applies the low-confidence ones as admin entries");

    const saved = await DT.saveDeviceTypes([...mt.map((t) => (t.key === "cameras" ? { ...t, label: "PTZ & Cameras" } : t)), { label: "Fog & Haze", scope: "Lighting" }]);
    const re = await DT.getDeviceTypes();
    ok(saved.ok && re.find((t) => t.key === "cameras")?.label === "PTZ & Cameras" && re.some((t) => t.key === "fog-haze"), "#226 store: the type list round-trips (rename + add)");
    ok(!(await DT.saveDeviceTypes([{ label: "", scope: "Lighting" }])).ok, "#226 store: an invalid list is refused whole");

    const f1 = await DT.toggleGridFavorite(U, "P-1");
    const f2 = await DT.toggleGridFavorite(U, "P-2");
    ok(f1.ok && f2.ok && (await DT.getGridFavorites(U)).join() === "P-2,P-1", "#226 favorites: newest star first, per user");
    const f3 = await DT.toggleGridFavorite(U, "P-1");
    ok(f3.ok && !f3.on && (await DT.getGridFavorites(U)).join() === "P-2", "#226 favorites: starring again removes it");
    ok((await DT.getGridFavorites("TEST226-other")).length === 0, "#226 favorites: another user's list is separate");
    await setBlob(`gridFavorites:${U}`, { ids: Array.from({ length: 300 }, (_, i) => `F-${i}`) });
    const full = await DT.toggleGridFavorite(U, "P-9");
    ok(!full.ok && /300/.test(full.error), "#226 favorites: capped at 300 — a 301st star is refused with a message");

    for (let i = 0; i < 45; i++) await DT.pushGridRecent(U, `R-${i}`);
    await DT.pushGridRecent(U, "R-40");
    const rec = await DT.getGridRecent(U);
    ok(rec.length === 40 && rec[0] === "R-40" && rec[1] === "R-44" && rec.filter((x) => x === "R-40").length === 1 && !rec.includes("R-4"),
      "#226 recent: last 40 distinct, most recent first");
  } finally {
    await db.delete(blobs226).where(inArray(blobs226.id, ids));
    for (const row of snapshot) await db.insert(blobs226).values(row);
  }
}

/* ====== Batch 1 final-review fixes — #221 redirect loop, #224 ?n= cap,
   #212 custom-item save/remove never sticks ====== */
import { estimatorShouldRedirect as fr221Redirect, quoteBuilderHref as fr221Href } from "@/lib/quote-links";
import { parsePageSize as fr224ParsePageSize } from "@/lib/short-list";
{
  const read = (f: string) => readFileSync(join(process.cwd(), f), "utf8");

  // --- #221: estimatorShouldRedirect is now defined purely off quoteBuilderHref,
  // so a quoteType that falls through to the Estimator (e.g. "service", coming
  // from the Import hub) no longer redirects estimator/page.tsx back to itself.
  const fr221False: Array<string | undefined | null> = ["service", "some-unknown-type", "system", "", null];
  for (const t of fr221False)
    ok(
      fr221Redirect({ id: "x", quoteType: t }) === false,
      `#221: estimatorShouldRedirect is false for quoteType=${JSON.stringify(t)} (quoteBuilderHref falls back to /estimator?id=…, so no redirect)`
    );
  const fr221True = ["flame_test", "repair", "inspection", "consulting", "rental"];
  for (const t of fr221True)
    ok(fr221Redirect({ id: "x", quoteType: t }) === true, `#221: estimatorShouldRedirect stays true for quoteType=${t}`);
  // Purity check: the result always agrees with quoteBuilderHref's own prefix,
  // for every case above — i.e. there is no separate allow-list to drift.
  for (const t of [...fr221False, ...fr221True]) {
    const href = fr221Href({ id: "x", quoteType: t });
    ok(
      fr221Redirect({ id: "x", quoteType: t }) === !href.startsWith("/estimator?"),
      `#221: estimatorShouldRedirect(quoteType=${JSON.stringify(t)}) matches !quoteBuilderHref(...).startsWith("/estimator?") (href was ${href})`
    );
  }

  // --- #224: ?n= is parsed by one shared, exported, clamped parsePageSize.
  ok(fr224ParsePageSize("999999") === 500, "#224: parsePageSize clamps a huge ?n= to the max (500)");
  ok(fr224ParsePageSize("-5") === 50, "#224: parsePageSize falls back to the default (50) for a negative ?n=");
  ok(fr224ParsePageSize("abc") === 50, "#224: parsePageSize falls back to the default (50) for a non-numeric ?n=");
  ok(fr224ParsePageSize("") === 50, "#224: parsePageSize falls back to the default (50) for an empty ?n=");
  ok(fr224ParsePageSize("100") === 100, "#224: parsePageSize passes an in-range ?n= through unchanged");
  ok(fr224ParsePageSize("500") === 500, "#224: parsePageSize passes the max itself through unchanged");
  ok(fr224ParsePageSize("50", 25, 200) === 50, "#224: parsePageSize honors a caller's own default/max");

  const companiesSrc224 = read("src/app/(app)/companies/page.tsx");
  const venuesSrc224 = read("src/app/(app)/venues/page.tsx");
  for (const [name, src] of [
    ["companies/page.tsx", companiesSrc224],
    ["venues/page.tsx", venuesSrc224],
  ] as const) {
    ok(src.includes('from "@/lib/short-list"'), `#224: ${name} imports the shared short-list module`);
    ok(!/function parsePageSize\(/.test(src), `#224: ${name} no longer defines its own local parsePageSize`);
  }
  const shortListLibSrc224 = read("src/lib/short-list.ts");
  ok(/export function parsePageSize\(/.test(shortListLibSrc224), "#224: short-list.ts exports the shared parsePageSize");

  const shortListUiSrc224 = read("src/components/short-list.tsx");
  ok(/<input[\s\S]*?aria-label=\{searchPlaceholder\}/.test(shortListUiSrc224), "#224: the ShortList filter input carries an aria-label built from its own placeholder text");

  // --- #212: a thrown save or remove on a Grid custom item never leaves the
  // button stuck reading "Saving…"/"Removing…" — both wrap their action in
  // try/catch/finally and show the same generic retry message.
  const customItemsSrc212 = read("src/app/(app)/design/grid/[id]/custom-items.tsx");
  ok(
    /const save = async \(\) => \{[\s\S]*?try \{[\s\S]*?saveCustomItemAction[\s\S]*?\} catch \{[\s\S]*?\} finally \{\s*setSaving\(false\);\s*\}\s*\};/.test(customItemsSrc212),
    "#212: save() wraps saveCustomItemAction in try/catch/finally, and finally unconditionally clears setSaving — a throw can't leave the button stuck on \"Saving…\""
  );
  ok(
    /onConfirm=\{async \(\) => \{\s*try \{[\s\S]*?removeCustomItemAction[\s\S]*?\} catch \{/.test(customItemsSrc212),
    "#212: the remove confirm's onConfirm also wraps removeCustomItemAction in try/catch"
  );
  ok(
    (customItemsSrc212.match(/Something went wrong — try again\./g) || []).length === 2,
    "#212: both the save and remove catch blocks show the same generic \"Something went wrong — try again.\" message"
  );
}

/* ====================================================================
   #217 T3 — the flame builder previews through the engine's finish, the Total
   is an input (Reset to auto + warning), each venue's Testing cell is an input,
   and reopening a quote restores both (D286-style seed for old sent prices).
   Client component — raw-source idiom (#177).
   ==================================================================== */
import { seedPriceOverrideIsLegacy as seedPriceOverrideIsLegacy217 } from "@/lib/service-pricing";
{
  const fc = readFileSync(join(process.cwd(), "src/app/(app)/flame-tests/quote/controls.tsx"), "utf8");
  const fcCode = fc.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
  ok(/from "@\/lib\/service-pricing"/.test(fc) && /finishFlame\(\{/.test(fcCode) && /venueTesting\(/.test(fcCode) && !/\/ \(1 - margin\)/.test(fcCode),
    "#217 flame builder: the preview finishes through finishFlame()/venueTesting(), no inlined margin math");
  ok(/fd\.set\("priceOverride", priceOverride != null \? String\(priceOverride\) : ""\);/.test(fc) &&
      /testingOverride: normalizeTestingOverride\(v\.testingOverride\) \?\? null,/.test(fc),
    "#217 flame builder: posts the typed total and each venue's typed testing cost");
  ok(/<ServiceTotalField/.test(fc) && /aria-label=\{"Testing cost for " \+ l\.label/.test(fc),
    "#217 flame builder: the Total and each venue's Testing cell are inputs");
  ok(/value=\{r\?\.overridden \? sliderPts\(r\.effectiveMargin\) : marginPts\}/.test(fc) &&
      /setMarginPts\(Math\.round\(\+e\.target\.value\)\);\n\s*setPriceText\(""\);/.test(fc) &&
      /function resetToAuto\(\)/.test(fc),
    "#217 flame builder: the slider follows a typed total; moving it or Reset to auto clears the override");
  ok(!/^import (?!type )[^;]*from "@\/lib\/(flametest-engine|repair-engine|inspection-engine)"/m.test(fc),
    "#217 flame builder: imports no engine module (client bundle)");
  const tf = readFileSync(join(process.cwd(), "src/components/service-total-field.tsx"), "utf8");
  ok(/^"use client";/.test(tf) && !/from "@\/(lib\/stores|db)\//.test(tf) && /Reset to auto/.test(tf) && /typedPriceWarning\(/.test(tf) && /rounded to the nearest \$25/.test(tf),
    "#217: the shared Total field is a client component on the pure module, with Reset to auto and the warning");
  const fp = readFileSync(join(process.cwd(), "src/app/(app)/flame-tests/quote/page.tsx"), "utf8");
  ok(/priceOverride: seedPriceOverride\(editQuote\.status, grossQuoteValue\(editQuote\), ft && ft\.priceOverride\),/.test(fp) &&
      /testing: v\.testingOverride != null \? String\(v\.testingOverride\) : ""/.test(fp),
    "#217 flame page: reopening restores the typed total and testing costs (old sent prices stay put)");

  // ---- controller addendum (Task 2 review): D286 priceOverrideSeeded marker,
  // and the renewal draft never says "current rates" twice.
  ok(!fc.includes("priceOverrideSeeded, setPriceOverrideSeeded") && !fc.includes("priceOverrideSeeded?: boolean"),
    "#217 final: the flame builder keeps no write-only priceOverrideSeeded state (the server derives the marker)");
  ok(!/fd\.set\("priceOverrideSeeded"/.test(fc),
    "#217 fix wave: the flame builder no longer posts priceOverrideSeeded — the save action derives it server-side");
  ok(/onReset=\{resetToAuto\}/.test(fc) &&
      /function resetToAuto\(\) \{\s*if \(r\?\.overridden\) setMarginPts\(sliderPts\(r\.effectiveMargin\)\);\s*setPriceText\(""\);\s*dirty\(\);/.test(fc),
    "#217 flame builder: Reset to auto clears the typed total");
  ok(!fp.includes("seedPriceOverrideIsLegacy") && !fp.includes("priceOverrideSeeded"),
    "#217 final: the flame page no longer passes a seeded flag to the builder");

  const faSrc217 = readFileSync(join(process.cwd(), "src/app/(app)/flame-tests/quote/actions.ts"), "utf8");
  ok(!/formData\.get\("priceOverrideSeeded"\)/.test(faSrc217) &&
      /deriveSeededMarker\(\{/.test(faSrc217) &&
      /\.\.\.\(r\.priceOverride != null && priceOverrideSeeded \? \{ priceOverrideSeeded: true \} : \{\}\),/.test(faSrc217),
    "#217 fix wave: the flame save derives priceOverrideSeeded from the stored quote, never a posted flag");

  ok(seedPriceOverrideIsLegacy217("sent", 821, undefined) === true && seedPriceOverrideIsLegacy217("won", 821.4, null) === true,
    "#217 D286 marker: a pre-#217 sent quote's off-grid reopen-seed is flagged legacy");
  ok(seedPriceOverrideIsLegacy217("sent", 900, 900) === false && seedPriceOverrideIsLegacy217("draft", 821, undefined) === false,
    "#217 D286 marker: a real saved priceOverride, or nothing seeded at all, is never flagged legacy");
  ok(priorHandSetPrice217({ priceOverride: 850, priceOverrideSeeded: true }) === null,
    "#217 renewal: a seeded (not hand-set) prior override reads as no hand-set price at all");
  ok(priorHandSetPrice217({ priceOverride: 850, priceOverrideSeeded: false }) === 850,
    "#217 renewal: priceOverrideSeeded false still reads the real hand-set price");

  type PP217b = Parameters<typeof priceParagraph217>[0];
  const para3 = priceParagraph217({ quote: { value: 900 }, lastPrice: 850, reasons: [], lastHandSet: 850 } as unknown as PP217b, "inspection");
  ok(!para3.includes("reflects our current rates") && (para3.match(/current rates/g) || []).length === 1,
    "#217 renewal wording: when last year's price was hand-set, \"current rates\" is said once, not twice");
  const para4 = priceParagraph217({ quote: { value: 900 }, lastPrice: 850, reasons: ["a longer curtain run"], lastHandSet: 850 } as unknown as PP217b, "inspection");
  ok(para4.includes("reflects a longer curtain run") && para4.includes("hand-set at $850"),
    "#217 renewal wording: a specific reason still prints alongside the hand-set sentence");
}

/* ====================================================================
   #217 T4 — repairs + inspections builders preview through the engines'
   finish, the Total is an input, and reopening restores a typed total.
   ==================================================================== */
{
  const strip217 = (s: string): string => s.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
  const rc = readFileSync(join(process.cwd(), "src/app/(app)/repairs/quote/controls.tsx"), "utf8");
  ok(/from "@\/lib\/service-pricing"/.test(rc) && /finishRepair\(\{/.test(strip217(rc)) && !/\/ \(1 - margin\)/.test(strip217(rc)) && !/\/ \(1 - pMargin\)/.test(strip217(rc)),
    "#217 repair builder: the preview finishes through finishRepair(), no inlined margin math");
  ok(/fd\.set\("priceOverride", priceOverride != null \? String\(priceOverride\) : ""\);/.test(rc) && /<ServiceTotalField/.test(rc),
    "#217 repair builder: the Total is an input and the typed total is posted");
  ok(/value=\{r\?\.overridden \? sliderPts\(r\.serviceMargin\) : marginPts\}/.test(rc) &&
      /setMarginPts\(Math\.round\(\+e\.target\.value\)\);\n\s*setPriceText\(""\);/.test(rc) &&
      /function resetToAuto\(\)/.test(rc),
    "#217 repair builder: the slider follows the back-solved SERVICE margin; moving it or Reset clears the override");
  const ic = readFileSync(join(process.cwd(), "src/app/(app)/inspections/quote/controls.tsx"), "utf8");
  ok(/from "@\/lib\/service-pricing"/.test(ic) && /finishInspection\(\{/.test(strip217(ic)) && !/\/ \(1 - margin\)/.test(strip217(ic)),
    "#217 inspection builder: the preview finishes through finishInspection(), no inlined margin math");
  ok(/fd\.set\("priceOverride", priceOverride != null \? String\(priceOverride\) : ""\);/.test(ic) && /<ServiceTotalField/.test(ic),
    "#217 inspection builder: the Total is an input and the typed total is posted");
  ok(/value=\{r\?\.overridden \? sliderPts\(r\.effectiveMargin\) : marginPts\}/.test(ic) &&
      /setMarginPts\(Math\.round\(\+e\.target\.value\)\);\n\s*setPriceText\(""\);/.test(ic) &&
      /function resetToAuto\(\)/.test(ic),
    "#217 inspection builder: the slider follows a typed total; moving it or Reset clears the override");
  for (const [svc, sub] of [["repairs", "rp"], ["inspections", "insp"]] as const) {
    const pg = readFileSync(join(process.cwd(), `src/app/(app)/${svc}/quote/page.tsx`), "utf8");
    ok(new RegExp(`priceOverride: seedPriceOverride\\(editQuote\\.status, grossQuoteValue\\(editQuote\\), ${sub} && ${sub}\\.priceOverride\\),`).test(pg),
      `#217 ${svc} page: reopening restores the typed total (old sent prices stay put)`);
  }

  // ---- addendum: the D286 priceOverrideSeeded marker is wired the same way
  // through repairs and inspections — the save action derives it on the
  // server from the stored quote (deriveSeededMarker) and stores it; the
  // builders keep no client copy — so a re-opened old off-grid sent price is
  // never mistaken for a real hand-set price by next year's renewal-outreach
  // math (priorHandSetPrice, currently flame- and inspection-only, but the
  // marker itself must exist on repairs too for #217 D286 parity).
  ok(!rc.includes("priceOverrideSeeded, setPriceOverrideSeeded") && !rc.includes("priceOverrideSeeded?: boolean"),
    "#217 final: the repair builder keeps no write-only priceOverrideSeeded state (the server derives the marker)");
  ok(!/fd\.set\("priceOverrideSeeded"/.test(rc),
    "#217 fix wave: the repair builder no longer posts priceOverrideSeeded — the save action derives it server-side");
  ok(/onReset=\{resetToAuto\}/.test(rc) &&
      /function resetToAuto\(\) \{\s*if \(r\?\.overridden\) setMarginPts\(sliderPts\(r\.serviceMargin\)\);\s*setPriceText\(""\);\s*dirty\(\);/.test(rc),
    "#217 repair builder: Reset to auto clears the typed total");

  ok(!ic.includes("priceOverrideSeeded, setPriceOverrideSeeded") && !ic.includes("priceOverrideSeeded?: boolean"),
    "#217 final: the inspection builder keeps no write-only priceOverrideSeeded state (the server derives the marker)");
  ok(!/fd\.set\("priceOverrideSeeded"/.test(ic),
    "#217 fix wave: the inspection builder no longer posts priceOverrideSeeded — the save action derives it server-side");
  ok(/onReset=\{resetToAuto\}/.test(ic) &&
      /function resetToAuto\(\) \{\s*if \(r\?\.overridden\) setMarginPts\(sliderPts\(r\.effectiveMargin\)\);\s*setPriceText\(""\);\s*dirty\(\);/.test(ic),
    "#217 inspection builder: Reset to auto clears the typed total");

  for (const [svc, sub] of [["repairs", "rp"], ["inspections", "insp"]] as const) {
    const pg = readFileSync(join(process.cwd(), `src/app/(app)/${svc}/quote/page.tsx`), "utf8");
    ok(!pg.includes("seedPriceOverrideIsLegacy") && !pg.includes("priceOverrideSeeded") && pg.includes(`${sub} && ${sub}.priceOverride`),
      `#217 final: the ${svc} page no longer passes a seeded flag to the builder`);
    const ac = readFileSync(join(process.cwd(), `src/app/(app)/${svc}/quote/actions.ts`), "utf8");
    ok(!/formData\.get\("priceOverrideSeeded"\)/.test(ac) &&
        /deriveSeededMarker\(\{/.test(ac) &&
        /\.\.\.\(r\.priceOverride != null && priceOverrideSeeded \? \{ priceOverrideSeeded: true \} : \{\}\),/.test(ac),
      `#217 fix wave: the ${svc} save derives priceOverrideSeeded from the stored quote, never a posted flag`);
  }

  // ---- the repairs-only "below parts price" warning: a typed total under
  // what the parts alone are selling for warns sharper than below-cost.
  const stf217 = readFileSync(join(process.cwd(), "src/components/service-total-field.tsx"), "utf8");
  ok(/partsSell/.test(stf217) && /typedPriceWarning\(total, cost, margin, partsSell\)/.test(stf217),
    "#217: the shared Total field threads an optional partsSell into typedPriceWarning() for repairs");
  ok(/partsSell=\{r\?\.partsSell/.test(rc),
    "#217 repair builder: the Total field is given the service's partsSell for the below-parts-price warning");
}

/* ====================================================================
   #217 fix wave — the D286 priceOverrideSeeded marker is derived on the
   SERVER (a client can't fake or drop it, and it agrees with itself across
   every reopen), plus three review-flagged minors on the flame Testing
   cell and the shared ServiceTotalField.
   ==================================================================== */
import { deriveSeededMarker as deriveSeededMarker217 } from "@/lib/service-pricing";
{
  // ---- the pure helper itself ----
  const firstReopen217 = { value: 821, status: "sent", priceOverride: undefined, priceOverrideSeeded: undefined };
  ok(deriveSeededMarker217({ postedOverride: 821, stored: firstReopen217 }) === true,
    "#217 fix wave: a first reopen of a pre-#217 off-grid sent quote (no stored priceOverride yet) flags the marker");

  const secondSave217 = { value: 821, status: "sent", priceOverride: 821, priceOverrideSeeded: true };
  ok(deriveSeededMarker217({ postedOverride: 821, stored: secondSave217 }) === true,
    "#217 fix wave: a SECOND save of that same seeded value still flags the marker (the bug: the old code read this as a real hand-set price)");

  ok(deriveSeededMarker217({ postedOverride: 900, stored: secondSave217 }) === false,
    "#217 fix wave: typing a different total off an already-seeded quote is a real hand-set price — no marker");

  const draftQuote217 = { value: 821, status: "draft", priceOverride: undefined, priceOverrideSeeded: undefined };
  ok(deriveSeededMarker217({ postedOverride: 821, stored: draftQuote217 }) === false,
    "#217 fix wave: a draft quote — nobody has seen a price yet — is never flagged");

  const realHandSet217 = { value: 900, status: "sent", priceOverride: 900, priceOverrideSeeded: false };
  ok(deriveSeededMarker217({ postedOverride: 900, stored: realHandSet217 }) === false,
    "#217 fix wave: a stored REAL hand-set override (no marker), re-saved unchanged, stays unmarked forever");

  ok(deriveSeededMarker217({ postedOverride: 900, stored: null }) === false,
    "#217 fix wave: a brand-new quote (nothing stored yet) is never flagged, even when its first typed total happens to equal itself");
  ok(deriveSeededMarker217({ postedOverride: null, stored: secondSave217 }) === false,
    "#217 fix wave: no posted override at all is never flagged");

  // ---- client-posted flag ignored: none of the three save actions read it,
  // and all three derive the marker from deriveSeededMarker() instead ----
  for (const svc of ["flame-tests", "repairs", "inspections"] as const) {
    const ac = readFileSync(join(process.cwd(), `src/app/(app)/${svc}/quote/actions.ts`), "utf8");
    ok(!/formData\.get\("priceOverrideSeeded"\)/.test(ac) && /deriveSeededMarker\(\{/.test(ac) && /get as getQuote/.test(ac),
      `#217 fix wave: ${svc}'s save action never reads a client-posted priceOverrideSeeded — it looks up the stored quote and derives the marker itself`);
  }

  // ---- minor (a): the flame Testing cell is a plain text input, normalized
  // on blur — no rounding mid-keystroke ("12.5" jumping to "13"), and no
  // native type="number" wipe on a transient state like "1e".
  const fc217 = readFileSync(join(process.cwd(), "src/app/(app)/flame-tests/quote/controls.tsx"), "utf8");
  ok(/type="text"\s*\n\s*inputMode="decimal"\s*\n\s*value=\{st\.testing/.test(fc217) &&
      /onBlur=\{\(\) => blurTesting\(l\.id\)\}/.test(fc217),
    "#217 fix wave (a): the flame Testing cell is a text input (inputMode=\"decimal\") normalized on blur, not a native number input");
  ok(/function setTesting\(locId: string, val: string\) \{[\s\S]*?testing: val, on: true[\s\S]*?\n  \}/.test(fc217) &&
      !/testing: clean/.test(fc217),
    "#217 fix wave (a): typing into the Testing cell keeps exactly what's typed — no per-keystroke rounding");
  ok(/function blurTesting\(locId: string\) \{[\s\S]*?normalizeTestingOverride\(cur\.testing\)/.test(fc217),
    "#217 fix wave (a): the Testing cell normalizes (rounds to a whole dollar, blank = computed) only on blur");

  // ---- minors (b)/(c), in the shared ServiceTotalField so all three
  // builders get them ----
  const stf217fix = readFileSync(join(process.cwd(), "src/components/service-total-field.tsx"), "utf8");
  ok(!/Typed total · auto is/.test(stf217fix) && /Typed total · Reset keeps this margin/.test(stf217fix),
    "#217 fix wave (b): the typed-total note states what Reset actually does (it parks the slider at the back-solved margin) instead of naming a figure Reset won't reproduce");
  ok(/disabled \? "—" : String\(Math\.round\(autoTotal\)\)/.test(stf217fix),
    "#217 fix wave (c): a disabled Total field shows \"—\", never a bare 0 that reads as a real free quote");
}

/* ====== #227 T1: one flat $/sq ft, one helper, every mirror agrees ====== */
import { curtainCost as fab227Cost, curtainPrice as fab227Price, fabricAreaRateOf as fab227RateOf, SEED_FABRIC_RATES as fab227Seeds } from "@/lib/design/curtain-pricing";
import { curtainCost as fab227PortalCost, fabricSellPerSqft as fab227Sell } from "@/lib/curtain-pricing";
import { curtainPriceEach as fab227PriceEach } from "@/lib/curtain-geom";
import { drapeUnitCost as fab227Drape } from "@/lib/design/equipment-pricing";
import { computeCurtain as fab227Compute } from "@/app/(app)/estimator/pricing";
import { priceGridCurtains as fab227Grid } from "@/lib/design/grid-curtains";
import { priceCell as fab227PriceCell, type PricingPart as Fab227Part } from "@/lib/design/equipment-map";
import { EQUIPMENT_ROW_BY_KEY as fab227Rows } from "@/lib/design/equipment-vocab";
import { curtainSwapHits as fab227SwapHits } from "@/lib/design/auto-estimate";
{
  // The formula: sewn area × rate, pleated and flat alike.
  const pleated = fab227Cost({ finishedWidthFt: 20, finishedHeightFt: 19, fullnessPct: 50, qty: 1 }, { fabricRate: 3.64, sewingPct: 0 });
  ok(pleated.sewnAreaSqft === 570 && pleated.costEach === 2074.8, `#227: pleated cost = sewn area 570 × 3.64 = 2074.8, no width term (got ${pleated.costEach})`);
  const flat = fab227Cost({ finishedWidthFt: 40, finishedHeightFt: 20, fullnessPct: 0, qty: 1 }, { fabricRate: 0.9, sewingPct: 0 });
  ok(flat.sewnAreaSqft === 800 && flat.costEach === 720, `#227: flat goods cost = 800 × 0.9 = 720 (got ${flat.costEach})`);
  ok(fab227Price(pleated.costEach, 0.3) === Math.round((2074.8 / 0.7) * 100) / 100, "#227: sell = cost ÷ (1 − margin), unchanged");

  // The one fallback chain.
  ok(fab227RateOf({ sku: "RB-EN-16", curtainAreaRate: 5, costPerSqft: 1 }) === 5, "#227 chain: the catalog's curtainAreaRate wins");
  ok(fab227RateOf({ sku: "RB-EN-16", costPerSqft: 2.6 }) === fab227Seeds["RB-EN-16"], "#227 chain: then the seed rate for that SKU");
  ok(fab227RateOf({ sku: "RB-EN-16", curtainAreaRate: null, costPerSqft: 2.6 }) === 2.1, "#227 chain: a null curtainAreaRate falls through like an absent one");
  ok(fab227RateOf({ sku: "FAB227-X", costPerSqft: 1.1 }) === 1.1, "#227 chain: then the raw costPerSqft");
  ok(fab227RateOf({ sku: "FAB227-X" }) === 0 && fab227RateOf(null) === 0 && fab227RateOf(undefined) === 0, "#227 chain: else 0 (No $/sq ft set)");
  ok(fab227RateOf({ sku: "toString" }) === 0 && fab227RateOf({ sku: "FAB227-X", curtainAreaRate: -2 }) === 0, "#227 chain: a prototype key is never a seed, and a negative rate is 0");

  // Parity: every mirror returns the same number for the same drape.
  const cases = [
    { w: 20, h: 19, full: 50, rate: 3.64 },
    { w: 40, h: 20, full: 0, rate: 0.9 },
    { w: 9.5, h: 10 + 11 / 12, full: 100, rate: 2.84 },
    { w: 50, h: 3, full: 75, rate: 4.37 },
  ];
  for (const c of cases) {
    const tag = `${c.w}×${c.h.toFixed(2)} @${c.full}% $${c.rate}`;
    const shared = fab227Cost({ finishedWidthFt: c.w, finishedHeightFt: c.h, fullnessPct: c.full, qty: 1 }, { fabricRate: c.rate, sewingPct: 10 }).costEach;
    const spec = { name: "d", hang: "", fabric: "FAB227", qty: "1", width: String(c.w), height: String(c.h), fullness: String(c.full), bottom: "" };
    const portal = fab227PortalCost(spec, { fabricRate: c.rate, sewingPct: 10 }, 0.3);
    const est = fab227Compute({ ...spec, vendorCostOverride: "" }, [{ sku: "FAB227", name: "x", costPerSqft: 0, curtainAreaRate: c.rate }], { sewingPct: 10 }, 0.3);
    const grid = fab227Grid(
      [{ id: "pl1", curtain: { type: "Draw", name: "d", widthFt: c.w, heightFt: c.h, fullnessPct: c.full, fabricSku: "FAB227" } }],
      [{ id: "FAB227", sku: "FAB227", desc: "x", category: "Fabric", curtainAreaRate: c.rate }],
      { sewingPct: 10 },
      0.3
    ).get("pl1")!;
    const drape = fab227Drape({ w: c.w, h: c.h, fullness: c.full, qty: 1 }, c.rate, 10);
    const client = fab227PriceEach(spec, fab227Sell({ fabricRate: c.rate, sewingPct: 10 }, 0.3));
    ok(portal.costEach === shared && est.costEach === shared && grid.costEach === shared, `#227 parity ${tag}: portal, estimator and Grid cost = shared model ${shared} (got ${portal.costEach} / ${est.costEach} / ${grid.costEach})`);
    ok(drape === Math.round(shared), `#227 parity ${tag}: the Equipment map drape cost is the shared cost, dollar-rounded (got ${drape})`);
    ok(grid.priceEach === portal.priceEach && Math.abs(client - portal.priceEach) < 0.011, `#227 parity ${tag}: Grid + client preview sell = portal sell (client ${client}, server ${portal.priceEach})`);
    ok(Math.abs(est.priceEach - portal.priceEach) <= 0.011, `#227 parity ${tag}: estimator sell within a cent of the portal sell`);
  }

  // The Equipment map and the swap search read the same helper.
  const drawDef = fab227Rows.get("curtains:draw")!;
  const ctxOf = (p: Fab227Part) => ({ parts: new Map<string, Fab227Part>([[p.sku, p]]), fixtures: new Map(), margin: 0.3 });
  const seeded = fab227PriceCell({ kind: "part", sku: "RB-EN-16" }, drawDef, ctxOf({ sku: "RB-EN-16", desc: "Encore 16", unit: "sq ft", cost: 0, list: 0, category: "Fabric" }));
  ok(seeded.status === "part" && seeded.areaRate === 2.1, "#227: the Equipment map resolves a fabric through fabricAreaRateOf — seed rates included (spec §2)");
  const cps = fab227PriceCell({ kind: "part", sku: "FAB227-CPS" }, drawDef, ctxOf({ sku: "FAB227-CPS", desc: "Muslin", unit: "sq ft", cost: 0, list: 0, category: "Fabric", costPerSqft: 1.4 }));
  ok(cps.status === "part" && cps.areaRate === 1.4, "#227: …and falls back to the fabric's cost per sq ft");
  const hits = fab227SwapHits([{ sku: "FAB227-CPS", desc: "cost/sq ft only", costPerSqft: 1.4 }, { sku: "FAB227-NONE", desc: "no rate" }], 0.3);
  ok(hits.length === 1 && hits[0].ref === "FAB227-CPS" && hits[0].unitSell === 2, "#227: the swap search finds a fabric priced only by cost per sq ft (the one helper), sold through the margin");

  // No making term and no private rate chain survives in any mirror.
  const mirrors227 = [
    "src/lib/design/curtain-pricing.ts", "src/lib/curtain-pricing.ts", "src/lib/curtain-geom.ts",
    "src/lib/design/equipment-pricing.ts", "src/lib/design/equipment-map.ts", "src/lib/design/grid-curtains.ts",
    "src/lib/design/auto-estimate.ts", "src/app/(app)/estimator/pricing.ts", "src/app/(app)/estimator/page.tsx",
    // #245 Task 12: the portal estimate builder is deleted (the catalog cart replaced it).
    "src/app/portal/actions.ts", "src/app/portal/estimate/page.tsx",
    "src/app/(app)/design/grid/[id]/page.tsx", "src/app/(app)/design/grid/[id]/editor.tsx", "src/app/(app)/design/grid/[id]/curtain-drop.tsx",
  ];
  for (const f of mirrors227) {
    // #299: the Grid editor's logic moved to use-grid-editor.ts — scanned under the editor's entry.
    const s = readFileSync(join(process.cwd(), f), "utf8") +
      (f.endsWith("/grid/[id]/editor.tsx") ? readFileSync(join(process.cwd(), "src/app/(app)/design/grid/[id]/use-grid-editor.ts"), "utf8") + readFileSync(join(process.cwd(), "src/app/(app)/design/grid/[id]/plan-canvas.tsx"), "utf8") + gridWorkspaceSource : "");
    ok(!/makingRate|MAKING_RATE|sellCoeffs|SellCoeffs|makingPerFt|curtainCoeffs/.test(s), `#227: ${f} carries no making term or sell coefficients`);
    if (f !== "src/lib/design/curtain-pricing.ts") ok(!/curtainAreaRate\s*\?\?|SEED_FABRIC_RATES\[/.test(s), `#227: ${f} resolves a fabric rate only through fabricAreaRateOf`);
  }
}

/* ====== #227 T2: fabric $/sq ft — part form, converter, Import hub + price-book columns ====== */
import { fabricFieldsOf as fab227Fields, parseCatalog as fab227ParseBook } from "@/app/(app)/catalog/parse";
import { sqftRateFromLinearYard as fab227FromLinYd, sqftRateFromSquareYard as fab227FromSqYd } from "@/lib/curtain-geom";
{
  // Converter: a 54″ velour yard is 3 ft × 4.5 ft = 13.5 sq ft.
  ok(fab227FromLinYd(40.5, 54) === 3, "#227 converter: $40.50/lin-yd of 54″ velour → $3/sq ft (÷ 13.5)");
  ok(fab227FromLinYd(27, 54) === 2 && fab227FromLinYd(30, 120) === 1, "#227 converter: $/lin-yd ÷ (3 × bolt in ÷ 12) at any bolt width");
  ok(fab227FromLinYd(40.5, 0) === 0 && fab227FromLinYd(0, 54) === 0 && fab227FromLinYd(Number.NaN, 54) === 0, "#227 converter: a missing price or bolt width converts to 0, never NaN/Infinity");
  ok(fab227FromSqYd(9) === 1 && fab227FromSqYd(13.5) === 1.5 && fab227FromSqYd(0) === 0, "#227 converter: $/sq yd ÷ 9");

  // Part form: submitted-only, blank clears.
  const fd = new FormData();
  fd.set("sku", "FAB227");
  const none = optionalPartFields(fd);
  ok(!("curtainAreaRate" in none) && !("boltWidthIn" in none), "#227 part form: a form without the fabric fields leaves the stored rate alone");
  fd.set("curtainAreaRate", " $4.85 ");
  fd.set("boltWidthIn", "54");
  const set = optionalPartFields(fd);
  ok(set.curtainAreaRate === 4.85 && set.boltWidthIn === 54, "#227 part form: a typed $/sq ft and bolt width save");
  fd.set("curtainAreaRate", "");
  fd.set("boltWidthIn", "-3");
  const cleared = optionalPartFields(fd);
  ok("curtainAreaRate" in cleared && cleared.curtainAreaRate === undefined && "boltWidthIn" in cleared && cleared.boltWidthIn === undefined, "#227 part form: a blanked or non-positive value clears it (the part falls back to seed / cost per sq ft)");

  // Import hub: exact-header-only number columns; price-only rows carry no fabric key.
  const hubCat = getTypeMeta("catalog")!;
  const rateField = hubCat.fields.find((f) => f.key === "curtainAreaRate");
  const boltField = hubCat.fields.find((f) => f.key === "boltWidthIn");
  ok(rateField?.header === "Fabric $/sq ft" && rateField.kind === "number" && rateField.exactOnly === true && boltField?.header === "Bolt width (in)" && boltField.kind === "number" && boltField.exactOnly === true, "#227 Import hub: Fabric $/sq ft and Bolt width (in) are exact-header-only number columns");
  const hubValues = (headers: string[], row: string[]) => prepareRows([row], autoMap(headers, hubCat.fields), hubCat.fields).rows[0].values;
  const withRate = hubValues(["SKU", "Description", "Manufacturer", "Fabric $/sq ft", "Bolt width (in)"], ["FAB227-V", "Velour", "Rose Brand", "4.85", "54"]);
  const created = catalogPatch(withRate, null, "FAB227-V");
  ok(created.curtainAreaRate === 4.85 && created.boltWidthIn === 54, "#227 Import hub: the fabric columns land on curtainAreaRate / boltWidthIn");
  const stored227 = { sku: "FAB227-V", desc: "Velour", category: "Fabric", unit: "sq ft", list: 0, cost: 0, mfr: "Rose Brand", curtainAreaRate: 4.85, boltWidthIn: 54 };
  const priceOnly = catalogPatch(hubValues(["SKU", "Description", "Manufacturer", "List Price"], ["FAB227-V", "Velour", "Rose Brand", "12"]), stored227, "FAB227-V");
  ok(!("curtainAreaRate" in priceOnly) && !("boltWidthIn" in priceOnly), "#227 Import hub: a price-only row carries no fabric key, so mergeUpsert keeps the stored rate");
  const blankRate = catalogPatch(hubValues(["SKU", "Description", "Manufacturer", "Fabric $/sq ft"], ["FAB227-V", "Velour", "Rose Brand", ""]), stored227, "FAB227-V");
  ok(!("curtainAreaRate" in blankRate), "#227 Import hub: a blank Fabric $/sq ft cell never clears the stored rate");
  const lookalike = autoMap(["SKU", "Description", "Price per sq ft", "Width"], hubCat.fields);
  ok(lookalike.curtainAreaRate === -1 && lookalike.boltWidthIn === -1, "#227 Import hub: a vendor's look-alike columns never map to the fabric fields");
  ok(importTemplateCsv("catalog").split("\n")[0].includes("Fabric $/sq ft,Bolt width (in)"), "#227 Import hub: the catalog template advertises both columns");

  // Price-book importer: header-only columns, only positive values written.
  const book = fab227ParseBook("SKU,Description,Fabric $/sq ft,Bolt width (in)\nFAB227-V,Velour,4.85,54\n");
  ok(book.ok && book.rows[0].curtainAreaRate === 4.85 && book.rows[0].boltWidthIn === 54, "#227 price book: the fabric headers parse");
  const wrote = fab227Fields(book.rows[0]);
  ok(wrote.curtainAreaRate === 4.85 && wrote.boltWidthIn === 54, "#227 price book: a carried rate and bolt width are written");
  ok(Object.keys(fab227Fields(fab227ParseBook("SKU,Description,List Price\nFAB227-V,Velour,12\n").rows[0])).length === 0, "#227 price book: a price-only file writes no fabric key — the stored rate survives the re-import");
  ok(Object.keys(fab227Fields(fab227ParseBook("FAB227-V,Velour,Fabric,sq ft,12,8,Rose Brand,,,,,,,,,,,,4.85,54\n").rows[0])).length === 0, "#227 price book: the fabric columns are header-only — no positional slot");
  const importSrc227 = readFileSync(join(process.cwd(), "src/app/(app)/catalog/import.ts"), "utf8");
  ok(importSrc227.includes("...fabricFieldsOf(r),"), "#227 price book: runCatalogImport spreads fabricFieldsOf into the mergeUpsert patch");

  // Catalog editor: client field, Fabric parts only, no store/cost import.
  const frf = readFileSync(join(process.cwd(), "src/app/(app)/catalog/fabric-rate-field.tsx"), "utf8");
  ok(frf.startsWith('"use client"') && !/from "@\/lib\/stores\/|from "@\/db|curtain-pricing"/.test(frf), "#227 catalog editor: the rate field is a client component importing no store or cost module");
  ok(frf.includes('name="curtainAreaRate"') && frf.includes('name="boltWidthIn"') && frf.includes("$/sq ft fabric"), "#227 catalog editor: it posts curtainAreaRate + boltWidthIn under the spec's label (#227 late: $/sq ft fabric)");
  const catPage227 = readFileSync(join(process.cwd(), "src/app/(app)/catalog/page.tsx"), "utf8");
  ok(catPage227.includes("part && isFabricPart(part) && (") && catPage227.includes("<FabricRateField"), "#227 catalog editor: only fabric parts (#264: isFabricPart) show the $/sq ft field");
}

/* ====== #227 T3: labels — $X/sq ft fabric (#227 late; was sewn incl. making) / No $/sq ft set ====== */
import { fabricRateLabel as fab227Label, FABRIC_RATE_UNIT as fab227Unit, NO_FABRIC_RATE as fab227NoRate } from "@/lib/curtain-geom";
import { priceCell as fab227PriceCell3, type PricingPart as Fab227Part3 } from "@/lib/design/equipment-map";
import { EQUIPMENT_ROW_BY_KEY as fab227Rows3 } from "@/lib/design/equipment-vocab";
import { curtainSwapHits as fab227Swap3 } from "@/lib/design/auto-estimate";
{
  ok(fab227Unit === "sq ft fabric" && fab227NoRate === "No $/sq ft set", "#227 labels: the unit and the no-rate text are the spec's words (#227 late: sq ft fabric)");
  ok(fab227Label(3.64) === "$3.64/sq ft fabric", `#227 labels: a rate reads $X/sq ft fabric (#227 late) (got ${fab227Label(3.64)})`);
  ok(fab227Label(0) === fab227NoRate && fab227Label(undefined) === fab227NoRate && fab227Label(null) === fab227NoRate && fab227Label(Number.NaN) === fab227NoRate, "#227 labels: no rate reads No $/sq ft set");

  const hits = fab227Swap3([{ sku: "FAB227-S", desc: "velour", curtainAreaRate: 3.5 }], 0.3);
  ok(hits.length === 1 && hits[0].unit === fab227Unit, "#227 labels: the swap search shows a fabric per sq ft fabric (#227 late)");

  const drawDef = fab227Rows3.get("curtains:draw")!;
  const ctxOf = (p: Fab227Part3) => ({ parts: new Map<string, Fab227Part3>([[p.sku, p]]), fixtures: new Map(), margin: 0.3 });
  const bare = fab227PriceCell3({ kind: "part", sku: "FAB227-BARE" }, drawDef, ctxOf({ sku: "FAB227-BARE", desc: "Bare", unit: "sq ft", cost: 0, list: 0, category: "Fabric" }));
  ok(bare.status === "needs-part" && bare.reason === "FAB227-BARE: No $/sq ft set", "#227 labels: a rateless fabric on a curtain row is needs-a-part with No $/sq ft set");
  const notFabric = fab227PriceCell3({ kind: "part", sku: "FAB227-HB" }, drawDef, ctxOf({ sku: "FAB227-HB", desc: "Headblock", unit: "ea", cost: 500, list: 700, category: "Rigging Hardware" }));
  ok(notFabric.status === "needs-part" && notFabric.reason === "FAB227-HB is not a fabric (category Fabric, or Theatrical/Soft Goods sold per sq ft)", "#227 labels: a non-fabric part on a curtain row says so");

  const src = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const modal = src("src/app/(app)/estimator/curtain-modal.tsx");
  ok(modal.includes("fabricRateLabel(f.curtainAreaRate)") && !modal.includes('"/sq ft sewn"'), "#227 labels: the estimator curtain modal labels each fabric with fabricRateLabel");
  ok(src("src/app/(app)/design/grid/[id]/curtain-drop.tsx").includes("sewnSellLabel(f.pricePerSqft)"), "#227 labels: the Grid curtain drop-in labels each fabric (No $/sq ft set when unrated; #227 late: its sewn sell rate, sewing included)");
  const emc227 = src("src/app/(app)/design/grid/settings/equipment-map/equipment-map-client.tsx");
  ok(emc227.includes("FABRIC_RATE_UNIT") && !emc227.includes("+ making"), "#227 labels: the Equipment map cell reads per sq ft fabric (#227 late), not + making");
  // PartFormModal is reused across parts without remounting, so the rate
  // field's local state must be keyed per part or part A's rate saves onto B.
  ok(/<FabricRateField[^>]*key=\{part\.sku\}/.test(src("src/app/(app)/catalog/page.tsx")), "#227 catalog editor: FabricRateField is keyed by part.sku so one part's rate never carries into the next");
}

/* --- #233: relabels — one label source (the vocabulary); old Quick Design overrides and the moved Equipment-map key still resolve --- */
import {
  EQUIPMENT_ROWS as r233Rows, EQUIPMENT_ROW_BY_KEY as r233ByKey,
  EQUIPMENT_KEY_ALIASES as r233KeyAliases, EQUIPMENT_LABEL_ALIASES as r233LabelAliases,
} from "@/lib/design/equipment-vocab";
import {
  compute as r233Compute, defaultAState as r233Default, cleanQtyOverrides as r233Clean, hydrateAState as r233Hydrate,
  type AState as R233AState,
} from "@/app/(app)/design/quick/engine";
import { sanitizeEquipmentMap as r233Sanitize } from "@/lib/design/equipment-map";
import { LEGACY_HINTS as r233Hints } from "@/lib/design/equipment-legacy-hints";
{
  const L = (k: string) => r233ByKey.get(k)?.label;
  const expected: Array<[string, string]> = [
    ["rigging:aircraftCable", "Suspension Method"],
    ["rigging:chainWrap", "Batten Termination"],
    ["rigging:terminationKit", "Beginning Termination"],
    ["controls:consoleTouch", "Console Accessories"],
    ["controls:batteryBackup", "Emergency"],
    ["controls:processor", "Power Controls – Production"],
    ["controls:button", "Power Controls – Architectural"],
    ["controls:archTouch", "Architectural Controls"],
    ["controls:inputStation", "DMX Distribution"],
    ["lighting:cablePackage", "Cable Package"],
    ["controls:distro", "Labor"],
  ];
  const wrong = expected.filter(([k, l]) => L(k) !== l).map(([k]) => `${k}=${L(k)}`);
  ok(wrong.length === 0, `#233: the eleven relabels (wrong: ${wrong.join(", ") || "none"})`);
  ok(!r233ByKey.has("controls:outputStation") && r233ByKey.get("lighting:cablePackage")?.system === "lighting" && r233ByKey.get("lighting:cablePackage")?.place === "lot" && r233Rows.filter((r) => !r.derived).length === 46,
    "#233: Output station moved to Lighting as Cable Package (a lot row) — still 46 rows");

  // One source: compute() reads name AND unit from the vocabulary.
  const base = r233Default(0);
  const s: R233AState = {
    ...base, venue: "pac", size: "medium", width: 60, depth: 40, grid: 50,
    sys: { ...base.sys, lighting: true, controls: true }, ctrl: { console: true, architectural: true, data: true },
  };
  const C = r233Compute(s);
  const light = C.systems.find((x) => x.key === "lighting")!;
  const ctrl = C.systems.find((x) => x.key === "controls")!;
  const cable = light.items.find((i) => i.key === "lighting:cablePackage");
  ok(cable?.qty === 90 && cable.desc === "Cable Package" && cable.unit === "ea" && !ctrl.items.some((i) => i.key === "controls:outputStation"),
    "#233: Cable Package is on the Lighting system — #233 late: ⌈78 fixtures × 1 × 1.15⌉ = 90 at medium Better (was Output station's 2 × ⌊40/4⌋ = 20)");
  const noLight = r233Compute({ ...s, sys: { ...s.sys, lighting: false } });
  ok(!noLight.systems.some((x) => x.key === "lighting" && x.items.some((i) => i.key === "lighting:cablePackage")),
    "#233: …and follows Lighting — with Lighting out of scope there is no Cable Package, whatever Controls/Data say");
  const everyItem = C.systems.flatMap((x) => x.items);
  ok(everyItem.every((i) => r233ByKey.get(i.key)?.label === i.desc && r233ByKey.get(i.key)?.unit === i.unit),
    "#233: every emitted item's name and unit are the vocabulary's");
  const engSrc = readFileSync(join(process.cwd(), "src/app/(app)/design/quick/engine.ts"), "utf8");
  ok(engSrc.includes('from "@/lib/design/equipment-vocab"') && !/\beq\(\s*"[a-z]+:[a-zA-Z]+",\s*"/.test(engSrc) &&
      !/addFix\("[a-z]+", fx\.[a-z]+, "/.test(engSrc) && !/addDrape\([^)]*"curtains:[a-z]+", "/.test(engSrc),
    "#233: compute() carries no item-name literals — one source");
  const vocabSrc = readFileSync(join(process.cwd(), "src/lib/design/equipment-vocab.ts"), "utf8");
  ok(!/^import\s+(?!type\b)[^;]*from\s+"@\/app\/\(app\)\/design\/quick\/engine"/m.test(vocabSrc),
    "#233: the vocabulary imports only types from the engine (no runtime cycle)");

  // Quick Design qty overrides keyed by the OLD label read under the new one.
  const cleaned = r233Clean({ better: { rigging: { "Aircraft cable": 900, Pipe: 12 }, controls: { "Output station": 7, "Distro system": 1, Console: 2 } } }, true);
  ok(cleaned.better?.rigging?.["Suspension Method"] === 900 && cleaned.better?.rigging?.Pipe === 12 && !("Aircraft cable" in (cleaned.better?.rigging || {})),
    "#233: an override saved under an old label reads under the new label");
  ok(!("Cable Package" in (cleaned.better?.lighting || {})) && cleaned.better?.controls?.["Output station"] === 7 && cleaned.better?.controls?.Labor === 1 && cleaned.better?.controls?.Console === 2,
    "D393: a typed Output-station qty does NOT carry to Lighting · Cable Package — it's counted per cable now, not by the old row's math, so it just sits inertly under controls (no live row reads it); unrenamed rows are untouched");
  const both = r233Clean({ good: { rigging: { "Aircraft cable": 5, "Suspension Method": 8 } } }, true);
  ok(both.good?.rigging?.["Suspension Method"] === 8 && Object.keys(both.good?.rigging || {}).length === 1,
    "#233: when both labels were saved, the new label's value wins");
  const hyd = r233Hydrate({ config: { ...r233Default(0), qtyOverrides: { best: { rigging: { "Chain wrap, 3 ft": 3 } } }, overrideUnits: { "curtains:Scenery track": "ft" } } }, 0);
  ok(hyd.qtyOverrides.best?.rigging?.["Batten Termination"] === 3,
    "#233: a saved design hydrates its old overrides under the new labels (screen and server share this read)");
  const aliasTargetsLive = [...(r233LabelAliases?.values() ?? [])].every((to) => {
    const i = to.indexOf(":");
    return r233Rows.some((r) => r.system === to.slice(0, i) && r.label === to.slice(i + 1));
  });
  ok(r233LabelAliases?.size === 10 && !r233LabelAliases?.has("controls:Output station") && aliasTargetsLive,
    "D393: ten label aliases, each pointing at a live row — no controls:Output station → lighting:Cable Package entry");

  // Equipment map: D393 removed the controls:outputStation → lighting:cablePackage
  // key alias — an old part mapping stored under the old key is now simply
  // unknown (EQUIPMENT_ROW_BY_KEY has no controls:outputStation row) and is
  // dropped, never carried onto Cable Package.
  const cell = { kind: "part", sku: "CAB-1" };
  const oldOnly = r233Sanitize({ "controls:outputStation": { tiers: { good: cell }, updatedBy: "J", updatedAt: 1 } });
  ok(!("lighting:cablePackage" in oldOnly) && !("controls:outputStation" in oldOnly),
    "D393: a stored controls:outputStation row does NOT carry to lighting:cablePackage — it's dropped, leaving Cable Package unmapped");
  const newOnly = r233Sanitize({ "controls:outputStation": { tiers: { good: cell } }, "lighting:cablePackage": { tiers: { good: { kind: "part", sku: "CAB-2" } } } });
  const nc = newOnly["lighting:cablePackage"]?.tiers.good;
  ok(nc?.kind === "part" && nc.sku === "CAB-2" && !("controls:outputStation" in newOnly),
    "D393: a directly-saved lighting:cablePackage row reads normally regardless of any old controls:outputStation entry alongside it");
  const cleared = r233Sanitize({ "controls:outputStation": { tiers: { good: cell } }, "lighting:cablePackage": null });
  ok(!("lighting:cablePackage" in cleared), "D393: clearing Cable Package (null) keeps it cleared — the old key never resurrects it");
  ok(r233KeyAliases?.size === 0 && r233KeyAliases?.get("controls:outputStation") === undefined,
    "D393: no key alias for Output station — Cable Package starts unmapped, not carried from an old part mapping");
  ok(r233Hints["lighting:cablePackage"] === undefined && !("controls:outputStation" in r233Hints),
    "#233 late review: the row has no 'was' hint — the old Output-station price was scaled to the pre-#233-late count and no longer applies; the row starts unmapped");
}

/* --- #229: "Not included" — a resolved Equipment-map cell: $0, never Incomplete, never placed, never quoted --- */
import {
  sanitizeEquipCell as n229Cell, sanitizeEquipmentMap as n229Map, mergeEquipRow as n229Merge, rowStatus as n229Status,
  priceCell as n229Price, buildEquipmentPriceTable as n229Table, type EquipmentMap as N229Map,
} from "@/lib/design/equipment-map";
import { EQUIPMENT_ROW_BY_KEY as n229ByKey } from "@/lib/design/equipment-vocab";
import { equipmentMapView as n229View, mapSummary as n229Summary } from "@/lib/design/equipment-map-view";
import { applyEquipment as n229Apply } from "@/lib/design/equipment-pricing";
import { targetsFromSystems as n229Targets, needsPartCount as n229Needs } from "@/lib/design/scope-targets";
import { autoEstimateCards as n229Cards, autoQuoteNeedsPart as n229AutoNeeds } from "@/lib/design/auto-estimate";
import { partIdForLine as n229PartId } from "@/lib/design/grid-auto-layout";
import { compute as n229Compute, defaultAState as n229Default } from "@/app/(app)/design/quick/engine";
{
  ok(JSON.stringify(n229Cell({ kind: "none", junk: 1 })) === '{"kind":"none"}', "#229: a Not included cell sanitizes to { kind: \"none\" }");
  const m = n229Merge(undefined, { tiers: { good: { kind: "none" }, better: { kind: "part", sku: "P1" }, best: { kind: "part", sku: "P1" } } }, "Jeff", 5);
  ok(m.ok && m.row.tiers.good?.kind === "none" && m.row.tiers.better?.kind === "part", "#229: the editor saves Not included for one tier");
  const same = n229Merge(undefined, { tiers: { good: { kind: "none" } }, sameAll: true }, "Jeff", 5);
  ok(same.ok && same.row.tiers.best?.kind === "none", "#229: …or for all tiers (Same for all tiers)");
  const stored = n229Map({ "rigging:varSpeedHoist": { tiers: { good: { kind: "none" } }, sameAll: true, updatedBy: "J", updatedAt: 1 } });
  ok(n229Status(stored["rigging:varSpeedHoist"]) === "mapped", "#229: a Not included row reads Mapped (resolved), never Needs a part");

  const ctx = { parts: new Map([["P1", { sku: "P1", desc: "Hoist", unit: "ea", cost: 100, list: 150 }]]), fixtures: new Map(), margin: 0.3 };
  const p = n229Price({ kind: "none" }, n229ByKey.get("rigging:varSpeedHoist")!, ctx);
  ok(p.status === "none" && p.unitCost === 0 && p.unitSell === 0 && p.desc === "Not included", "#229: Not included prices $0 with status none");
  ok(n229Price({ kind: "none" }, n229ByKey.get("curtains:border")!, ctx).status === "none", "#229: a curtain row can be Not included too");

  const map: N229Map = { "lighting:par": { tiers: { good: { kind: "none" } }, sameAll: true, updatedBy: "J", updatedAt: 1 } };
  const table = n229Table(map, ctx);
  const base = n229Default(0);
  const lightOnly = { rigging: false, curtains: false, lighting: true, controls: false, audio: false, video: false, acoustical: false, pit: false };
  const [priced] = n229Apply(n229Compute({ ...base, sys: lightOnly }).systems.filter((x) => x.key === "lighting"), "good", table);
  const par = priced.items.find((i) => i.key === "lighting:par")!;
  ok(par.status === "none" && par.price === 0 && par.cost === 0 && !par.ref, "#229: the pipeline carries a Not included line at $0 with no product behind it");
  const others = priced.items.filter((i) => i.qty > 0 && i.status === "needs-part").length;
  ok(n229Targets([priced]).lighting!.needsPart === others && n229Needs([priced]) === others, "#229: Not included is never counted as needs-a-part (the Incomplete gate ignores it)");

  const cards = n229Cards({ ...base, sys: lightOnly }, { tierByScope: { lighting: "good" }, overrides: {} }, table, {});
  const line = cards[0].lines.find((l) => l.rowKey === "lighting:par")!;
  ok(line.status === "none" && line.total === 0 && n229PartId(line, "good") === null && cards[0].lines.filter((l) => l.status === "needs-part").length === cards[0].needsPart,
    "#229: an Auto card line is Not included — $0, not needs-a-part, never placed");
  ok(n229AutoNeeds(cards, { tierByScope: { lighting: "good" } }) === cards[0].needsPart, "#229: Not included never refuses a Grid quote");

  const view = n229View(map, ctx, {});
  const row = view.find((r) => r.key === "lighting:par")!;
  ok(row.status === "mapped" && row.cells.every((c) => c.kind === "none" && c.title === "Not included" && c.problem === null && c.input?.kind === "none"),
    "#229: the Equipment map shows Not included and re-posts it");
  ok(n229Summary(view).mapped === 1, "#229: the summary counts a Not included row as Mapped");

  const emc = readFileSync(join(process.cwd(), "src/app/(app)/design/grid/settings/equipment-map/equipment-map-client.tsx"), "utf8");
  ok(emc.includes('<option value="none">Not included</option>') && emc.includes('k === "none" ? { kind: "none" }'), "#229: the cell editor offers Not included");
  const card = readFileSync(join(process.cwd(), "src/app/(app)/design/grid/[id]/equipment-card.tsx"), "utf8");
  ok(card.includes('l.status === "none"') && card.includes("Not included in this tier"), "#229: Auto cards say Not included");
  const qd = readFileSync(join(process.cwd(), "src/app/(app)/design/quick/quick-design-client.tsx"), "utf8");
  ok(qd.includes('it.status === "none" ? "Not included"'), "#229: Quick Design's BOM says Not included");
}

/* --- #228: Hardware assemblies — a third FixtureKind through the builder, the Equipment map and Auto --- */
import {
  sanitizeFixtureInput as h228Sanitize, fixtureLineParts as h228Lines, resolveFixture as h228Resolve, allAssembliesFrom as h228From,
  type FixtureRecord as H228Rec,
} from "@/lib/fixture-assemblies";
import { normalizeFixtureRow as h228Normalize } from "@/lib/fixtures-convert";
import { assemblyOptions as h228Opts, equipmentMapView as h228View } from "@/lib/design/equipment-map-view";
import { priceCell as h228Price, type EquipmentMap as H228Map } from "@/lib/design/equipment-map";
import { EQUIPMENT_ROW_BY_KEY as h228ByKey } from "@/lib/design/equipment-vocab";
import { assemblyPartId as h228AsmId, virtualPartsFor as h228Virtual } from "@/lib/design/grid-virtual-parts";
import { assemblySwapCandidates as h228Cand, scopeLabelOf as h228ScopeLabel } from "@/lib/design/auto-estimate";
{
  const noParts = h228Sanitize({ kind: "hardware", label: "Chain Wrap", description: "", parts: [] });
  ok(!noParts.ok && /part/i.test(noParts.error), "#228: hardware needs at least one part");
  const hw = h228Sanitize({ kind: "hardware", label: " Chain Wrap ", description: "", scope: "Audio", lightEngineSku: "IGNORED", parts: [{ sku: "CH-3", qty: 1 }, { sku: "SHK-1", qty: 2 }] });
  ok(hw.ok && hw.value.kind === "hardware" && hw.value.label === "Chain Wrap" && hw.value.lightEngineSku === "" && hw.value.lensSku === null && !("scope" in hw.value) && (hw.value.parts || []).length === 2,
    "#228: a hardware assembly keeps one parts list — no light engine, no scope of its own");
  const dup = h228Sanitize({ kind: "hardware", label: "X", description: "", parts: [{ sku: "A", qty: 1 }, { sku: "A", qty: 1 }] });
  ok(!dup.ok && /two lines/.test(dup.error), "#228: hardware refuses a SKU on two lines, like a system");

  const rec: H228Rec = {
    id: "SA-HW1", kind: "hardware", label: "Chain Wrap", description: "", lightEngineSku: "", lensSku: null,
    lines: { data: [], power: [], mounting: [], accessories: [] }, parts: [{ sku: "CH-3", qty: 1 }, { sku: "SHK-1", qty: 2 }],
    createdAt: 1, createdBy: "t", updatedAt: 1, updatedBy: "t",
  };
  const catalog = new Map([
    ["CH-3", { sku: "CH-3", desc: "Chain 3 ft", unit: "ea", cost: 10, list: 20 }],
    ["SHK-1", { sku: "SHK-1", desc: "Shackle", unit: "ea", cost: 5, list: 8 }],
  ]);
  const r = h228Resolve(rec, catalog);
  ok(h228Lines(rec).length === 2 && h228Lines(rec).every((x) => x.slot === "parts") && r.cost === 20 && r.sell === 36,
    "#228: hardware prices its parts list (cost 10 + 2×5, sell 20 + 2×8)");
  const norm = h228Normalize({ ...rec } as unknown as Record<string, unknown> & { id: string });
  ok(norm.kind === "hardware" && (norm.parts || []).length === 2, "#228: a stored hardware row normalizes as hardware, keeping its parts");
  // #246/#247 reversed #228's "never in the pickers": both pickers list hardware now, as its own group.
  ok(h228From([rec], catalog).map((a) => `${a.kind}:${a.id}`).join(",") === "hardware:SA-HW1", "#228/#247: hardware is listed in the Estimator / Quick Design pickers, as hardware");

  const ctx = { parts: catalog, fixtures: new Map([[rec.id, rec]]), margin: 0.3 };
  const opt = h228Opts([rec], ctx)[0];
  ok(opt?.kind === "hardware" && opt.unitSell === 36 && opt.unitCost === 20, "#228: the Equipment-map picker lists hardware assemblies with live totals");
  const pc = h228Price({ kind: "assembly", id: rec.id }, h228ByKey.get("rigging:chainWrap")!, ctx);
  ok(pc.status === "assembly" && pc.desc === "Chain Wrap" && pc.unitSell === 36, "#228: Batten Termination maps to the Chain Wrap hardware assembly");
  const map: H228Map = { "rigging:chainWrap": { tiers: { good: { kind: "assembly", id: rec.id } }, sameAll: true, updatedBy: "J", updatedAt: 1 } };
  ok(h228View(map, ctx, {}).find((row) => row.key === "rigging:chainWrap")!.cells[0].detail === "Hardware", "#228: the map cell names it Hardware");

  const [vp] = h228Virtual([h228AsmId(rec.id)], map, ctx);
  ok(vp?.gridScope === "Rigging" && !vp.virtualDead && vp.list === 36, "#228: a hardware virtual part draws on its mapped row's system (Rigging), not the Lighting default");
  const onCurtains: H228Map = { "curtains:scenerytrack": { tiers: { good: { kind: "assembly", id: rec.id } }, sameAll: true, updatedBy: "J", updatedAt: 1 } };
  ok(h228Virtual([h228AsmId(rec.id)], onCurtains, ctx)[0]?.gridScope === "Curtains", "#228: …mapped on a Curtains row it draws on Curtains");
  ok(h228Virtual([h228AsmId(rec.id)], {}, ctx)[0]?.gridScope === "Rigging", "#228: an unmapped (swapped-in) hardware assembly defaults to Rigging");

  const cands = [{ kind: "hardware" as const, id: "hw" }, { kind: "fixture" as const, id: "fx" }, { kind: "system" as const, scope: "Rigging", id: "sys" }];
  ok(h228Cand(cands, h228ScopeLabel("rigging")).map((f) => f.id).join(",") === "hw,sys" && !h228Cand(cands, h228ScopeLabel("lighting")).some((f) => f.id === "hw"),
    "#228: hardware is a swap candidate on Rigging rows only");

  const fb = readFileSync(join(process.cwd(), "src/app/(app)/design/assemblies/fixture-builder.tsx"), "utf8");
  ok(fb.includes('hardware: "Hardware"') && fb.includes('start("hardware")'), "#228: the builder has a Hardware tab and a New assembly → Hardware button");
  const ff = readFileSync(join(process.cwd(), "src/app/(app)/design/assemblies/fixture-form.tsx"), "utf8");
  ok(ff.includes('const isParts = draft.kind !== "fixture"') && ff.includes("isHardware"), "#228: the form edits hardware as one parts list");
  const emc = readFileSync(join(process.cwd(), "src/app/(app)/design/grid/settings/equipment-map/equipment-map-client.tsx"), "utf8");
  ok(emc.includes('a.kind === "hardware" ? "Hardware"') && emc.includes("Assembly (fixture, system, hardware or rack)"), "#228: the map picker labels hardware assemblies");
}

/* --- #246: the Estimator's "+ Add assembly" lists every assembly — fixtures, systems and hardware (pure + source) --- */
import {
  allAssembliesFrom as e246From, ASSEMBLY_GROUPS as e246Groups,
  type FixtureRecord as E246Rec,
} from "@/lib/fixture-assemblies";
import { fixtureBomLine as e246Bom, hasHangPosition as e246Hang } from "@/app/(app)/estimator/fixture-bom";
{
  const base = { description: "", lensSku: null, lines: { data: [], power: [], mounting: [], accessories: [] }, createdAt: 1, createdBy: "t", updatedAt: 1, updatedBy: "t" };
  const recs: E246Rec[] = [
    // listFixtures order (by label), kinds interleaved on purpose.
    { ...base, id: "SA-H1", kind: "hardware", label: "Batten wrap", lightEngineSku: "", parts: [{ sku: "E246-CH", qty: 2 }] },
    { ...base, id: "SA-F1", kind: "fixture", label: "Cyc light", lightEngineSku: "E246-ENG", position: "1st elec", circuit: "12" },
    { ...base, id: "SA-S1", kind: "system", label: "Stage wash package", scope: "Lighting", lightEngineSku: "", parts: [{ sku: "E246-ENG", qty: 4 }], position: "stray", circuit: "9" },
    { ...base, id: "SA-F2", kind: "fixture", label: "Wash", lightEngineSku: "E246-ENG" },
    { ...base, id: "SA-S2", kind: "system", label: "Voice lift", scope: "Audio", lightEngineSku: "", parts: [{ sku: "E246-CH", qty: 1 }] },
  ];
  const cat = new Map([
    ["E246-ENG", { sku: "E246-ENG", desc: "Engine", unit: "ea", cost: 100, list: 200 }],
    ["E246-CH", { sku: "E246-CH", desc: "Chain", unit: "ea", cost: 10, list: 25 }],
  ]);
  const all = e246From(recs, cat);
  ok(all.map((a) => `${a.kind}:${a.id}`).join(",") === "fixture:SA-F1,fixture:SA-F2,system:SA-S1,system:SA-S2,hardware:SA-H1",
    "#246: allAssembliesFrom returns fixtures, then systems, then hardware — each in the input (label) order, every row carrying its kind");
  ok(e246Groups.map((g) => g.label).join(",") === "Fixtures,Systems,Hardware,Racks", "#246: the picker's groups are Fixtures / Systems / Hardware (+ #296 Racks)");
  const s1 = all.find((a) => a.id === "SA-S1")!;
  ok(s1.scope === "Lighting" && s1.name === "Stage wash package" && s1.components.length === 1 && s1.components[0].role === "other" && s1.components[0].defaultQty === 4 && s1.components[0].list === 200,
    "#246: a system resolves in the same shape — its scope, its parts list as components");
  ok(!("position" in s1) && !("circuit" in s1) && !("scope" in all.find((a) => a.id === "SA-H1")!), "#246: only a fixture carries a hang position / circuit; hardware has no scope");
  const f1 = all.find((a) => a.id === "SA-F1")!;
  ok(f1.position === "1st elec" && f1.circuit === "12" && f1.kind === "fixture", "#246: a fixture keeps its default hang position / circuit");

  const draft = { componentQty: {}, position: "1st elec", circuit: "12" };
  ok(e246Bom(f1, draft)!.desc.endsWith(" (Pos 1st elec / Ckt 12)"), "#246: a fixture's BOM line still ends in (Pos … / Ckt …)");
  const sysLine = e246Bom(s1, draft)!;
  ok(!/Pos|Ckt/.test(sysLine.desc) && sysLine.price === 800 && sysLine.cost === 400, "#246: a system's BOM line drops a stale Pos / Ckt from the draft, priced 4 × $200");
  ok(!/Pos|Ckt/.test(e246Bom(all.find((a) => a.id === "SA-H1")!, draft)!.desc), "#246: …and so does hardware");
  ok(e246Hang({}) && e246Hang({ kind: "fixture" }) && !e246Hang({ kind: "system" }) && !e246Hang({ kind: "hardware" }), "#246: no kind (a legacy row) reads as a fixture");

  const card = readFileSync(join(process.cwd(), "src/app/(app)/estimator/section-card.tsx"), "utf8");
  ok(card.includes('addBtn("+ Add assembly", p.onToggleFixture') && !card.includes("Configure fixture"), "#246: the section card's button reads \"+ Add assembly\"");
  const modal = readFileSync(join(process.cwd(), "src/app/(app)/estimator/fixture-modal.tsx"), "utf8");
  ok(modal.includes('title="Add assembly"') && modal.includes(">Add assembly</button>") && modal.includes("<optgroup key={g.kind} label={g.label}>")
    && modal.includes("No assemblies yet — build one in the Assembly Builder") && modal.includes(">Qty</label>") && !/[Ff]ixture qty|Add fixture|No fixture assemblies/.test(modal),
    "#246: the modal says Add assembly, groups its options, and reads Qty");
  ok(/\{showHang && <>/.test(modal) && modal.includes("hasHangPosition(assembly)"), "#246: Hang position / Circuit # show only for a fixture");
  const page = readFileSync(join(process.cwd(), "src/app/(app)/estimator/page.tsx"), "utf8");
  ok(page.includes("fixtureAssemblies={allAssembliesFrom(fixtures, catalogRows)}"), "#246: the Estimator page passes every assembly kind");
  const client = readFileSync(join(process.cwd(), "src/app/(app)/estimator/estimator-client.tsx"), "utf8");
  ok(client.includes('fixtureAssemblies.find((item) => (item.kind ?? "fixture") === "fixture")'), "#246: opening the modal preselects the first fixture (never a system)");
}

/* --- #247: Quick Design's lighting fixture picker lists every assembly — fixtures, systems and hardware (pure + source) --- */
import {
  allAssembliesFrom as q247From, groupAssemblies as q247Group, assemblyOptionLabel as q247Label, ASSEMBLY_GROUPS as q247Groups,
  type FixtureRecord as Q247Rec,
} from "@/lib/fixture-assemblies";
import { fixturePricesFrom as q247Prices, pickedFixtureIds as q247Picked } from "@/lib/stores/design-pricing";
import { fixtureOverridesFor as q247Overrides, quickDesignPrice as q247Price } from "@/lib/design/equipment-pricing";
import { EQUIPMENT_ROWS as q247Rows } from "@/lib/design/equipment-vocab";
import { defaultAState as q247Default } from "@/app/(app)/design/quick/engine";
{
  const read = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const base = { description: "", lensSku: null, lines: { data: [], power: [], mounting: [], accessories: [] }, createdAt: 1, createdBy: "t", updatedAt: 1, updatedBy: "t" };
  const recs: Q247Rec[] = [
    { ...base, id: "SA-Q47H", kind: "hardware", label: "Pipe clamp kit", lightEngineSku: "", parts: [{ sku: "Q247-CL", qty: 2 }] },
    { ...base, id: "SA-Q47F", kind: "fixture", label: "Par wash", lightEngineSku: "Q247-ENG" },
    { ...base, id: "SA-Q47S", kind: "system", label: "Stage wash package", scope: "Lighting", lightEngineSku: "", parts: [{ sku: "Q247-ENG", qty: 4 }] },
    { ...base, id: "SA-Q47Z", kind: "system", label: "Unpriced package", scope: "Lighting", lightEngineSku: "", parts: [{ sku: "Q247-NOPE", qty: 1 }] },
  ];
  const parts = new Map([
    ["Q247-ENG", { sku: "Q247-ENG", desc: "Engine", unit: "ea", cost: 100, list: 200 }],
    ["Q247-CL", { sku: "Q247-CL", desc: "Clamp", unit: "ea", cost: 10, list: 25 }],
  ]);

  // The list: every kind, grouped, and the client rows carry kind (+ a system's scope).
  const list = q247From(recs, parts);
  ok(list.map((a) => `${a.kind}:${a.id}`).join(",") === "fixture:SA-Q47F,system:SA-Q47S,system:SA-Q47Z,hardware:SA-Q47H", "#247: allAssembliesFrom lists fixtures, systems, then hardware");
  const legacy: Array<{ id: string; name: string; kind?: "fixture" | "system" | "hardware" }> = [{ id: "legacy", name: "Old fixture" }];
  const groups = q247Group([...list.map(({ id, name, kind }) => ({ id, name, kind })), ...legacy]);
  ok(groups.map((g) => `${g.label}:${g.items.map((i) => i.id).join("+")}`).join(",") === "Fixtures:SA-Q47F+legacy,Systems:SA-Q47S+SA-Q47Z,Hardware:SA-Q47H"
    && q247Group([{ id: "h", name: "H", kind: "hardware" as const }]).map((g) => g.label).join(",") === "Hardware"
    && q247Groups.map((g) => g.label).join(",") === "Fixtures,Systems,Hardware,Racks",
    "#247: groupAssemblies — Fixtures / Systems / Hardware in order, a kind-less row reads as a fixture, empty groups dropped");
  ok(q247Label({ name: "Stage wash package", kind: "system", scope: "Lighting" }) === "Stage wash package (Lighting)" && q247Label({ name: "Pipe clamp kit", kind: "hardware" }) === "Pipe clamp kit" && q247Label({ name: "Par wash" }) === "Par wash",
    "#247: a system option names its scope, the Estimator's format; fixtures and hardware show the bare name");

  // Pricing: a system / hardware pick prices through priceCell's assembly branch — no kind filter anywhere.
  const ctx = { parts, fixtures: new Map(recs.map((r) => [r.id, r])), margin: 0.3 };
  const cfg = { ...q247Default(10), tier: "better", fixtureAssemblies: { par: "SA-Q47S", front: "SA-Q47H", cyc: "SA-Q47F" } } as unknown as Record<string, unknown>;
  const rec = { tier: "better", config: cfg };
  const ids = q247Picked(rec);
  ok(ids.sort().join(",") === "SA-Q47F,SA-Q47H,SA-Q47S", "#247: pickedFixtureIds returns system and hardware picks too (serverDesignPrice / serverDesignPrices / quickPromoteCheck load these)");
  const fp = q247Prices([...ids, "SA-Q47Z"], ctx);
  ok(fp["SA-Q47S"]?.status === "assembly" && fp["SA-Q47S"].unitSell === 800 && fp["SA-Q47S"].unitCost === 400 && fp["SA-Q47H"]?.status === "assembly" && fp["SA-Q47H"].unitSell === 50 && fp["SA-Q47H"].unitCost === 20,
    "#247: fixturePricesFrom prices a system pick (4 × $200 sell / $100 cost) and a hardware pick (2 × $25 / $10) from their parts lists");
  ok(fp["SA-Q47Z"]?.status === "needs-part", "#247: a system with no priced parts stays needs-a-part");
  const ov = q247Overrides(cfg.fixtureAssemblies as Record<string, string>, fp);
  ok(ov["lighting:par"]?.status === "assembly" && ov["lighting:par"].desc === "Stage wash package" && ov["lighting:front"]?.status === "assembly" && ov["lighting:front"].desc === "Pipe clamp kit",
    "#247: fixtureOverridesFor turns a system / hardware pick into its lighting row's price");
  const table = {
    margin: 0.3,
    byTier: Object.fromEntries((["good", "better", "best"] as const).map((t) => [t, Object.fromEntries(q247Rows.map((r) => [r.key, { status: "allowance" as const, ref: r.key, desc: r.label, unit: r.unit, unitCost: 10, unitSell: 14.29 }]))])) as never,
  };
  const rates = { freightPct: 5, contingencyPct: 10 };
  const plain = q247Price({ tier: "better", config: { ...cfg, fixtureAssemblies: {} } }, table, {}, rates);
  const picked = q247Price(rec, table, fp, rates);
  ok(plain.needsPart === 0 && picked.needsPart === 0 && picked.budget > plain.budget,
    `#247: the server's Quick Design price (quickDesignPrice) prices system + hardware picks and stays complete (${plain.budget} → ${picked.budget})`);
  const dead = q247Price({ tier: "better", config: { ...cfg, fixtureAssemblies: { par: "SA-Q47Z" } } }, table, fp, rates);
  ok(dead.needsPart > 0, "#247: an unpriceable system pick blocks Add to Quotes (needs a part), like a fixture pick");

  // Source: the page, the picker, and the server paths.
  const qp = read("src/app/(app)/design/quick/page.tsx");
  ok(qp.includes("allAssembliesFrom(fixtureRecords, catalogRows)") && !qp.includes("fixtureAssembliesFrom") && qp.includes("kind: assembly.kind") && qp.includes("scope: assembly.scope"),
    "#247: Quick Design's page lists every assembly kind and passes kind + scope to the picker");
  ok(!read("src/lib/fixture-assemblies.ts").includes("export function fixtureAssembliesFrom") && !/estimatorAssembliesFrom|ESTIMATOR_ASSEMBLY_GROUPS/.test(read("src/lib/fixture-assemblies.ts")),
    "#247: the fixtures-only helper is gone; the all-kinds list and groups have neutral names");
  const panel = read("src/components/design/scope-inputs-panel.tsx");
  const iDead = panel.indexOf("(deleted — choose another)"), iGen = panel.indexOf(">Generic allowance</option>"), iGrp = panel.indexOf("<optgroup key={g.kind} label={g.label}>");
  ok(panel.includes("groupAssemblies(fixtureAssemblies)") && panel.includes("assemblyOptionLabel(assembly)") && iDead > 0 && iDead < iGen && iGen < iGrp,
    "#247: the picker keeps the dead pick, then Generic allowance, then Fixtures / Systems / Hardware optgroups");
  ok(panel.includes("fixtureAssemblies?: AssemblyPickerOption[]") && read("src/app/(app)/design/quick/quick-design-client.tsx").includes("fixtureAssemblies: AssemblyPickerOption[]"), "#247: the client list type carries kind / scope");
  const modal = read("src/app/(app)/estimator/fixture-modal.tsx");
  ok(modal.includes("groupAssemblies(assemblies)") && modal.includes("assemblyOptionLabel(item)"), "#247: the Estimator's modal shares the same grouping and option label");
  const dp = read("src/lib/stores/design-pricing.ts");
  const em = read("src/lib/stores/equipment-map.ts");
  ok(!/kind === "fixture"/.test(dp) && !/kind === "fixture"/.test(em), "#247: no Quick Design server price path (design-pricing, loadEquipPriceCtx) filters picks to fixtures");
  const acts = read("src/app/(app)/design/assemblies/actions.ts");
  const rc = acts.slice(acts.indexOf("const revalidateConsumers"), acts.indexOf("};", acts.indexOf("const revalidateConsumers")));
  ok(rc.includes('"/design/quick"') && !/kind/.test(rc), "#247: saving or deleting any assembly kind revalidates Quick Design");
}

/* --- #231/#232 T1: wire pull + system labor — rules and formulas (pure) --- */
import * as wl231 from "@/lib/design/wire-labor";
import { GROUPS as wl231Groups } from "@/lib/stores/pricing";
{
  const d = wl231.defaultWireLaborRules();
  ok(wl231.WIRE_SYSTEMS.every((s) => d.wire[s].runs === 0 && d.wire[s].mult.good === 1 && d.wire[s].mult.better === 1.15 && d.wire[s].mult.best === 1.3),
    "#231: every wire system defaults to 0 runs (off) and ×1.0 / ×1.15 / ×1.3");
  ok(wl231.LABOR_SYSTEMS.every((s) => d.labor[s].pct === 18 && d.labor[s].mult.good === 1 && d.labor[s].mult.better === 1.15 && d.labor[s].mult.best === 1.3),
    "#232: every labor system defaults to 18% and ×1.0 / ×1.15 / ×1.3");
  const stored: Record<string, unknown> = { "wire.lighting.runs": 2, "wire.lighting.best": 1.5, "labor.audio.pct": 25, "labor.video.pct": -4, "wire.audio.runs": 999, "labor.pit.good": null };
  const r = wl231.wireLaborRulesFrom((id) => stored[id]);
  ok(r.wire.lighting.runs === 2 && r.wire.lighting.mult.best === 1.5 && r.labor.audio.pct === 25 && r.labor.video.pct === 18 && r.wire.audio.runs === wl231.RUNS_MAX && r.labor.pit.mult.good === 1,
    "#231/#232: stored rates are read, junk falls back to the default, and values cap at the rule maximum");
  const dims = wl231.wireDimsOf({ width: 40, depth: 30 });
  const lightRule = { runs: 2, mult: d.wire.lighting.mult };
  const f = wl231.wirePullFeet(dims, lightRule, "better");
  ok(f.feet === 161 && f.missing.join() === "houseDepth", `#231: feet = (40 + 30 + 0) × 2 runs × 1.15 = 161, house depth missing (${f.feet})`);
  ok(wl231.wirePullNote(f.missing) === "House depth isn't in the design — not counted", "#231: a missing dimension is noted on the line");
  ok(wl231.wirePullFeet(dims, lightRule, null).feet === 140, "#231: no tier chosen → ×1.0");
  ok(wl231.wirePullFeet(dims, { runs: 2.5, mult: d.wire.lighting.mult }, "best").feet === 228, "#231: footage rounds UP to a whole foot (227.5 → 228)");
  ok(wl231.wirePullFeet(dims, { runs: 0, mult: d.wire.lighting.mult }, "best").feet === 0, "#231: 0 runs → no footage");
  const none = wl231.wirePullFeet({}, { runs: 3, mult: d.wire.lighting.mult }, "good");
  ok(none.feet === 0 && none.missing.length === 3, "#231: every dimension missing → 0 ft, all three noted");
  ok(wl231.laborAmount(10000, d.labor.lighting, "better") === 2070 && wl231.laborAmount(10000, d.labor.lighting, null) === 1800 && wl231.laborAmount(10000, d.labor.lighting, "best") === 2340,
    "#232: labor = material × 18% × 1.15 / ×1.0 (none) / ×1.3");
  ok(wl231.laborAmount(0, d.labor.lighting, "best") === 0, "#232: no material → no labor");
  const fr = wl231.laborFracsFor(d, "good");
  ok(Object.keys(fr).length === 8 && Object.values(fr).every((v) => v === 0.18), "#232: at Good every Quick Design system's fraction is today's flat 18%");
  const lines = wl231.gridLaborLines({ lighting: 10000, general: 500, audio: 0 }, (s) => (s === "lighting" ? "better" : null), d, {});
  ok(lines.map((l) => `${l.sku}=${l.amount}`).join() === "labor:lighting=2070,labor:general=90", `#232: one Grid labor line per system with material, in system order (${lines.map((l) => l.sku).join()})`);
  const ov = wl231.gridLaborLines({ lighting: 10000 }, () => "better", d, { lighting: 1500, audio: 0 });
  ok(ov[0].amount === 1500 && ov[0].computed === 2070 && ov[0].overridden && ov[1]?.system === "audio" && ov[1].amount === 0 && ov[1].overridden,
    "#232: a typed $ overrides; an override on a system with no material still shows, so it can be reset");
  ok(wl231.laborLineDesc("lighting") === "Labor — Lighting" && wl231.isLaborSku("labor:general") && !wl231.isLaborSku("LIG-LBR"), "#232: labor lines read 'Labor — <System>' under a labor: sku");
  ok(JSON.stringify(wl231.sanitizeLaborOverrides({ lighting: 1200.5, audio: -1, bogus: 5, video: "7", rigging: 2e7 })) === '{"lighting":1200.5}',
    "#232: overrides keep known systems with a $0–$10M number");
  ok(JSON.stringify(wl231.applyLaborOverride({ lighting: 5 }, "audio", 0)) === '{"lighting":5,"audio":0}' && JSON.stringify(wl231.applyLaborOverride({ lighting: 5 }, "lighting", null)) === "{}",
    "#232: set or clear one system's override");
  ok(wl231.laborSystemOf("rigging", "Lighting") === "rigging" && wl231.laborSystemOf(undefined, "Audio") === "audio" && wl231.laborSystemOf(null, "Unscoped") === "general" && wl231.laborSystemOf(null, "constructor") === "general",
    "#232: an Auto tag's scope wins, then the part's Grid scope, else General");
  const ids = new Set(wl231Groups.flatMap((g) => g.items.map((it) => it.id)));
  ok(wl231.WIRE_SYSTEMS.every((s) => ["runs", "good", "better", "best"].every((x) => ids.has(`wire.${s}.${x}`))) && wl231.LABOR_SYSTEMS.every((s) => ["pct", "good", "better", "best"].every((x) => ids.has(`labor.${s}.${x}`))),
    "#231/#232: Estimating Rules carries runs / labor % and Good/Better/Best × for every system");
  const wlSrc = readFileSync(join(process.cwd(), "src/lib/design/wire-labor.ts"), "utf8");
  ok([...wlSrc.matchAll(/^import\s+(?!type\b)[^;]*?from\s+"([^"]+)";/gm)].length === 0, "#231/#232: wire-labor.ts has type-only imports — safe for client components");

  // Controller decision: an unset per-system labor % takes the CURRENT stored flat install %, so Good-tier totals never shift on deploy.
  const legacy: Record<string, unknown> = { [wl231.LEGACY_INSTALL_PCT_ID]: 20, "labor.audio.pct": 25 };
  const lg = wl231.wireLaborRulesFrom((id) => legacy[id]);
  const lgFr = wl231.laborFracsFor(lg, "good");
  ok(wl231.LABOR_SYSTEMS.every((s) => lg.labor[s].pct === (s === "audio" ? 25 : 20)) && lgFr.lighting === 0.2 && lgFr.audio === 0.25,
    "#232: an unset system's labor % defaults to the stored install % (20 → every system 20%, Good fraction 0.20); a per-system value still wins");
  const junk = (v: unknown) => wl231.wireLaborRulesFrom((id) => (id === wl231.LEGACY_INSTALL_PCT_ID ? v : undefined)).labor.lighting.pct;
  ok(junk(-3) === 18 && junk("20") === 18 && junk(Number.NaN) === 18 && junk(null) === 18 && junk(999) === wl231.LABOR_PCT_MAX && junk(0) === 0,
    "#232: a missing or junk stored install % leaves the 18% default; an over-max one caps; a stored 0 stays 0");
}

/* #231/#232 T1 (b) — the rules loader against the scratch DB. Leaves the defaults behind. */
async function wireLabor231AsyncChecks(): Promise<void> {
  const P = await import("@/lib/stores/pricing");
  const fresh = await P.loadWireLaborRules();
  ok(JSON.stringify(fresh) === JSON.stringify(wl231.defaultWireLaborRules()), "#231/#232: a fresh database reads the default rules");
  await P.setValue("wire.lighting.runs", 3);
  await P.setValue("labor.audio.pct", 22.5);
  const set = await P.loadWireLaborRules();
  ok(set.wire.lighting.runs === 3 && set.labor.audio.pct === 22.5 && set.wire.audio.runs === 0, "#231/#232: Estimating Rules edits reach the loader");
  // The flat install % written straight into the blob (Task 3 retires its registry row; the stored value stays).
  await setBlob219("pricing_rules", { [wl231.LEGACY_INSTALL_PCT_ID]: 21 });
  const legacy = await P.loadWireLaborRules();
  ok(legacy.labor.lighting.pct === 21 && legacy.labor.general.pct === 21 && legacy.labor.audio.pct === 22.5 && (await P.value("labor.lighting.pct")) === 21,
    "#232: a stored install % of 21 seeds every unset system's labor % in the loader and on Estimating Rules");
  await setBlob219("pricing_rules", { [wl231.LEGACY_INSTALL_PCT_ID]: null });
  await P.setValue("wire.lighting.runs", 0);
  await P.setValue("labor.audio.pct", 18);
  ok(JSON.stringify(await P.loadWireLaborRules()) === JSON.stringify(wl231.defaultWireLaborRules()), "#231/#232: resetting restores the defaults (later suites see the defaults)");
}

