async function finalWaveAAsyncChecks(): Promise<void> {
  // #216 final — a save shaped like the company modal → saveCustomerAction.
  const CO = fixtureId(216, "fwa-move");
  const base = {
    id: "fw1", label: "Main Hall", locationName: "", primary: true, venueKind: "proscenium",
    address: "1 Main St", city: "Omaha", state: "NE", zip: "68102" as string | null,
    lat: 41.25 as number | null, lng: -95.9 as number | null,
    travelMiles: 12 as number | null, travelMin: 20 as number | null,
  };
  const site = async () => (await v216Sites(CO)).find((s) => s.legacyLocId === "fw1") ?? null;
  const modalSave = async (patch: Partial<typeof base>) => {
    const locations = await fwaApplyMove(CO, [{ ...base, ...patch }]);
    await upsertCustomer({ id: CO, name: "Move Rule Hall Co", type: "Education", locations, contacts: [] });
  };
  try {
    await upsertCustomer({ id: CO, name: "Move Rule Hall Co", type: "Education", locations: [base], contacts: [] });
    let s = await site();
    ok(!!s && s.zip === "68102" && Number(s.lat) === 41.25 && s.travelMiles === "12", "#216 final: fixture venue stored with coordinates, zip and drive distance");

    // Unchanged address, coordinates/zip dropped by the client → stored kept.
    await modalSave({ zip: null, lat: null, lng: null });
    s = await site();
    ok(!!s && Number(s.lat) === 41.25 && Number(s.lng) === -95.9 && s.zip === "68102" && s.travelMiles === "12" && s.travelMin === "20",
      "#216 final: modal save with an unchanged address keeps coordinates, zip and drive distance");

    // Unchanged address, travel typed → the manual override is honoured.
    await modalSave({ travelMiles: 30, travelMin: 45 });
    s = await site();
    ok(!!s && s.travelMiles === "30" && s.travelMin === "45" && Number(s.lat) === 41.25, "#216 final: an unchanged venue keeps a hand-typed drive distance");

    // Moved by hand: coordinates + zip dropped by the modal, travel echoed.
    await modalSave({ address: "2 Oak St", zip: null, lat: null, lng: null, travelMiles: 30, travelMin: 45 });
    s = await site();
    ok(!!s && s.address === "2 Oak St" && s.lat == null && s.lng == null && s.zip == null && s.travelMiles == null && s.travelMin == null,
      "#216 final: modal save moved by hand clears coordinates, zip and drive distance");

    // Picked hit: its coordinates + zip land; the stale (null) travel stays null.
    await modalSave({ address: "5 Elm St", city: "Lincoln", zip: "68508", lat: 40.8, lng: -96.7, travelMiles: null, travelMin: null });
    s = await site();
    ok(!!s && Number(s.lat) === 40.8 && Number(s.lng) === -96.7 && s.zip === "68508" && s.travelMiles == null,
      "#216 final: modal save of a picked hit sets its coordinates and zip");

    // Picked again + Route run after the move → the fresh distance is kept.
    await modalSave({ address: "9 Pine St", city: "Lincoln", zip: "68510", lat: 40.81, lng: -96.68, travelMiles: 55, travelMin: 60 });
    s = await site();
    ok(!!s && s.zip === "68510" && s.travelMiles === "55" && s.travelMin === "60", "#216 final: a drive distance routed after the move is kept");
  } finally {
    for (const s of await v216Sites(CO)) await v216SoftDel(s.id);
    await removeCustomer(CO);
  }
  // #218 final — refuse() re-checks before it deletes: a racing finalize that
  // records the same blob mid-flight means the blob is never deleted.
  const DCO = fixtureId(218, "fwa-race");
  const k = d218NewKey();
  const path = d218Path(DCO, k, "race.pdf").replace(/\.pdf$/, "-Zz12Yy.pdf");
  const removed: string[] = [];
  const raced = await d218Finalize(
    { customerId: DCO, uploadKey: k, blobPath: path, fileName: "race.pdf", siteId: "not-this-company" },
    { kind: "team", name: "Jeff" },
    {
      head: async () => ({ bytes: new Uint8Array([0x25, 0x50, 0x44, 0x46, 0x2d]), size: 10 }),
      remove: async (p: string) => { removed.push(p); },
      facts: async () => {
        const rival = await d218Create({
          title: "Race", fileName: "race.pdf", mime: "application/pdf", size: 10, blobPath: path,
          category: "other", visibility: "internal", source: "team", customerId: DCO, siteId: null, projectId: null,
          notes: "", uploadedBy: "Rival",
        });
        registerFixture("documents", rival.id);
        return { customerExists: true, siteIds: ["v1"], project: null };
      },
      categories: async () => d218Resolve(undefined),
    }
  );
  ok(!raced.ok && removed.length === 0, "#218 final: a refusal never deletes a blob a racing finalize has recorded meanwhile");
  const k2 = d218NewKey();
  const path2 = d218Path(DCO, k2, "lone.pdf").replace(/\.pdf$/, "-Qq34Ww.pdf");
  const lone = await d218Finalize(
    { customerId: DCO, uploadKey: k2, blobPath: path2, fileName: "lone.pdf", siteId: "not-this-company" },
    { kind: "team", name: "Jeff" },
    {
      head: async () => ({ bytes: new Uint8Array([0x25, 0x50, 0x44, 0x46, 0x2d]), size: 10 }),
      remove: async (p: string) => { removed.push(p); },
      facts: async () => ({ customerExists: true, siteIds: ["v1"], project: null }),
      categories: async () => d218Resolve(undefined),
    }
  );
  ok(!lone.ok && removed.includes(path2), "#218 final: an unrecorded refused upload is still deleted");
}

/* --- #216 final — stale travel survives a venue move (review fix). Both
   handlers that change a card's address must also clear its travel so any
   travel showing at save time was routed/typed AFTER the last address
   change; the server-side applyVenueMoveRule rule (checked above) still
   drops it too, but the client must never resend a now-stale number. --- */
{
  const em216 = fwaRd("src/app/(app)/companies/edit-modal.tsx");
  const typeSpotBody = em216.slice(em216.indexOf("const typeSpot ="), em216.indexOf("const makePrimaryLoc ="));
  const pickAddressBody = em216.slice(em216.indexOf("const pickAddress ="), em216.indexOf("const runRoute ="));
  ok(typeSpotBody.includes('travelMiles: "", travelMin: ""'),
    "#216 final: typeSpot (hand-typed street/city/state edits) clears travelMiles/travelMin so stale travel never survives a moved card");
  ok(pickAddressBody.includes('travelMiles: "", travelMin: ""'),
    "#216 final: pickAddress (a picked address hit) clears travelMiles/travelMin so stale travel never survives a moved card");
}

/* ======================================================================
   final wave B — batch 2 review minors (#212, #214, #216, #219, #222,
   #224–#227, #230). Pure/structural checks here; DB-backed ones in
   finalWaveBAsyncChecks.
   ====================================================================== */
import { RENDER_LAUNCH_TIMEOUT_MS as fwbLaunchMs, RENDER_STEP_TIMEOUT_MS as fwbStepMs } from "@/lib/quote-pdf/render";
import { pdfStoragePath as fwbPdfPath, portalPdfPreparing as fwbPreparing, portalPdfUnavailable as fwbUnavailable, PDF_PENDING_STALE_MS as fwbStaleMs } from "@/lib/quote-pdf/state";
import { accessoryClampNote as fwbClampNote, ACCESSORY_QTY_MAX as fwbAccMax } from "@/lib/design/grid-accessories";
import { sanitizeTypeMap as fwbSanitizeTypeMap } from "@/lib/design/device-types";
import { fabricRateProblem as fwbFabricProblem, FABRIC_AREA_RATE_MAX as fwbFabricMax } from "@/app/(app)/catalog/part-form";
const fwbRd = (p: string) => readFileSync(join(process.cwd(), p), "utf8");
{
  // #222 (3) + (4) + (7): render.ts — the page is re-checked right before
  // print, a capped fonts wait warns, and the worst case is the sum of the
  // waits renderOnce actually performs (not a constant restated).
  const rs = fwbRd("src/lib/quote-pdf/render.ts");
  const body = rs.slice(rs.indexOf("async function renderOnce("));
  const recheck = body.indexOf("landedOnRequested(url, page.url())");
  ok(recheck > body.indexOf("page.evaluate(") && recheck < body.indexOf("page.pdf("), "#222 final-B: render re-checks the landed URL after the fonts wait and before page.pdf()");
  ok(/if \(fontsCapped\) console\.warn\(/.test(body) && /document\.fonts\.ready\.then\(\(\) => false\)/.test(body) && !/throw[^\n]*fonts/i.test(body), "#222 final-B: a capped fonts wait logs console.warn and never fails the render");
  const stepWaits = (body.match(/[{,]\s*timeout\s*[,}]/g) || []).length;
  ok(
    stepWaits >= 2 && /timeout: RENDER_LAUNCH_TIMEOUT_MS/.test(body) && /Math\.min\(timeout, RENDER_FONTS_TIMEOUT_MS\)/.test(body) &&
      RENDER_WORST_CASE_MS222 === fwbLaunchMs + stepWaits * fwbStepMs + RENDER_FONTS_TIMEOUT_MS222 && RENDER_FONTS_TIMEOUT_MS222 < fwbStepMs,
    `#222 final-B: RENDER_WORST_CASE_MS is launch + ${stepWaits} step-timeout waits + the fonts cap — exactly the waits renderOnce performs`
  );

  // #222 (5): "being prepared" needs a non-failed view.
  const sentAt10 = [{ rev: 1, at: 10, reason: "sent" }];
  const failed = { revisions: sentAt10, pdf: { status: "failed" as const, at: 11, savedAt: 9, error: "Chrome crashed" } };
  const livePending = { revisions: sentAt10, pdf: { status: "pending" as const, at: 11, savedAt: 9 } };
  ok(!fwbPreparing(failed, 12) && fwbUnavailable(failed, 12), "#222 final-B: a failed render is never 'being prepared' — it reads unavailable");
  ok(fwbPreparing(livePending, 12) && !fwbPreparing(livePending, 11 + fwbStaleMs + 1) && fwbUnavailable(livePending, 11 + fwbStaleMs + 1), "#222 final-B: a pending render is 'being prepared' only until pdfView calls it failed (stale)");

  // #222 (6): project status comes only from this customer's quotes.
  ok(/const quoteStatusById = new Map\(quotes\.filter\(\(q\) => q\.customerId === cid\)\.map\(/.test(fwbRd("src/app/portal/page.tsx")), "#222 final-B: the portal's quoteStatusById is built from the session customer's quotes only");

  // #222 (2): source guard (the behaviour is exercised in finalWaveBAsyncChecks).
  ok(/prev && prev !== path && prev !== res\.after\?\.blobPath/.test(fwbRd("src/lib/quote-pdf/generate.ts")), "#222 final-B: generate never deletes the old file when it is the stored blobPath");

  // #212: each unit-cost refusal says what is wrong.
  const ciErr = (unitCost: unknown) => { const r = ci212Sanitize({ desc: "x", qty: 1, unitCost }, "ci-0123456789ab"); return r.ok ? "" : r.error; };
  ok(ciErr("abc") === "Enter the unit cost as a number." && /can't be more than \$10,000,000/.test(ciErr(10_000_001)) && ciErr(0) === "A custom item needs a unit cost above $0." && ciErr(-5) === "A custom item needs a unit cost above $0.",
    "#212 final-B: junk, over-ceiling and zero unit costs each get an accurate message");
  const ci = fwbRd("src/app/(app)/design/grid/[id]/custom-items.tsx");
  ok(/finally \{\s*setSaving\(false\);/.test(ci), "#212 final-B: save() clears Saving… in a finally");

  // #230: removed-part chip, clamp note, picker closes.
  const lines = a230Lines([{ id: "ba-000000000001", partId: "GONE-1", qty: 2, scope: "general" }, { id: "ba-000000000002", partId: "P-1", qty: 1, scope: "general" }], [{ id: "P-1", desc: "Clamp", unit: "ea", list: 10 }]);
  ok(lines[0].removed === true && lines[0].ext === 0 && !("removed" in lines[1]), "#230 final-B: a part that left the library marks its accessory line removed (prices $0); a live one doesn't");
  const base230 = [{ id: "ba-000000000003", partId: "P-1", qty: fwbAccMax - 1, scope: "general" as const }];
  const bump = a230Save(base230, { partId: "P-1", qty: 5, scope: "general" }, () => "ba-000000000004");
  const plain = a230Save(base230, { partId: "P-1", qty: 1, scope: "general" }, () => "ba-000000000004");
  ok(bump.ok && bump.clamped === true && bump.item.qty === fwbAccMax && plain.ok && !("clamped" in plain), "#230 final-B: an over-cap bump is clamped and says so; an exact fit doesn't");
  ok(fwbClampNote(fwbAccMax) === "That accessory line is capped at 100,000 — it now holds 100,000.", "#230 final-B: the clamp note names the cap");
  const acc = fwbRd("src/app/(app)/design/grid/[id]/accessories.tsx");
  const ed = fwbRd("src/app/(app)/design/grid/[id]/editor.tsx") + fwbRd("src/app/(app)/design/grid/[id]/workspace/bom-panel.tsx");
  const gridActs = fwbRd("src/app/(app)/design/grid/[id]/actions.ts");
  ok(/line\.removed \?/.test(acc) && acc.includes("Removed part") && /onDone\(true, r\.note\)/.test(acc), "#230 final-B: the row shows a Removed part chip; the picker hands the clamp note back");
  ok(/onDone=\{\(added, note\) => \{\s*setAddingTo\(null\);[\s\S]{0,120}if \(note\) setErr\(note\);/.test(ed), "#230 final-B: the picker closes after adding and the clamp note is shown");
  ok(/r\.clamped \? \{ note: accessoryClampNote\(r\.item\.qty\) \}/.test(gridActs), "#230 final-B: saveAccessoryAction returns the clamp note");

  // #226: a stored Fabric/Labor entry is dropped on read; bulk default + cap note stay.
  ok(JSON.stringify(fwbSanitizeTypeMap({ fabric: { typeKey: "speakers", by: "admin", at: 1 }, " Labor ": { typeKey: null, by: "admin", at: 1 }, hoist: { typeKey: "hoists-motors", by: "auto", at: 1 } })) === JSON.stringify({ hoist: { typeKey: "hoists-motors", by: "auto", at: 1 } }),
    "#226 final-B: sanitizeTypeMap drops Fabric/Labor keys like every writer does");
  const dtc = fwbRd("src/app/(app)/catalog/device-types/device-types-client.tsx");
  ok(/useState\(""\);\s*\n/.test(dtc.slice(dtc.indexOf("const [bulkChoice, setBulkChoice]"))) && /disabled=\{!picked\.length \|\| !bulkChoice \|\| pending\}/.test(dtc) && /Showing \{ROW_CAP\} of/.test(dtc), "#226 final-B: bulk assign has no default type, and the 200-row cap says so");

  // #227: the fabric rate is refused server-side off Fabric and above the ceiling.
  ok(fwbFabricProblem("Fabric", undefined) === null && fwbFabricProblem("Lighting", undefined) === null && fwbFabricProblem("Fabric", 4.85) === null && fwbFabricProblem("Fabric", fwbFabricMax) === null,
    "#227 final-B: a cleared rate, or a Fabric rate up to $500/sq ft, is fine");
  ok(/Only a fabric part/.test(fwbFabricProblem("Lighting", 4) || "") && /over \$500\/sq ft/.test(fwbFabricProblem("Fabric", 500.01) || ""), "#227 final-B: a non-Fabric rate and one over $500/sq ft are refused with a clear message");
  const cat = fwbRd("src/app/(app)/catalog/actions.ts");
  const up = cat.slice(cat.indexOf("export async function upsertPart("), cat.indexOf("export async function importCatalog("));
  ok(up.indexOf("fabricRateProblem(category, optional.curtainAreaRate, unit)") > -1 && up.indexOf("fabricRateProblem(") < up.indexOf("await mergeUpsert(") && /partError=\$\{encodeURIComponent\(rateProblem\)\}/.test(up), "#227 final-B: upsertPart refuses a bad rate before it writes, back to the modal with the message");

  // #219: Done banner when every owner stopped; per-owner lines say reload to retry.
  const cal = fwbRd("src/app/(app)/import/daylite/calendar/calendar-client.tsx");
  ok(/const allStopped = picked\.length > 0 && picked\.every\(\(o\) => stoppedOwners\.includes\(o\.owner\)\)/.test(cal) && /phase === "paused" && allStopped/.test(cal) && /\{finished && \(\s*<div role="status"/.test(cal), "#219 final-B: the run shows a Done banner when every selected owner has stopped");
  ok(/\{e\.lastError\} — reload to retry/.test(cal), "#219 final-B: each per-owner error line ends '— reload to retry'");

  // #224: already on main — one parsePageSize, labelled filter input.
  ok(/aria-label=\{searchPlaceholder\}/.test(fwbRd("src/components/short-list.tsx")), "#224 final-B: the ShortList filter input has an aria-label");

  // #225: whitespace-only terms print no heading.
  const letter = fwbRd("src/app/(app)/design/engagements/letter/page.tsx");
  ok(/const termsText = \(pay\.terms \|\| ""\)\.trim\(\);/.test(letter) && /\{termsText && \(/.test(letter) && !/\{pay\.terms && \(/.test(letter), "#225 final-B: the Terms heading prints only for non-blank terms");

  // #216: Saved note survives a save (card keyed by type keys only); raw unlisted key.
  const sc = fwbRd("src/app/(app)/settings/groups/field.tsx");
  ok(/<VenueTypesCard\s+key=\{venueTypes\.map\(\(t\) => t\.key\)\.join\("\|"\)\}/.test(sc), "#216 final-B: the Venue types card is keyed by type keys only, so a rename save keeps it mounted");
  const vc = fwbRd("src/app/(app)/settings/venue-types-card.tsx");
  ok(/if \(serverSig !== seenSig\)/.test(vc) && /justSaved && !dirty/.test(vc), "#216 final-B: the card adopts the refreshed list without remounting, so ✓ Saved shows");
  ok(v216Label([], "oldkind") === "oldkind" && v216Label([], "  ") === "Venue", "#216 final-B: an unlisted stored key shows its raw key; no key reads Venue");

  // #214: already on main — the Link search is debounced with a stale-response guard.
  const lp = fwbRd("src/app/(app)/inbox/link-panel.tsx");
  ok(/const my = \+\+seq\.current;/.test(lp) && /if \(my !== seq\.current\) return;/.test(lp) && /\}, 2[0-9]0\);/.test(lp), "#214 final-B: searchLinkTargetsAction is debounced and stale answers are dropped");
}

async function finalWaveBAsyncChecks(): Promise<void> {
  await withPdfEnv222(finalWaveBPdfChecks);
}
async function finalWaveBPdfChecks(): Promise<void> {
  delete process.env.BLOB_READ_WRITE_TOKEN;
  delete process.env.VERCEL;
  process.env.QUOTE_PDF_DIR = mkdtempSync(join(tmpdir(), "quote-pdfs-fwb-"));
  const store = pdfStorage();
  if ("unavailable" in store || store.backend !== "fs") {
    ok(false, "#222 final-B: local PDF store available");
    return;
  }
  const origin = "http://print.test";
  const secret = "spec-secret-fwb";

  // #222 (1): the settle and an unrelated update start in the SAME tick,
  // through the updatePdf seam, 50 times. Confirmed to bite: with the
  // compare-and-set removed (patchQuote/updateQuotePdf writing a doc read
  // before the row lock) all 50 runs lose the name or the pdf state.
  const id = fixtureId222("222", "fwb-race");
  registerFixture222("quotes", id);
  await q222Create({ id, name: "#222 fwb race", customer: "Spec fixture", owner: "spec" });
  let lost = 0;
  for (let i = 0; i < 50; i++) {
    const at = 1_000 + i;
    await q222UpdatePdf(id, (cur) => pendingPdf(cur, at, at));
    const settled = await generateQuotePdf({
      quoteId: id, savedAt: at, origin, secret,
      render: async () => Buffer.from(`%PDF-1.4 fwb ${i}`),
      updatePdf: (qid, mutate) => Promise.all([q222UpdatePdf(qid, mutate), q222Update(qid, { name: `fwb race ${i}` })]).then(([r]) => r),
    });
    const q = await q222Get(id);
    if (!settled || q?.pdf?.status !== "ready" || q.pdf.savedAt !== at || q.name !== `fwb race ${i}`) lost++;
  }
  ok(lost === 0, `#222 final-B: a settle and an update landing in the same tick never lose either write (50 runs, ${lost} lost)`);

  // #222 (2): the old file is never deleted when it is the stored blobPath.
  const kid = fixtureId222("222", "fwb-keep");
  registerFixture222("quotes", kid);
  await q222Create({ id: kid, name: "#222 fwb keep", customer: "Spec fixture", owner: "spec" });
  const kept = await store.put(fwbPdfPath(kid, "kept"), Buffer.from("%PDF-1.4 kept"));
  await q222UpdatePdf(kid, (cur) => pendingPdf(cur, 10, 10));
  await generateQuotePdf({
    quoteId: kid, savedAt: 10, origin, secret,
    render: async () => Buffer.from("%PDF-1.4 new"),
    // The store reports the committed state as still recording `kept`.
    updatePdf: async (qid, mutate) => {
      const r = await q222UpdatePdf(qid, mutate);
      return r && r.after ? { ...r, before: { ...r.after, blobPath: kept }, after: { ...r.after, blobPath: kept } } : r;
    },
  });
  ok((await store.read(kept))?.toString() === "%PDF-1.4 kept", "#222 final-B: a settle whose stored blobPath is the old path never deletes that file");
}

/* ======================================================================
   #233 late (Jeff 2026-09-27) — the Cable Package quantity is the fixture
   count × a per-fixture factor × the tier's multiplier, like labor:
   qty = ⌈fixtures × perFixture × tier ×⌉. Estimating Rules ids
   cable.lighting.perFixture (1, cap 10) and cable.lighting.good|better|best.
   ====================================================================== */
import * as cp233l from "@/lib/design/cable-package";
import { LIGHTING_FIXTURE_KEYS as cp233lFixtureKeys, isLightingFixtureKey as cp233lIsFixture } from "@/lib/design/equipment-vocab";
import { compute as cp233lCompute, defaultAState as cp233lDefault, tierDefsDefault as cp233lTierDefs, type AState as Cp233lAState } from "@/app/(app)/design/quick/engine";
import { tierSystems as cp233lTierSystems } from "@/lib/design/equipment-pricing";
import { autoEstimateCards as cp233lCards } from "@/lib/design/auto-estimate";
import { manualScopeInputs as cp233lInputs } from "@/lib/design/grid-intake";
import { GROUPS as cp233lGroups } from "@/lib/stores/pricing";
{
  const WL = wl231;
  // The fixture set — named next to the vocabulary.
  ok(cp233lFixtureKeys.join() === "lighting:par,lighting:front,lighting:cyc,lighting:side,lighting:automated",
    "#233 late: the fixture set is Par, Front, Cyc, Side light and Automated");
  ok(!cp233lIsFixture("lighting:cablePackage") && !cp233lIsFixture("lighting:wirePull") && !cp233lIsFixture("controls:console") && !cp233lIsFixture("controls:inputStation") && cp233lIsFixture("lighting:automated"),
    "#233 late: the Cable Package itself, Wire pull, consoles and controls are not fixtures");
  const items = [
    { key: "lighting:par", qty: 10 }, { key: "lighting:front", qty: 13 }, { key: "lighting:automated", qty: 5 },
    { key: "lighting:cablePackage", qty: 99 }, { key: "lighting:wirePull", qty: 400 }, { key: "controls:console", qty: 1 },
  ];
  ok(cp233l.lightingFixtureCount(items) === 28, `#233 late: the fixture count sums only fixture lines (got ${cp233l.lightingFixtureCount(items)})`);

  // Rules: defaults, sanitizer bounds.
  const d = WL.defaultWireLaborRules();
  ok(d.cable.perFixture === 1 && d.cable.mult.good === 1 && d.cable.mult.better === 1.15 && d.cable.mult.best === 1.3,
    "#233 late: defaults — 1 per fixture, ×1.0 / ×1.15 / ×1.3");
  ok(WL.cableRateId("perFixture") === "cable.lighting.perFixture" && WL.cableRateId("best") === "cable.lighting.best", "#233 late: the rule ids are cable.lighting.perFixture / .good / .better / .best");
  const stored: Record<string, unknown> = { "cable.lighting.perFixture": 1.5, "cable.lighting.best": 99 };
  const r = WL.wireLaborRulesFrom((id) => stored[id]);
  ok(r.cable.perFixture === 1.5 && r.cable.mult.best === WL.MULT_MAX && r.cable.mult.good === 1, "#233 late: a stored per-fixture (decimals allowed) is read; a multiplier caps at MULT_MAX");
  const pf = (v: unknown) => WL.wireLaborRulesFrom((id) => (id === "cable.lighting.perFixture" ? v : undefined)).cable.perFixture;
  ok(pf(-1) === 1 && pf("2") === 1 && pf(Number.NaN) === 1 && pf(null) === 1 && pf(50) === WL.CABLE_PER_FIXTURE_MAX && WL.CABLE_PER_FIXTURE_MAX === 10 && pf(0) === 0,
    "#233 late: junk per-fixture → 1; above 10 caps at 10; a stored 0 stays 0");

  // The quantity: tier multiplier, round up, none → ×1.0, 0 fixtures → nothing.
  ok(cp233l.cablePackageQty(39, d.cable, "good") === 39 && cp233l.cablePackageQty(39, d.cable, "better") === 45 && cp233l.cablePackageQty(39, d.cable, "best") === 51,
    "#233 late: 39 fixtures → 39 / ⌈44.85⌉ = 45 / ⌈50.7⌉ = 51 at Good / Better / Best");
  ok(cp233l.cablePackageQty(39, d.cable, null) === 39, "#233 late: no tier → ×1.0");
  ok(cp233l.cablePackageQty(10, { perFixture: 1.1, mult: d.cable.mult }, "good") === 11, "#233 late: float noise never buys an extra package (10 × 1.1 = 11, not 12)");
  ok(cp233l.cablePackageQty(39, { perFixture: 1.5, mult: d.cable.mult }, "best") === 77, "#233 late: 39 × 1.5 × 1.3 = 76.05 rounds UP to 77");
  ok(cp233l.cablePackageQty(0, d.cable, "best") === 0 && cp233l.cablePackageQty(12, { perFixture: 0, mult: d.cable.mult }, "best") === 0, "#233 late: 0 fixtures (or 0 per fixture) → 0");
  ok(cp233l.cablePackageNote(24, d.cable, "better") === "24 fixtures × 1 × 1.15" && cp233l.cablePackageNote(1, { perFixture: 1.5, mult: d.cable.mult }, null) === "1 fixture × 1.5 × 1",
    `#233 late: the line's note shows the math (${cp233l.cablePackageNote(24, d.cable, "better")})`);

  // compute(): 40 × 24 medium, every fixture on → 10 + 13 + 6 + 5 + 5 = 39 fixtures.
  const base = cp233lDefault(0);
  const s: Cp233lAState = {
    ...base, venue: "school", size: "medium", width: 40, depth: 24, grid: 24, wing: 12, ph: 20, tier: "better",
    sys: { ...base.sys, rigging: false, curtains: false, lighting: true, controls: false, audio: false, video: false, acoustical: false, pit: false },
    fixtures: { par: true, front: true, cyc: true, side: true, automated: true },
  };
  const C = cp233lCompute(s);
  const light = C.systems.find((x) => x.key === "lighting")!;
  const cable = light.items.find((i) => i.key === "lighting:cablePackage");
  ok(cable?.qty === 45 && cable.note === "39 fixtures × 1 × 1.15" && cable.desc === "Cable Package",
    `#233 late: compute() emits ⌈39 × 1 × 1.15⌉ = 45 at the design's Better tier, noted (${cable?.qty} · ${cable?.note})`);
  ok(light.items[light.items.length - 1].key === "lighting:cablePackage", "#233 late: the Cable Package follows the fixture lines");
  const deeper = cp233lCompute({ ...s, depth: 25 });
  ok(deeper.systems.find((x) => x.key === "lighting")!.items.find((i) => i.key === "lighting:cablePackage")?.qty === 45, "#233 late: stage depth no longer moves the quantity (same fixtures → same Cable Package)");
  const none = cp233lCompute({ ...s, fixtures: { par: false, front: false, cyc: false, side: false, automated: false } });
  ok(!none.systems.find((x) => x.key === "lighting")!.items.some((i) => i.key === "lighting:cablePackage"), "#233 late: no fixtures selected → no Cable Package line");

  // The pipeline step applies the LIVE rules at each tier.
  const rules = WL.wireLaborRulesFrom((id) => ({ "cable.lighting.perFixture": 2 } as Record<string, unknown>)[id]);
  const stepped = cp233l.withCablePackage(C.systems, "best", rules);
  const sc = stepped.find((x) => x.key === "lighting")!.items.filter((i) => i.key === "lighting:cablePackage");
  ok(sc.length === 1 && sc[0].qty === 102 && sc[0].note === "39 fixtures × 2 × 1.3", `#233 late: the step replaces the line — 39 × 2 × 1.3 = 101.4 → 102 (${sc.map((i) => i.qty).join()})`);
  ok(cp233l.withCablePackage(C.systems, "better", WL.defaultWireLaborRules()).every((x, i) => x === C.systems[i]), "#233 late: the step at the default rules and the design's tier changes nothing");
  const off = cp233l.withCablePackage(C.systems.map((x) => (x.key === "lighting" ? { ...x, on: false } : x)), "best", rules);
  ok(!off.find((x) => x.key === "lighting")!.items.some((i) => i.key === "lighting:cablePackage"), "#233 late: Lighting out of scope → no Cable Package");

  // Quick Design (tierSystems) and Grid Auto (autoEstimateCards) both run it.
  const allNone = { margin: 0.3, byTier: { good: {}, better: {}, best: {} } } as never;
  const qd = (t: "good" | "better" | "best") => cp233lTierSystems(C, s, t, cp233lTierDefs(), allNone, {}, rules).find((x) => x.key === "lighting")!.items.find((i) => i.key === "lighting:cablePackage")!;
  ok(qd("good").qty === 78 && qd("better").qty === 90 && qd("best").qty === 102, `#233 late: Quick Design prices each tier's Cable Package at that tier (78 / 90 / 102 at 2 per fixture)`);
  const inputs = { ...cp233lInputs(s), sys: s.sys };
  const cards = cp233lCards(inputs, { tierByScope: { lighting: "best" as const }, overrides: {} }, allNone, {}, rules);
  const cl = cards.find((c) => c.scope === "lighting")!.lines.find((l) => l.rowKey === "lighting:cablePackage")!;
  ok(cl.qty === 102 && cl.eqQty === 102 && cl.note === "39 fixtures × 2 × 1.3" && cl.place === "lot", `#233 late: the Grid Auto Lighting card carries the Cable Package at the Lighting tier (${cl.qty})`);

  /* #233 late review (Jeff): the fixture count must follow the designer's
     TYPED quantity — a Quick Design qty override or a Grid Auto qty edit —
     not only the raw equation output. Base case: 39 fixtures (10 Par + 13
     Front + 6 Cyc + 5 Side + 5 Automated). */
  const sParOv: Cp233lAState = { ...s, qtyOverrides: { good: { lighting: { Par: 60 } } } };
  const qdOv = cp233lTierSystems(C, sParOv, "good", cp233lTierDefs(), allNone, {}, rules)
    .find((x) => x.key === "lighting")!
    .items.find((i) => i.key === "lighting:cablePackage")!;
  ok(qdOv.qty === 178,
    `#233 late review: a typed Par override (10 → 60) changes the Cable Package's fixture count in Quick Design — 89 fixtures × 2 × 1 = 178 (got ${qdOv.qty})`);
  ok(qdOv.note === "89 fixtures × 2 × 1", `#233 late review: the note shows the effective count, not the equation's (${qdOv.note})`);

  const cardsParOv = cp233lCards(inputs, { tierByScope: { lighting: "best" as const }, overrides: { "lighting:par": { qty: 60 } } }, allNone, {}, rules);
  const clParOv = cardsParOv.find((c) => c.scope === "lighting")!.lines.find((l) => l.rowKey === "lighting:cablePackage")!;
  ok(clParOv.qty === 232,
    `#233 late review: a typed Par qty edit (10 → 60) on the Grid Auto card changes the Cable Package's fixture count — 89 × 2 × 1.3 = 231.4 → 232 (got ${clParOv.qty})`);

  // A typed Cable Package qty itself still wins (applyOverrides / the Auto
  // card's own qty edit run after this step) — and the client drops the
  // now-stale fixture-math note when that happens.
  ok(r233Hints["lighting:cablePackage"] === undefined,
    "#233 late review: the row has no legacy 'was' hint — the old Output-station price no longer applies to the per-cable unit");
  const qdcSrc = readFileSync(join(process.cwd(), "src/app/(app)/design/quick/quick-design-client.tsx"), "utf8");
  ok(qdcSrc.includes('import { CABLE_PACKAGE_KEY } from "@/lib/design/cable-package"') &&
      qdcSrc.includes('it.key === CABLE_PACKAGE_KEY && hasOv'),
    "#233 late review: Quick Design drops the fixture-math note once the Cable Package's own qty is typed over");

  // Estimating Rules wiring.
  const g = cp233lGroups.find((x) => x.key === "cable");
  const ids = (g?.items || []).map((it) => it.id);
  ok(!!g && g.live && ["cable.lighting.perFixture", "cable.lighting.good", "cable.lighting.better", "cable.lighting.best"].every((id) => ids.includes(id)),
    "#233 late: Estimating Rules has a live Cable package group with per fixture and Good / Better / Best ×");
  const pfRow = g?.items.find((it) => it.id === "cable.lighting.perFixture");
  ok(!!pfRow && pfRow.kind === "rate" && pfRow.def === 1 && pfRow.max === 10 && pfRow.step < 1 && pfRow.store === "general", "#233 late: per fixture defaults to 1, caps at 10 and takes decimals");
  const gk = cp233lGroups.map((x) => x.key);
  ok(gk.indexOf("cable") === gk.indexOf("wire") + 1 && gk.indexOf("labor") === gk.indexOf("cable") + 1, "#233 late: it sits between Wire pull and System labor");
  const eng = readFileSync(join(process.cwd(), "src/app/(app)/design/quick/engine.ts"), "utf8");
  ok(!/2 \* fl\(D \/ 7\)/.test(eng), "#233 late: the stage-depth formula is gone");
  const cpSrc = readFileSync(join(process.cwd(), "src/lib/design/cable-package.ts"), "utf8");
  ok(!/from "@\/lib\/stores|from "@\/db/.test(cpSrc), "#233 late: cable-package.ts is client-safe (no store or db import)");
}

/* #233 late (b) — the Cable Package rules through Estimating Rules into the loader, against the scratch DB. Leaves the defaults behind. */
async function cable233LateAsyncChecks(): Promise<void> {
  const P = await import("@/lib/stores/pricing");
  await P.setValue("cable.lighting.perFixture", 1.25);
  await P.setValue("cable.lighting.better", 1.5);
  const set = await P.loadWireLaborRules();
  ok(set.cable.perFixture === 1.25 && set.cable.mult.better === 1.5, "#233 late: Estimating Rules edits reach the loader");
  await P.setValue("cable.lighting.perFixture", 40);
  ok((await P.loadWireLaborRules()).cable.perFixture === 10, "#233 late: Estimating Rules clamps per fixture at 10");
  await P.resetValue("cable.lighting.perFixture");
  await P.resetValue("cable.lighting.better");
  ok(JSON.stringify(await P.loadWireLaborRules()) === JSON.stringify(wl231.defaultWireLaborRules()), "#233 late: resetting restores the defaults");
}

/* ======================================================================
   #227 late (Jeff 2026-09-27) — "a 10% adder to the fabric pricing for
   sewing labor … built into the estimators, not on the fabric cost". The
   catalog rate is fabric cost per sq ft again; every curtain estimate adds
   the sewing rule (curtains.sewingPct, default 10, cap 100) through the one
   shared model: cost = sewn area × fabric rate × (1 + sewing % ÷ 100).
   ====================================================================== */
import * as sew227 from "@/lib/design/curtain-pricing";
import { curtainCost as sew227PortalCost, fabricSellPerSqft as sew227Sell } from "@/lib/curtain-pricing";
import { curtainPriceEach as sew227PriceEach, fabricRateLabel as sew227Label, FABRIC_RATE_UNIT as sew227Unit, sewnSellLabel as sew227SellLabel } from "@/lib/curtain-geom";
import { drapeUnitCost as sew227Drape, applyEquipment as sew227Apply } from "@/lib/design/equipment-pricing";
import { computeCurtain as sew227Compute } from "@/app/(app)/estimator/pricing";
import { priceGridCurtains as sew227Grid } from "@/lib/design/grid-curtains";
import { priceCell as sew227PriceCell, buildEquipmentPriceTable as sew227Table, type PricingPart as Sew227Part } from "@/lib/design/equipment-map";
import { EQUIPMENT_ROW_BY_KEY as sew227Rows } from "@/lib/design/equipment-vocab";
import { GROUPS as sew227Groups } from "@/lib/stores/pricing";
{
  const S = sew227;
  ok(S.SEWING_PCT_ID === "curtains.sewingPct" && S.DEFAULT_SEWING_PCT === 10 && S.SEWING_PCT_MAX === 100, "#227 late: the rule is curtains.sewingPct, default 10 %, cap 100 %");
  ok(S.sewingPctFrom(undefined) === 10 && S.sewingPctFrom(null) === 10 && S.sewingPctFrom("20") === 10 && S.sewingPctFrom(-5) === 10 && S.sewingPctFrom(Number.NaN) === 10,
    "#227 late: a missing or junk sewing % is the 10 % default");
  ok(S.sewingPctFrom(250) === 100 && S.sewingPctFrom(0) === 0 && S.sewingPctFrom(12.5) === 12.5, "#227 late: above 100 caps; a stored 0 stays 0; decimals kept");

  // The report's example figures — same inputs as before the adder.
  const at = (w: number, h: number, full: number, rate: number, sewingPct: number) =>
    S.curtainCost({ finishedWidthFt: w, finishedHeightFt: h, fullnessPct: full, qty: 1 }, { fabricRate: rate, sewingPct });
  ok(at(50, 3, 50, 3.64, 10).costEach === 900.9, `#227 late: a 50×3 border at 50% = 225 × 3.64 × 1.10 = 900.90 (was 819) (got ${at(50, 3, 50, 3.64, 10).costEach})`);
  ok(at(20, 19, 50, 3.64, 10).costEach === 2282.28, `#227 late: a 20×19 main at 50% = 570 × 3.64 × 1.10 = 2282.28 (was 2074.80) (got ${at(20, 19, 50, 3.64, 10).costEach})`);
  ok(at(40, 20, 0, 0.9, 10).costEach === 792, `#227 late: a flat 40×20 muslin cyc = 800 × 0.90 × 1.10 = 792 (was 720) (got ${at(40, 20, 0, 0.9, 10).costEach})`);
  ok(at(50, 3, 50, 3.64, 0).costEach === 819 && at(50, 3, 50, 3.64, 20).costEach === 982.8, "#227 late: the rule drives the adder — 0 % is fabric only (819), 20 % → 982.80");
  ok(S.sewnAreaRate(3.64, 10) === 3.64 * 1.1 && S.sewnAreaRate(0, 10) === 0 && S.sewnAreaRate(-1, 10) === 0, "#227 late: the sewn area rate is fabric rate × (1 + sewing %)");
  const vo = S.curtainCost({ finishedWidthFt: 23, finishedHeightFt: 15, fullnessPct: 50, qty: 2, vendorCostOverride: 2080 }, { fabricRate: 3.64, sewingPct: 10 });
  ok(vo.costEach === 2080 && vo.costTotal === 4160 && vo.overridden, "#227 late: a typed vendor cost is the full cost — no sewing on top");
  ok(S.curtainPrice(at(20, 19, 50, 3.64, 10).costEach, 0.3) === Math.round((2282.28 / 0.7) * 100) / 100, "#227 late: sell = cost ÷ (1 − margin), as before");

  // Parity: every mirror carries the adder, at the default and a non-default rule.
  for (const sewingPct of [10, 25]) {
    for (const c of [{ w: 20, h: 19, full: 50, rate: 3.64 }, { w: 40, h: 20, full: 0, rate: 0.9 }, { w: 9.5, h: 10 + 11 / 12, full: 100, rate: 2.84 }]) {
      const tag = `${c.w}×${c.h.toFixed(2)} @${c.full}% $${c.rate} +${sewingPct}%`;
      const shared = at(c.w, c.h, c.full, c.rate, sewingPct).costEach;
      const spec = { name: "d", hang: "", fabric: "SEW227", qty: "1", width: String(c.w), height: String(c.h), fullness: String(c.full), bottom: "" };
      const portal = sew227PortalCost(spec, { fabricRate: c.rate, sewingPct }, 0.3);
      const est = sew227Compute({ ...spec, vendorCostOverride: "" }, [{ sku: "SEW227", name: "x", costPerSqft: 0, curtainAreaRate: c.rate }], { sewingPct }, 0.3);
      const grid = sew227Grid(
        [{ id: "pl1", curtain: { type: "Draw", name: "d", widthFt: c.w, heightFt: c.h, fullnessPct: c.full, fabricSku: "SEW227" } }],
        [{ id: "SEW227", sku: "SEW227", desc: "x", category: "Fabric", curtainAreaRate: c.rate }],
        { sewingPct },
        0.3
      ).get("pl1")!;
      const drape = sew227Drape({ w: c.w, h: c.h, fullness: c.full, qty: 1 }, c.rate, sewingPct);
      const client = sew227PriceEach(spec, sew227Sell({ fabricRate: c.rate, sewingPct }, 0.3));
      ok(shared > at(c.w, c.h, c.full, c.rate, 0).costEach, `#227 late ${tag}: the adder raises the cost`);
      ok(portal.costEach === shared && est.costEach === shared && grid.costEach === shared && drape === Math.round(shared),
        `#227 late parity ${tag}: portal, estimator, Grid and the Equipment-map drape all = shared ${shared} (got ${portal.costEach} / ${est.costEach} / ${grid.costEach} / ${drape})`);
      ok(grid.priceEach === portal.priceEach && Math.abs(client - portal.priceEach) < 0.011 && Math.abs(est.priceEach - portal.priceEach) <= 0.011,
        `#227 late parity ${tag}: Grid, client preview and estimator sell = portal sell (${portal.priceEach})`);
    }
  }
  const estOv = sew227Compute({ name: "d", hang: "", fabric: "SEW227", qty: "1", width: "20", height: "19", fullness: "50", bottom: "", vendorCostOverride: "2080" }, [{ sku: "SEW227", name: "x", costPerSqft: 0, curtainAreaRate: 3.64 }], { sewingPct: 10 }, 0.3);
  ok(estOv.costEach === 2080, "#227 late: the estimator's Rose Brand cost override carries no sewing adder");

  // Quick Design / Grid Equipment map: a fabric row carries the rule the server priced it with.
  const drawDef = sew227Rows.get("curtains:draw")!;
  const fab: Sew227Part = { sku: "SEW227-VEL", desc: "Velour", unit: "sq ft", cost: 0, list: 0, category: "Fabric", curtainAreaRate: 3.64 };
  const ctx = { parts: new Map<string, Sew227Part>([[fab.sku, fab]]), fixtures: new Map(), margin: 0.3, sewingPct: 25 };
  const cell = sew227PriceCell({ kind: "part", sku: fab.sku }, drawDef, ctx);
  ok(cell.status === "part" && cell.areaRate === 3.64 && cell.sewingPct === 25, "#227 late: a mapped fabric keeps its fabric-only area rate and carries the sewing %");
  const noRule = sew227PriceCell({ kind: "part", sku: fab.sku }, drawDef, { ...ctx, sewingPct: undefined });
  ok(noRule.status === "part" && noRule.sewingPct === 10, "#227 late: a price context without the rule prices at the 10 % default, never 0");
  const table = sew227Table({ "curtains:draw": { tiers: { good: { kind: "part", sku: fab.sku } }, sameAll: true, updatedBy: "t", updatedAt: 1 } }, ctx);
  const geom = { w: 20, h: 19, fullness: 50, qty: 2 };
  const sys = [{ key: "curtains" as const, name: "Curtains", on: true, m: 0.3, dot: "#000", rev: 0, cost: 0, items: [{ key: "curtains:draw", desc: "Draw", unit: "ea", qty: 1, cost: 0, price: 0, drape: geom }] }];
  const priced = sew227Apply(sys, "better", table)[0].items[0];
  const want = Math.round(S.curtainCost({ finishedWidthFt: 20, finishedHeightFt: 19, fullnessPct: 50, qty: 2 }, { fabricRate: 3.64, sewingPct: 25 }).costTotal);
  ok(priced.cost === want && want === Math.round(570 * 3.64 * 1.25 * 2), `#227 late: Quick Design / Grid Auto drape cost carries the adder (${priced.cost})`);

  // Estimating Rules.
  const row = sew227Groups.flatMap((g) => g.items.map((it) => ({ g, it }))).find((x) => x.it.id === "curtains.sewingPct");
  ok(!!row && row.g.live && row.it.kind === "rate" && row.it.def === 10 && row.it.max === 100 && row.it.store === "general" && row.it.unit === "%",
    "#227 late: Estimating Rules carries a live Curtain sewing % (default 10, max 100)");

  // Labels: the catalog rate is fabric cost.
  ok(sew227Unit === "sq ft fabric" && sew227Label(3.64) === "$3.64/sq ft fabric" && sew227Label(0) === "No $/sq ft set", `#227 late: a fabric rate reads $X/sq ft fabric (${sew227Label(3.64)})`);
  ok(sew227SellLabel(5.72) === "$5.72/sq ft sewn (incl. sewing)" && sew227SellLabel(0) === "No $/sq ft set", "#227 late: the Grid drop-in's sell rate says sewing is in it");
  const rd = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  const frf = rd("src/app/(app)/catalog/fabric-rate-field.tsx");
  ok(frf.includes("$/sq ft fabric") && frf.includes("Fabric cost only — estimates add sewing labor (Estimating Rules, default 10 %)") && frf.includes("sqftRateFromLinearYard") && frf.includes("sqftRateFromSquareYard"),
    "#227 late: the part editor's field reads $/sq ft fabric with the sewing help, and keeps the $/lin-yd and $/sq yd converter");
  const it227 = rd("src/app/(app)/import/types.ts");
  ok(it227.includes('label: "Fabric $/sq ft (fabric cost only)"') && it227.includes("estimates add sewing labor"), "#227 late: the Import hub column help says fabric cost only");
  ok(rd("src/app/(app)/design/grid/[id]/curtain-drop.tsx").includes("sewnSellLabel(f.pricePerSqft)"), "#227 late: the Grid drop-in labels each fabric's sewn sell rate");
  const labelled = [
    "src/app/(app)/catalog/fabric-rate-field.tsx", "src/app/(app)/catalog/parse.ts", "src/app/(app)/catalog/part-form.ts", "src/app/(app)/import/types.ts",
    "src/app/(app)/import/registry.ts", "src/app/(app)/estimator/pricing.ts", "src/app/(app)/estimator/curtain-modal.tsx", "src/lib/curtain-geom.ts",
    "src/lib/curtain-pricing.ts", "src/lib/design/curtain-pricing.ts", "src/lib/design/equipment-map.ts", "src/lib/design/equipment-pricing.ts",
    "src/lib/stores/catalog.ts", "src/app/(app)/design/grid/[id]/curtain-drop.tsx", "src/app/(app)/design/grid/settings/equipment-map/equipment-map-client.tsx",
  ];
  const stale = labelled.filter((f) => /incl\. making|includes making|making included|must include making|INCLUDING making|making \/ sewing included|add making before/i.test(rd(f)));
  ok(stale.length === 0, `#227 late: no label or help says the fabric rate includes making (${stale.join(", ") || "none"})`);

  // The rule reaches every pricing path as data from the server.
  ok(rd("src/app/(app)/estimator/page.tsx").includes("loadCurtainSewingPct()") && rd("src/app/(app)/estimator/page.tsx").includes("curtainSewingPct={curtainSewingPct}") &&
      rd("src/app/(app)/estimator/estimator-client.tsx").includes("{ sewingPct: curtainSewingPct }") && rd("src/app/(app)/estimator/curtain-modal.tsx").includes("{ sewingPct }"),
    "#227 late: the Estimator reads the rule on the server and hands it to its client curtain math");
  // #245 Tasks 10/12: the portal estimate page and its submit are retired —
  // no portal path there prices fabric any more.
  ok(!rd("src/app/portal/actions.ts").includes("curtainCost(") && !rd("src/app/portal/estimate/page.tsx").includes("fabricSellPerSqft"),
    "#227 late: no legacy portal path (estimate page/actions) prices a curtain");
  // #250: the portal configurator DOES price curtains now — through the ONE
  // shared chain (curtainCost/curtainPrice imported from the canonical
  // module), never a reimplementation.
  ok(rd("src/lib/portal-pricing.ts").includes('import { curtainCost, curtainPrice } from "@/lib/design/curtain-pricing"'),
    "#250: the portal cart prices curtains through the shared Estimator curtain math (curtainCost/curtainPrice), not a re-implementation");
  ok(rd("src/app/(app)/design/grid/[id]/page.tsx").includes("loadCurtainSewingPct()") && rd("src/lib/design/grid-quote.ts").includes("loadCurtainSewingPct()") && rd("src/lib/stores/equipment-map.ts").includes("loadCurtainSewingPct()"),
    "#227 late: the Grid editor, the Grid quote and the Equipment-map price context read the rule");
  // #245 Task 12: the portal estimate builder is deleted; the portal cart (which shows curtain requests) takes its place here.
  const clients = ["src/app/(app)/estimator/estimator-client.tsx", "src/app/(app)/estimator/curtain-modal.tsx", "src/app/(app)/design/grid/[id]/curtain-drop.tsx", "src/app/portal/catalog/quote/cart-client.tsx", "src/app/portal/catalog/curtain-request.tsx"];
  ok(clients.every((f) => !/^import\s+(?!type\b)[^;]*?from "@\/(lib\/stores\/|db)/m.test(rd(f))), "#227 late: no client curtain file imports a VALUE from a store");
}

/* #227 late (b) — the sewing rule through Estimating Rules into its loader and the Equipment-map price context, against the scratch DB. Leaves the default behind. */
async function sewing227LateAsyncChecks(): Promise<void> {
  const P = await import("@/lib/stores/pricing");
  const EMS = await import("@/lib/stores/equipment-map");
  ok((await P.loadCurtainSewingPct()) === 10 && (await EMS.loadEquipPriceCtx()).ctx.sewingPct === 10, "#227 late: a fresh database adds 10 % sewing");
  await P.setValue("curtains.sewingPct", 15);
  ok((await P.loadCurtainSewingPct()) === 15 && (await EMS.loadEquipPriceCtx()).ctx.sewingPct === 15, "#227 late: an Estimating Rules edit reaches the loader and the price context");
  await P.setValue("curtains.sewingPct", 500);
  ok((await P.loadCurtainSewingPct()) === 100, "#227 late: Estimating Rules clamps the sewing % at 100");
  await P.resetValue("curtains.sewingPct");
  ok((await P.loadCurtainSewingPct()) === 10, "#227 late: resetting restores 10 %");
}

/* #216 final-B (2026-09-27) — a deleted venue type never leaks its raw key
   into a DERIVED venue name: admin screens may show the key (venueTypeLabel),
   but a saved name reads "Venue" for a type the list no longer has. */
import { deriveLocationLabels as vn216Derive, venueNameTypeLabel as vn216NameLabel, venueTypesFrom as vn216Types } from "@/lib/venue-types";
{
  // The seed list with its one custom type, Gym Stage ("gymstage"), deleted in Settings.
  const types = vn216Types(null).filter((t) => t.key !== "gymstage");
  ok(vn216Types(null).some((t) => t.key === "gymstage") && !types.some((t) => t.key === "gymstage"), "#216 final-B: the fixture deletes the custom type gymstage from the list");
  const names = vn216Derive([{ label: "", locationName: "Main", venueKind: "gymstage", derive: true }], "Acme", types);
  ok(names[0] === "Main — Venue", `#216 final-B: a venue on a deleted type "gymstage" derives "Main — Venue", not "Main — gymstage" (got ${names[0]})`);
  ok(vn216NameLabel(types, "gymstage") === "Venue" && vn216NameLabel(types, "") === "Venue" && vn216NameLabel(types, types[0].key) === types[0].label,
    "#216 final-B: the name's type segment is the type's label, else Venue");
  const rd216 = (f: string) => readFileSync(join(process.cwd(), f), "utf8");
  ok(rd216("src/lib/identity/venue-save.ts").includes("typeLabel: venueNameTypeLabel(types, venueKind)") && rd216("src/app/(app)/companies/venue-dialog.tsx").includes("typeLabel: venueNameTypeLabel(venueTypes, venueKind)"),
    "#216 final-B: saveVenue and the venue dialog's preview derive the name with venueNameTypeLabel");
}

/* ======================================================================
   #223 — estimate numbers: the migration (sequence, assign_estimate_numbers(),
   date-ordered backfill with lead→quote carry and suffixes, setval) and the
   store wrapper's preview safety. Runs on the harness's fresh datadir, so
   the real drizzle/0030_estimate_numbers.sql is what is under test.
   ====================================================================== */
import { assignEstimateNumbers as e223Assign, resetEstimateNumberProbe as e223ResetProbe } from "@/lib/stores/estimate-numbers";
import { buildQuote as e223BuildQuote, type Quote as E223Quote } from "@/lib/stores/quotes";
import { mkLead as e223MkLead, type LeadRecord as E223Lead } from "@/lib/stores/leads";
import { getDocRows as e223GetRows, softDeleteDoc as e223SoftDelete } from "@/db/doc-store";
import { getDb as e223GetDb, withTransaction as e223Tx } from "@/db";
import { sql as e223Sql } from "drizzle-orm";
import { readFileSync as e223ReadFile, readdirSync as e223ReadDir } from "node:fs";
import { join as e223Join } from "node:path";
import { isDeepStrictEqual as e223DeepEq } from "node:util";
function e223Rows<T>(result: unknown): T[] {
  if (result && typeof result === "object" && "rows" in result) return (result as { rows: T[] }).rows;
  return Array.isArray(result) ? (result as T[]) : [];
}

async function estimate223BackfillAsyncChecks(): Promise<void> {
  const db = await e223GetDb();
  const reg = e223Rows<{ seq: string | null; fn: string | null }>(
    await db.execute(e223Sql`select to_regclass('estimate_number_seq')::text as seq, to_regprocedure('assign_estimate_numbers()')::text as fn`)
  );
  ok(!!reg[0]?.seq && !!reg[0]?.fn, "#223 migration: estimate_number_seq and assign_estimate_numbers() exist on a fresh datadir");

  // Number whatever earlier suites left unnumbered, so the fixtures below
  // are the only unnumbered rows and get consecutive numbers.
  await e223Assign();

  const id = (slug: string) => fixtureId(223, slug);
  const quote = (slug: string, t: number, extra: Partial<E223Quote> = {}): E223Quote => ({
    ...e223BuildQuote(id(slug), { name: "#223 " + slug, owner: "spec" }, extra.quoteType || "system", null, t),
    ...extra,
  });
  const lead = (slug: string, t: number, extra: Partial<E223Lead> = {}): E223Lead => ({
    ...e223MkLead({ id: id(slug), org: "#223 " + slug, createdAt: t }),
    ...extra,
  });

  // No createdAt at all — dated by its earliest history entry (5).
  const hist = quote("hist", 1, { history: [{ at: 5, to: "draft" }], updatedAt: 90 });
  delete (hist as Partial<E223Quote>).createdAt;
  await createFixture("quotes", hist);
  await createFixture("leads", lead("lead1", 10, { convertedQuoteId: id("q1") }));
  await createFixture("quotes", quote("gone", 15));
  await e223SoftDelete("quotes", id("gone"));
  await createFixture("quotes", quote("q1", 20, { source: "lead" }));
  await createFixture("quotes", quote("dl", 30, { source: "daylite" }));
  await createFixture("quotes", quote("q2", 40, { leadId: id("lead1"), quoteType: "flame_test" }));
  await createFixture("quotes", quote("q3", 55, { leadId: id("lead2") }));
  await createFixture("leads", lead("lead2", 60));
  await createFixture("quotes", quote("q4", 65, { quoteType: "consulting", consulting: { leadId: id("lead1") } }));
  await createFixture("quotes", quote("tie-b", 70));
  await createFixture("quotes", quote("tie-a", 70));

  const assigned = await e223Assign();
  ok(assigned === 11, `#223 backfill: numbers all eleven unnumbered fixtures in one pass (got ${assigned})`);

  // Sorted: getDocRows has no ORDER BY, and the re-run's ANALYZE can change
  // the plan (and so the row order) without changing any number.
  const read = async () =>
    [
      ...(await e223GetRows("quotes", ["hist", "gone", "q1", "dl", "q2", "q3", "q4", "tie-a", "tie-b"].map(id))),
      ...(await e223GetRows("leads", ["lead1", "lead2"].map(id))),
    ].sort((x, y) => (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
  const rows = await read();
  const field = (slug: string, k: "estNo" | "estSuffix") =>
    (rows.find((r) => r.id === id(slug))?.doc as Record<string, unknown> | undefined)?.[k];
  const no = (slug: string) => Number(field(slug, "estNo") ?? -1);
  const b = no("dl");
  ok(b >= 1001, "#223 backfill: numbers start at 1001 or later");
  ok(
    no("hist") === b + 1 && no("lead1") === b + 2 && no("gone") === b + 3 && no("q3") === b + 4 && no("tie-a") === b + 5 && no("tie-b") === b + 6,
    "#223 backfill: Daylite history first, then leads and quotes interleave in date order (createdAt, else earliest history/activity; ties by id)"
  );
  ok(rows.find((r) => r.id === id("gone"))?.deleted === true && no("gone") > 0, "#223 backfill: a soft-deleted quote is numbered too, so no number is ever reused");
  ok(no("dl") > 0, "#223 backfill: a Daylite-imported quote is numbered");
  ok(no("q1") === no("lead1") && field("q1", "estSuffix") === undefined, "#223 backfill: the lead's converted quote carries the lead's number, no suffix");
  ok(no("q2") === no("lead1") && field("q2", "estSuffix") === 2, "#223 backfill: a second quote on the lead (leadId) gets -2");
  ok(no("q4") === no("lead1") && field("q4", "estSuffix") === 3, "#223 backfill: a consulting proposal linked by consulting.leadId gets -3");
  ok(no("lead2") === no("q3") && field("q3", "estSuffix") === undefined, "#223 backfill: a lead newer than its quote takes the quote's number");
  const histDoc = rows.find((r) => r.id === id("hist"))?.doc as Record<string, unknown> | undefined;
  const histRest = { ...(histDoc || {}) };
  delete histRest.estNo;
  delete histRest.estSuffix;
  ok(
    e223DeepEq(histRest, JSON.parse(JSON.stringify({ ...hist, id: id("hist") }))),
    "#223 backfill: writes only estNo/estSuffix (jsonb_set) — updatedAt and every other field are untouched, so list order and a concurrent save survive"
  );

  ok((await e223Assign()) === 0, "#223 backfill: a second pass assigns nothing");

  const snapshot = JSON.stringify(rows.map((r) => [r.id, (r.doc as Record<string, unknown>).estNo, (r.doc as Record<string, unknown>).estSuffix]));
  const file = e223ReadDir(e223Join(process.cwd(), "drizzle")).find((f) => /^\d{4}_estimate_numbers\.sql$/.test(f));
  ok(!!file, "#223 migration: drizzle/NNNN_estimate_numbers.sql exists");
  let rerunError: unknown = null;
  if (file) {
    const stmts = e223ReadFile(e223Join(process.cwd(), "drizzle", file), "utf8")
      .split("--> statement-breakpoint")
      .map((s) => s.trim())
      .filter(Boolean);
    try {
      for (const s of stmts) await db.execute(e223Sql.raw(s));
    } catch (e) {
      rerunError = e;
    }
  }
  ok(rerunError === null, `#223 migration: re-running every statement of the file is harmless (${String(rerunError)})`);
  const after = await read();
  ok(
    JSON.stringify(after.map((r) => [r.id, (r.doc as Record<string, unknown>).estNo, (r.doc as Record<string, unknown>).estSuffix])) === snapshot,
    "#223 migration: a re-run changes no number"
  );

  const top = e223Rows<{ top: string | number | bigint | null }>(
    await db.execute(e223Sql`select max(v)::bigint as top from (
      select (doc->>'estNo')::numeric as v from quotes where jsonb_typeof(doc->'estNo') = 'number'
      union all
      select (doc->>'estNo')::numeric from leads where jsonb_typeof(doc->'estNo') = 'number') s`)
  );
  const seq = e223Rows<{ last_value: string | number | bigint; is_called: boolean }>(
    await db.execute(e223Sql`select last_value, is_called from estimate_number_seq`)
  );
  ok(
    seq[0]?.is_called === true && Number(seq[0]?.last_value) === Number(top[0]?.top),
    "#223 setval: the sequence sits at the highest number in use, so the next record continues it"
  );

  // A preview deploy reads the shared production DB before production has
  // migrated: no function. The wrapper must answer 0, not throw (a throw
  // inside a transaction would poison it).
  const sentinel = new Error("e223-rollback");
  const seen = { n: -1 };
  try {
    await e223Tx(async () => {
      const tx = await e223GetDb();
      await tx.execute(e223Sql`drop function assign_estimate_numbers()`);
      e223ResetProbe();
      seen.n = await e223Assign();
      throw sentinel;
    });
  } catch (e) {
    if (e !== sentinel) throw e;
  }
  ok(seen.n === 0, "#223 preview safety: with no assign_estimate_numbers() (an un-migrated DB) the wrapper returns 0 instead of throwing");
  const back = e223Rows<{ fn: string | null }>(await db.execute(e223Sql`select to_regprocedure('assign_estimate_numbers()')::text as fn`));
  ok(!!back[0]?.fn, "#223 …and rolling that transaction back restores the function");
}

/* ======================================================================
   #223 T2 fix — Daylite history (no original dates) is numbered FIRST, by
   company then name then id, with every text key under COLLATE "C"; a
   soft-deleted sibling still holds its suffix; a lead newer than its
   converted quote takes the quote's number; the function-exists probe is
   cached after its first success.
   ====================================================================== */
import { upsertDoc as e223fUpsert } from "@/db/doc-store";
import { registerFixture as e223fRegister } from "./test-fixtures";

async function estimate223FixAsyncChecks(): Promise<void> {
  const db = await e223GetDb();
  await e223Assign();
  const id = (slug: string) => fixtureId("223fix", slug);
  const quote = (slug: string, t: number, extra: Partial<E223Quote> = {}): E223Quote => ({
    ...e223BuildQuote(id(slug), { name: "#223 fix " + slug, owner: "spec" }, "system", null, t),
    ...extra,
  });
  const lead = (slug: string, t: number, extra: Partial<E223Lead> = {}): E223Lead => ({
    ...e223MkLead({ id: id(slug), org: "#223 fix " + slug, createdAt: t }),
    ...extra,
  });
  const dlLeadId = "L-dl-e223fix";

  // Pass 1: an app-era quote OLDER than every Daylite import, plus Daylite
  // quotes and a Daylite lead whose import-time dates must not matter.
  await createFixture("quotes", quote("old", 1));
  await createFixture("quotes", quote("dl-beta", 50, { source: "daylite", customer: "Beta Co", name: "Anything" }));
  await createFixture("quotes", quote("dl-alpha-z", 5, { source: "daylite", customer: "  alpha  ", name: "zeta" }));
  await createFixture("quotes", quote("dl-alpha-e", 60, { source: "daylite", customer: "Alpha", name: "Echo" }));
  await createFixture("quotes", quote("dl-empty", 2, { source: "daylite", customer: "", name: "aaa" }));
  await createFixture("quotes", quote("dl-hyphen", 90, { source: "daylite", customer: "Al-Z Co", name: "x" }));
  e223fRegister("leads", dlLeadId);
  await e223fUpsert("leads", e223MkLead({ id: dlLeadId, org: "ALPHA", interest: "Foxtrot", createdAt: 70 }));

  const n1 = await e223Assign();
  ok(n1 === 7, `#223 fix: one pass numbers the six Daylite records and the app-era quote (got ${n1})`);
  const rows1 = [
    ...(await e223GetRows("quotes", ["old", "dl-beta", "dl-alpha-z", "dl-alpha-e", "dl-empty", "dl-hyphen"].map(id))),
    ...(await e223GetRows("leads", [dlLeadId])),
  ];
  const no1 = (rowId: string) => Number((rows1.find((r) => r.id === rowId)?.doc as Record<string, unknown> | undefined)?.estNo ?? -1);
  const order = [id("dl-hyphen"), id("dl-alpha-e"), dlLeadId, id("dl-alpha-z"), id("dl-beta"), id("dl-empty"), id("old")];
  const base = no1(order[0]);
  ok(
    base >= 1001 && order.every((rowId, i) => no1(rowId) === base + i),
    `#223 fix: Daylite history takes the lowest numbers — by company (lowercased, trimmed, byte order: "al-z co" < "alpha" < "beta co", empty last), then name ("echo" < "foxtrot" < "zeta") — got ${order.map(no1).join(",")}`
  );
  ok(no1(id("old")) > no1(id("dl-empty")), "#223 fix: an app-era quote older than every Daylite import is still numbered after them");
  ok(no1(dlLeadId) > no1(id("dl-alpha-e")) && no1(dlLeadId) < no1(id("dl-alpha-z")), "#223 fix: a Daylite lead (L-dl-…) sorts by its org and interest among the Daylite quotes");

  // Pass 2: a soft-deleted sibling holds its place in the suffix count.
  await createFixture("leads", lead("sd-lead", 100));
  await createFixture("quotes", quote("sd-1", 110, { leadId: id("sd-lead") }));
  await e223Assign();
  await e223SoftDelete("quotes", id("sd-1"));
  await createFixture("quotes", quote("sd-2", 120, { leadId: id("sd-lead") }));
  // …and a converted quote older than its lead.
  await createFixture("quotes", quote("cq", 200));
  await createFixture("leads", lead("cl", 210, { convertedQuoteId: id("cq") }));
  const n2 = await e223Assign();
  ok(n2 === 3, `#223 fix: the second pass numbers sd-2, the converted quote and its lead (got ${n2})`);

  const rows2 = [
    ...(await e223GetRows("quotes", ["sd-1", "sd-2", "cq"].map(id))),
    ...(await e223GetRows("leads", ["sd-lead", "cl"].map(id))),
  ];
  const f2 = (slug: string, k: "estNo" | "estSuffix") =>
    (rows2.find((r) => r.id === id(slug))?.doc as Record<string, unknown> | undefined)?.[k];
  ok(
    rows2.find((r) => r.id === id("sd-1"))?.deleted === true &&
      f2("sd-1", "estNo") === f2("sd-lead", "estNo") && f2("sd-1", "estSuffix") === undefined &&
      f2("sd-2", "estNo") === f2("sd-lead", "estNo") && f2("sd-2", "estSuffix") === 2,
    "#223 fix: a soft-deleted sibling counts — the next quote on the lead is -2, never a reuse of the bare number"
  );
  ok(
    typeof f2("cq", "estNo") === "number" && f2("cl", "estNo") === f2("cq", "estNo") && f2("cq", "estSuffix") === undefined,
    "#223 fix: a lead newer than its converted quote (convertedQuoteId) takes the quote's number"
  );

  // Idempotent: nothing left to number, and re-running every statement of
  // the migration file (ANALYZE included) changes no number.
  ok((await e223Assign()) === 0, "#223 fix: a further pass assigns nothing");
  const allIds = { quotes: ["old", "dl-beta", "dl-alpha-z", "dl-alpha-e", "dl-empty", "dl-hyphen", "sd-1", "sd-2", "cq"].map(id), leads: [dlLeadId, id("sd-lead"), id("cl")] };
  const snap = async () =>
    JSON.stringify(
      [...(await e223GetRows("quotes", allIds.quotes)), ...(await e223GetRows("leads", allIds.leads))].map((r) => [
        r.id,
        (r.doc as Record<string, unknown>).estNo,
        (r.doc as Record<string, unknown>).estSuffix,
      ])
    );
  const before = await snap();
  const file = e223ReadDir(e223Join(process.cwd(), "drizzle")).find((f) => /^\d{4}_estimate_numbers\.sql$/.test(f));
  const sqlText = file ? e223ReadFile(e223Join(process.cwd(), "drizzle", file), "utf8") : "";
  ok(/ANALYZE quotes;[\s\S]*ANALYZE leads;[\s\S]*SELECT assign_estimate_numbers\(\);/.test(sqlText), "#223 fix: the migration ANALYZEs quotes and leads before the backfill");
  let rerunError: unknown = null;
  try {
    for (const stmt of sqlText.split("--> statement-breakpoint").map((x) => x.trim()).filter(Boolean)) await db.execute(e223Sql.raw(stmt));
  } catch (e) {
    rerunError = e;
  }
  ok(rerunError === null && (await snap()) === before, `#223 fix: re-running the migration is harmless and changes no number (${String(rerunError)})`);

  // The probe is cached: once the function was found, a later call goes
  // straight to it (here it is dropped inside a rolled-back transaction, so
  // the cached call reaches the missing function and rejects).
  const sentinel = new Error("e223fix-rollback");
  const seen = { rejected: false };
  try {
    await e223Tx(async () => {
      const tx = await e223GetDb();
      await e223Assign();
      await tx.execute(e223Sql`drop function assign_estimate_numbers()`);
      try {
        await e223Assign();
      } catch {
        seen.rejected = true;
      }
      throw sentinel;
    });
  } catch (e) {
    if (e !== sentinel) throw e;
  }
  ok(seen.rejected, "#223 fix: after the first success the function-exists probe is skipped (cached)");
  const back = e223Rows<{ fn: string | null }>(await db.execute(e223Sql`select to_regprocedure('assign_estimate_numbers()')::text as fn`));
  ok(!!back[0]?.fn && (await e223Assign()) === 0, "#223 fix: …the rollback restores the function and the cached path works again");
}

/* ======================================================================
   #223 — allocation on create: new leads, a lead's quotes (carry + suffix),
   standalone quotes, renewals, the consulting auto-lead carry, update()
   never renumbering, and the id→number lookups.
   ====================================================================== */
import * as e223Quotes from "@/lib/stores/quotes";
import * as e223Leads from "@/lib/stores/leads";
import { all as e223AllCustomers } from "@/lib/stores/customers";
import { registerFixture as e223Register } from "./test-fixtures";
import {
  quoteNumbersFor as e223QuoteNos,
  leadNumbersFor as e223LeadNos,
  findQuoteIdByNumberOrId as e223FindQuote,
} from "@/lib/stores/estimate-numbers";

async function estimate223AllocationAsyncChecks(): Promise<void> {
  const id = (slug: string) => fixtureId(223, slug);
  const cust = (await e223AllCustomers())[0];
  const lead = await e223Leads.create({ id: id("alloc-lead"), org: "#223 Alloc Co", customerId: cust?.id ?? null }, "spec");
  e223Register("leads", lead.id);
  ok(e223IsNo(lead.estNo), "#223 allocation: a new lead is numbered on create");

  const conv = await e223Leads.convert(lead.id, {}, "spec");
  if (conv?.quoteId) e223Register("quotes", conv.quoteId);
  const first = conv?.quoteId ? await e223Quotes.get(conv.quoteId) : null;
  ok(
    !!first && first.estNo === lead.estNo && first.estSuffix === undefined && first.leadId === lead.id,
    "#223 allocation: a lead's first quote carries its number with no suffix, and links back by leadId"
  );
  ok(
    !!first && !!conv && conv.lead.activities.some((a) => a.note.includes(e223DisplayQuote(first))),
    "#223 allocation: the lead's conversion activity names the quote by its number"
  );

  const second = await e223Quotes.create({ id: id("alloc-second"), name: "#223 second", owner: "spec", leadId: lead.id, quoteType: "flame_test" });
  e223Register("quotes", second.id);
  ok(
    second.estNo === lead.estNo && second.estSuffix === 2 && e223FormatQuote(second) === `FLM-${lead.estNo}-2`,
    "#223 allocation: a second quote on the same opportunity is -2, under its own type's prefix"
  );

  const solo = await e223Quotes.create({ id: id("alloc-solo"), name: "#223 solo", owner: "spec" });
  e223Register("quotes", solo.id);
  ok(e223IsNo(solo.estNo) && solo.estNo > (lead.estNo ?? 0) && solo.estSuffix === undefined, "#223 allocation: a standalone quote takes the next number");

  const renewal = await e223Quotes.create({ id: id("alloc-renewal"), name: "#223 renewal", owner: "spec", quoteType: "flame_test", renewalOf: id("job") });
  e223Register("quotes", renewal.id);
  ok(renewal.estNo === (solo.estNo ?? 0) + 1, "#223 allocation: a renewal is a new estimate with the next number");

  const kept = await e223Quotes.update(solo.id, { estNo: 1, estSuffix: 9, name: "#223 solo renamed" });
  ok(kept?.estNo === solo.estNo && kept?.estSuffix === undefined && kept?.name === "#223 solo renamed", "#223 allocation: quotes.update() never changes an allocated number");
  const keptLead = await e223Leads.update(lead.id, { estNo: 1 });
  ok(keptLead?.estNo === lead.estNo, "#223 allocation: leads.update() never changes an allocated number");

  const con = await e223Quotes.create({ id: id("alloc-con"), name: "#223 consulting", owner: "spec", quoteType: "consulting" });
  e223Register("quotes", con.id);
  const autoLead = await e223Leads.create({ id: id("alloc-autolead"), org: "#223 Auto", estNo: con.estNo ?? null }, "spec");
  e223Register("leads", autoLead.id);
  ok(autoLead.estNo === con.estNo && e223DisplayLead(autoLead) === `OPP-${con.estNo}`, "#223 allocation: the consulting auto-lead takes its proposal's number");

  const again = await e223Quotes.create({ id: id("alloc-solo"), name: "#223 solo re-created", owner: "spec" });
  ok(again.estNo === solo.estNo, "#223 allocation: create() over an existing id keeps that quote's number");

  const qn = await e223QuoteNos([solo.id, second.id, "Q-NOPE-223", null]);
  ok(qn.get(solo.id) === e223DisplayQuote(again) && qn.get(second.id) === `FLM-${lead.estNo}-2` && !qn.has("Q-NOPE-223"), "#223 lookup: quoteNumbersFor maps ids to display numbers and skips missing ids");
  const ln = await e223LeadNos([lead.id]);
  ok(ln.get(lead.id) === `OPP-${lead.estNo}`, "#223 lookup: leadNumbersFor");
  ok(
    (await e223FindQuote(solo.id)) === solo.id &&
      (await e223FindQuote(`est-${solo.estNo}`)) === solo.id &&
      (await e223FindQuote(`FLM-${lead.estNo}-2`)) === second.id &&
      (await e223FindQuote(String(lead.estNo))) === null &&
      (await e223FindQuote("nothing-223")) === null,
    "#223 lookup: findQuoteIdByNumberOrId takes an id or one exact number; an ambiguous bare number (shared by a lead's quotes) resolves to nothing"
  );
}

/* ======================================================================
   #223 T3 review — no writer wipes or rewrites a stored number: a stale
   whole-doc upsert, a stale patchDoc and a batch upsert all keep what the
   database allocated; a duplicate/copy is a NEW estimate; a create inside
   an outer transaction is not numbered there (the global advisory lock
   would be held until that transaction commits) and the next create heals it.
   ====================================================================== */
import { patchDoc as e223tPatch, upsertDocs as e223tUpsertMany } from "@/db/doc-store";

async function estimate223WritersAsyncChecks(): Promise<void> {
  const id = (slug: string) => fixtureId(223, slug);
  const lead = await e223Leads.create({ id: id("w-lead"), org: "#223 Writers" }, "spec");
  e223Register("leads", lead.id);
  const q1 = await e223Quotes.create({ id: id("w-q1"), name: "#223 w1", owner: "spec", leadId: lead.id });
  e223Register("quotes", q1.id);
  const q2 = await e223Quotes.create({ id: id("w-q2"), name: "#223 w2", owner: "spec", leadId: lead.id });
  e223Register("quotes", q2.id);
  ok(e223IsNo(q2.estNo) && q2.estNo === lead.estNo && q2.estSuffix === 2, "#223 writers: fixtures numbered (the -2 is what the stale writes below must keep)");

  // A copy read BEFORE numbering, written back after it (a stale whole doc).
  const stale = { ...q2 } as E223Quote;
  delete stale.estNo;
  delete stale.estSuffix;
  await e223fUpsert("quotes", { ...stale, name: "#223 w2 stale" });
  const afterStale = await e223Quotes.get(q2.id);
  ok(
    afterStale?.estNo === q2.estNo && afterStale?.estSuffix === 2 && afterStale?.name === "#223 w2 stale",
    "#223 writers: a stale whole-doc upsert (no estNo) keeps the stored number and suffix, and still saves its other fields"
  );
  await e223fUpsert("quotes", { ...stale, estNo: 1, estSuffix: 7 });
  const afterForged = await e223Quotes.get(q2.id);
  ok(afterForged?.estNo === q2.estNo && afterForged?.estSuffix === 2, "#223 writers: a whole-doc upsert carrying a different estNo/estSuffix cannot change them");
  await e223tUpsertMany("quotes", [{ ...stale, name: "#223 w2 batch" }]);
  const afterBatch = await e223Quotes.get(q2.id);
  ok(afterBatch?.estNo === q2.estNo && afterBatch?.estSuffix === 2 && afterBatch?.name === "#223 w2 batch", "#223 writers: a batch upsert keeps the stored number too");
  await e223tUpsertMany("quotes", [{ ...stale, estNo: 1, estSuffix: 7 }]);
  const afterBatchForged = await e223Quotes.get(q2.id);
  ok(afterBatchForged?.estNo === q2.estNo && afterBatchForged?.estSuffix === 2, "#223 writers: …and a batch upsert cannot rewrite it");
  await e223tPatch<E223Lead>("leads", lead.id, (l) => {
    delete l.estNo;
    l.interest = "#223 stale patch";
    return l;
  });
  const afterPatch = await e223Leads.get(lead.id);
  ok(afterPatch?.estNo === lead.estNo && afterPatch?.interest === "#223 stale patch", "#223 writers: a patchDoc whose doc lost estNo (read before numbering) keeps the stored number");
  await e223tPatch<E223Lead>("leads", lead.id, (l) => ({ ...l, estNo: 1 }));
  ok((await e223Leads.get(lead.id))?.estNo === lead.estNo, "#223 writers: a patchDoc cannot rewrite a lead's number");

  // A duplicate/copy of a numbered quote is a new estimate — the spread
  // estNo/estSuffix never travel (create() builds field by field).
  const src = (await e223Quotes.get(q1.id))!;
  const dup = await e223Quotes.create({ ...src, id: id("w-dup"), leadId: null, name: "#223 w1 copy" });
  e223Register("quotes", dup.id);
  ok(e223IsNo(dup.estNo) && dup.estNo > (q2.estNo ?? 0) && dup.estSuffix === undefined, "#223 writers: a duplicate of a numbered quote gets its own new number");
  const minted = await e223Quotes.create({ ...src, id: undefined, leadId: null, name: "#223 w1 copy 2" });
  e223Register("quotes", minted.id);
  ok(e223IsNo(minted.estNo) && minted.estNo === (dup.estNo ?? 0) + 1, "#223 writers: …a minted-id copy too (the next number, never the source's)");

  // Inside an outer transaction the create is not numbered (the lock would
  // live as long as that transaction); the next create outside heals it.
  // Ids sort in create order, so a same-millisecond tie (ordered by id) still numbers the in-tx quote first.
  e223Register("quotes", id("w-1-intx"));
  const inTx: { q: E223Quote | null } = { q: null };
  await e223Tx(async () => {
    inTx.q = await e223Quotes.create({ id: id("w-1-intx"), name: "#223 in tx", owner: "spec" });
  });
  ok(!!inTx.q && inTx.q.estNo === undefined, "#223 writers: a create inside an outer transaction is left unnumbered (never holds the global numbering lock past its own statement)");
  const healer = await e223Quotes.create({ id: id("w-2-healer"), name: "#223 healer", owner: "spec" });
  e223Register("quotes", healer.id);
  const healed = await e223Quotes.get(id("w-1-intx"));
  ok(e223IsNo(healed?.estNo) && e223IsNo(healer.estNo) && (healed?.estNo ?? 0) < healer.estNo, "#223 writers: …and the next create outside a transaction numbers it (oldest first)");
}

/* ======================================================================
   #223 — display sweep A: search + quotes hub + intake + Estimator. The
   screens are server/client components the harness can't render, so these
   are landmark guards: the old id-as-label text is gone and the number
   helpers are wired in. Behaviour of the helpers is asserted in Task 1.
   ====================================================================== */
import { quoteDocumentDataFor as e223QuoteDocData } from "@/lib/quote-pdf/quote-document-data";
import { pdfDocKey as e223PdfDocKey } from "@/app/(app)/estimator/pdf-doc-key";
import { DEFAULT_PDF_OPTIONS as E223_DEFAULT_PDF_OPTIONS } from "@/lib/quote-pdf/pdf-options";
function e223Src(rel: string): string {
  return e223ReadFile(e223Join(process.cwd(), rel), "utf8");
}
{
  const hub = e223Src("src/app/(app)/quotes/page.tsx");
  ok(!hub.includes("{q.id} · {owner}") && hub.includes("{displayQuoteNumber(q)} · {owner}"), "#223 quotes hub: rows show the estimate number, not the internal id");
  ok(hub.includes("quoteMatchesSearch(q, searchTerm)") && hub.includes('name="q"'), "#223 quotes hub: a search box filters by number, old id, name and customer");
  ok(hub.includes("was {q.id}"), "#223 quotes hub: the selected panel shows 'was Q-…' in small type");
  ok(hub.includes("quoteSearchRank(") && hub.includes("number={displayQuoteNumber(q)}"), "#223 quotes hub: exact-number hits list first; revision history names the number");
  ok(e223Src("src/app/(app)/quotes/controls.tsx").includes("Priced snapshots of {number || id}"), "#223 quotes hub: the revision-history drawer names the quote by its number");
  const search = e223Src("src/app/api/search/route.ts");
  ok(search.includes('listDocsByField("quotes", "estNo"') && search.includes('listDocsByField("leads", "estNo"') && search.includes("quoteMatchesSearch("), "#223 ⌘K: typed numbers are looked up by value; quotes also match by old id");
  // Designs/surveys/inspections keep their own ids; only the Quotes → Designs span is checked.
  const quoteGroups = search.slice(search.indexOf('"Quotes",'), search.indexOf('"Designs",'));
  ok(quoteGroups.length > 0 && !quoteGroups.includes("sub: `${d.id} · ") && quoteGroups.includes("displayLeadNumber("), "#223 ⌘K: quote and opportunity sub-lines show numbers, not ids");
  ok(search.includes("quoteSearchRank("), "#223 ⌘K: exact-number quote hits rank first");
  const intake = e223Src("src/app/(app)/quotes/new/intake-form.tsx");
  ok(!intake.includes("replacing.id") && intake.includes("replacing.number"), "#223 Change type intake names the quote by its number");
  const est = e223Src("src/app/(app)/estimator/estimator-client.tsx");
  ok(est.includes("setQuoteId(res.number ?? res.id)") && est.includes("({moveNotice.targetNumber})"), "#223 Estimator: header + move notice show numbers");
  ok(e223Src("src/app/(app)/estimator/page.tsx").includes("quoteId: displayQuoteNumber(q)"), "#223 Estimator: the header label starts as the quote's number");
  ok(e223Src("src/app/(app)/estimator/section-card.tsx").includes("{hit.number}"), "#223 Estimator: the move-to picker lists numbers");
  ok(e223Src("src/app/(app)/estimator/actions.ts").includes("quoteSearchRank("), "#223 Estimator: the move-to picker finds by number and ranks exact hits first");

  // The saved customer PDF (#222) prints the number; an unnumbered quote its id.
  const docBase = { name: "", customer: "Walk-in", customerId: null, owner: "", updatedAt: 5, createdAt: 5 };
  const numbered = e223QuoteDocData({ ...docBase, id: "Q-2041", estNo: 1005, estSuffix: 2 } as never, null, { companyName: "", logoDark: null });
  const unnumbered = e223QuoteDocData({ ...docBase, id: "Q-2042" } as never, null, { companyName: "", logoDark: null });
  ok(numbered.quoteId === "EST-1005-2" && unnumbered.quoteId === "Q-2042", "#223 saved quote PDF: prints the estimate number, else the internal id");
  // …and the PDF's fingerprint carries that number, so a renumbered document reads as out of date.
  const keyBase = {
    projectName: "P", custName: "C", customerId: null, locationId: null, contactName: "", quoteNote: "", assumptions: "",
    paymentTerms: "Unknown", sections: [], vendorQuotes: [], pdfOptions: E223_DEFAULT_PDF_OPTIONS,
  };
  ok(
    e223PdfDocKey({ ...keyBase, quoteNumber: "Q-2041" }) !== e223PdfDocKey({ ...keyBase, quoteNumber: "EST-1005" }) &&
      e223PdfDocKey({ ...keyBase, quoteNumber: "EST-1005" }) === e223PdfDocKey({ ...keyBase, quoteNumber: "EST-1005" }),
    "#223 pdfDocKey: the printed estimate number is part of the saved-PDF fingerprint"
  );
}

/* ======================================================================
   #223 — display sweep B: builders, letters, PDFs, packages, repairs, portal.
   Landmark guards, like sweep A: text shown to people prints the estimate
   number; hrefs, hidden inputs, Blob paths and package keys keep the id.
   ====================================================================== */
