  const g2 = c255T9Stretch(tpl2, keys2, D2({ movables: { c: { wall: "diag", t: 0.5 } } }));
  const f = { x: -136, y: -260 }, e = { x: 136, y: 100 }, L = Math.hypot(e.x - f.x, e.y - f.y), u = { x: (e.x - f.x) / L, y: (e.y - f.y) / L }, n = { x: u.y, y: -u.x };
