/* ======================================================================
   Manufacturer analytics — quoted cost, win rate and forecast (pure).
   ====================================================================== */
import { manufacturerAnalytics, rollupMetrics as maRollup, attributedLines as maLines, type AnalyticsQuote as MaQuote } from "@/lib/manufacturer-analytics";
{
  const DAY = 86400000;
  const now = Date.UTC(2026, 9, 1);
  const parts = new Map([
    ["S1", { sku: "S1", mfr: "ETC", desc: "Source Four" }],
    ["S2", { sku: "S2", mfr: "Allen & Heath", desc: "SQ-5" }],
    ["C1", { sku: "C1", mfr: "ETC", desc: "Lamp" }],
  ]);
  const canon = (k: string) => (k === "allenheath" ? "allenandheath" : k);
  const mk = (id: string, status: string, createdAt: number, history: Array<{ at: number; to: string }>, items: unknown[]) =>
    ({ id, status, createdAt, updatedAt: createdAt, history, spec: { sections: [{ id: "s", name: "S", kind: "materials", mfr: "", freightPct: 0, items }] } }) as unknown as MaQuote;
  const q1 = mk("Q1", "won", now - 100 * DAY, [{ at: now - 50 * DAY, to: "won" }], [
    { sku: "S1", qty: 2, cost: 100, price: 150 },
    { sku: "L", qty: 5, cost: 50, price: 80, labor: true },
    { sku: "S1", qty: 1, cost: 100, price: 150, option: true },
    { sku: "", qty: 1, cost: 500, price: 600, allowance: true },
    { sku: "fa-1", qty: 2, cost: 0, price: 0, components: [{ sku: "C1", label: "", role: "other", qty: 3, unit: "ea", cost: 10, price: 20 }] },
    { sku: "X9", qty: 1, cost: 40, price: 60, manufacturer: "Allen and Heath" },
  ]);
  const q2 = mk("Q2", "lost", now - 80 * DAY, [{ at: now - 40 * DAY, to: "lost" }], [{ sku: "S1", qty: 1, cost: 100, price: 150 }]);
  const q3 = mk("Q3", "sent", now - 10 * DAY, [], [{ sku: "S1", qty: 4, cost: 100, price: 150 }, { sku: "S2", qty: 1, cost: 200, price: 300 }]);
  const q4 = mk("Q4", "draft", now - 5 * DAY, [], [{ sku: "S1", qty: 1, cost: 100, price: 150 }]);
  const q5 = mk("Q5", "won", now - 500 * DAY, [{ at: now - 400 * DAY, to: "won" }], [{ sku: "S1", qty: 10, cost: 100, price: 150 }]);
  const res = manufacturerAnalytics([q1, q2, q3, q4, q5], parts, canon, now);
  const etc = res.byKey.get("etc")!;
  const ah = res.byKey.get("allenandheath")!;
  ok(!!etc && !!ah && !res.byKey.has("allenheath"), "mfr analytics: manufacturers resolve to canonical keys");
  ok(etc.quoted.cost === 760 && etc.quoted.sell === 2 * 150 + 2 * 3 * 20 + 150 + 600, "mfr analytics: quoted counts sent/won/lost lines in the window, fixture components expanded (cost 760)");
  ok(etc.won.cost === 260 && etc.lost.cost === 100 && etc.open.cost === 400 && etc.draft.cost === 100, "mfr analytics: won, lost, open and draft split by status");
  ok(etc.quotes === 3, "mfr analytics: quote count is distinct quotes in Quoted (draft and out-of-window excluded)");
  ok(Math.abs((etc.winRate ?? -1) - 260 / 360) < 1e-9 && !etc.usedShopRate, "mfr analytics: win rate is won ÷ (won + lost) by cost");
  ok(Math.abs(etc.forecast.cost - (400 * 260) / 360) < 1e-9, "mfr analytics: forecast is open × the manufacturer's win rate");
  ok(ah.won.cost === 40 && ah.open.cost === 200 && ah.winRate === 1 && ah.forecast.cost === 200, "mfr analytics: a line's own manufacturer text and a catalog mfr land under one canonical key");
  ok(ah.quoted.cost === 240, "mfr analytics: labor, option and allowance lines are excluded");
  ok(maLines(q1, parts, canon).length === 3 && maLines(q1, parts, canon).every((l) => l.cost > 0), "mfr analytics: attributedLines skips labor, option and allowance (S1, the fixture component and X9 are counted)");
  ok(etc.monthlyWon.length === 12 && etc.monthlyWon[11].month === "2026-09" && etc.monthlyWon[0].month === "2025-10", "mfr analytics: monthly won has 12 buckets ending with now's month");
  const wonMonth = etc.monthlyWon.find((m) => m.cost > 0);
  ok(!!wonMonth && wonMonth.month === "2026-08" && wonMonth.cost === 260 && etc.monthlyWon.reduce((a, m) => a + m.cost, 0) === 260, "mfr analytics: the won month holds the won cost and nothing else does");
  ok(etc.topParts[0].sku === "S1" && etc.topParts.length <= 10, "mfr analytics: top parts lead with the highest quoted cost");
  ok(res.shopWinRate !== null && Math.abs(res.shopWinRate - 300 / 400) < 1e-9, "mfr analytics: shop win rate is won ÷ (won + lost) across every manufacturer");
  const roll = maRollup([etc, ah], res.shopWinRate);
  ok(roll.quoted.cost === 1000 && roll.won.cost === 300 && roll.lost.cost === 100 && Math.abs((roll.winRate ?? -1) - 0.75) < 1e-9 && roll.keys.join() === "etc,allenandheath", "mfr analytics: rollup sums costs and recomputes the win rate from summed won/lost");
  ok(Math.abs(roll.forecast.cost - (etc.forecast.cost + ah.forecast.cost)) < 1e-9 && roll.quotes === 3, "mfr analytics: rollup forecast is the sum of the rows' forecasts and quotes are counted once (Q1, Q2, Q3)");
  ok(etc.monthlyWon.reduce((a, m) => a + m.cost, 0) === etc.won.cost && etc.monthlyWon.reduce((a, m) => a + m.sell, 0) === etc.won.sell, "mfr analytics: the Won total equals the sum of the monthly chart");
  ok(res.windowStart === Date.UTC(2025, 9, 1, 5), "mfr analytics: the window starts at midnight Chicago on the first day of the oldest chart month");
  const qx = mk("QX", "won", now - 400 * DAY, [{ at: now - 30 * DAY, to: "won" }], [{ sku: "S1", qty: 1, cost: 70, price: 90 }]);
  const resX = manufacturerAnalytics([qx], parts, canon, now).byKey.get("etc")!;
  ok(resX.won.cost === 70 && resX.quoted.cost === 0 && resX.quotes === 0, "mfr analytics: a quote created before the window but won inside it counts in Won, not Quoted");
  const qe = mk("QE", "sent", now - 2 * DAY, [], [
    { sku: "S1", qty: 1, cost: 1000, price: 1500, por: true },
    { sku: "", qty: 1, cost: 0, price: -50, rewardCredit: true },
    { sku: "S1", qty: 1, cost: 1000, price: 1500, laborOverhead: "shop" },
    { sku: "S1", qty: 1, cost: 1000, price: 1500, laborTravel: "hotel" },
    { sku: "S1", qty: 0, cost: 1000, price: 1500 },
    { sku: "S1", qty: 1, cost: 5, price: 8 },
    { sku: "", qty: 2, cost: 30, price: 40, desc: "Custom cable", manufacturer: "Neutrik" },
  ]);
  (qe as unknown as { spec: { sections: unknown[] } }).spec.sections.push({ id: "l", name: "Labor", kind: "labor", mfr: "", freightPct: 0, items: [{ sku: "S1", qty: 1, cost: 999, price: 1 }] });
  const lines = maLines(qe, parts, canon);
  ok(lines.length === 2 && lines.reduce((a, l) => a + l.cost, 0) === 65, "mfr analytics: por, rewards credit, labor overhead/travel, a labor section and zero-qty lines are excluded");
  const resE = manufacturerAnalytics([qe], parts, canon, now).byKey.get("neutrik")!;
  ok(resE.topParts[0].sku === "" && resE.topParts[0].desc === "Custom cable" && resE.topParts[0].cost === 60, "mfr analytics: a line with no sku is keyed by its description in top parts");
  const qc = mk("QC", "sent", now - 2 * DAY, [], [{ sku: "fa-2", qty: 1, cost: 0, price: 0, manufacturer: "Neutrik", components: [{ sku: "NOPE", label: "Plug", role: "other", qty: 2, unit: "ea", cost: 5, price: 9 }] }]);
  ok(maLines(qc, parts, canon).length === 1 && maLines(qc, parts, canon)[0].key === "neutrik", "mfr analytics: a component with no catalog manufacturer falls back to the line's manufacturer");
  const q6 = mk("Q6", "sent", now - 3 * DAY, [], [{ sku: "Z1", qty: 1, cost: 100, price: 150, manufacturer: "Neutrik" }]);
  const res2 = manufacturerAnalytics([q1, q2, q6], parts, canon, now);
  const neu = res2.byKey.get("neutrik")!;
  ok(neu.winRate === null && neu.usedShopRate === true && !manufacturerAnalytics([q6], parts, canon, now).byKey.get("neutrik")!.usedShopRate && neu.open.cost === 100 && Math.abs(neu.forecast.cost - 100 * (res2.shopWinRate ?? 0)) < 1e-9, "mfr analytics: a manufacturer with no decided quotes forecasts at the shop win rate");
}

/* ======================================================================
   Manufacturer analytics — the loader, the vendor card model (PGlite).
   ====================================================================== */
import { loadManufacturerAnalytics as maLoad } from "@/lib/manufacturer-analytics-load";
import { vendorQuotedVM as maVendorVm } from "@/lib/vendor-quoted";
import { create as maCreateQuote, update as maUpdateQuote } from "@/lib/stores/quotes";
async function mfrAnalyticsLoadAsyncChecks(): Promise<void> {
  const sku = fixtureId("MAL", "PART");
  await upsertPart({ id: sku, sku, desc: "mfr analytics part", category: "Lighting", unit: "ea", list: 200, cost: 100, mfr: "MfaBrand" });
  registerFixture("catalog_parts", sku);
  const spec = (items: unknown[]) => ({ sections: [{ id: "s", name: "S", kind: "materials", mfr: "", freightPct: 0, items }] }) as never;
  const qa = fixtureId("MAL", "Q-SENT");
  const qb = fixtureId("MAL", "Q-WON");
  const qc = fixtureId("MAL", "Q-DRAFT");
  for (const id of [qa, qb, qc]) registerFixture("quotes", id);
  await maCreateQuote({ id: qa, name: "mal sent", customer: "MAL Test" });
  await maUpdateQuote(qa, { status: "sent", spec: spec([{ sku, qty: 2, cost: 100, price: 150 }]) });
  await maCreateQuote({ id: qb, name: "mal won", customer: "MAL Test" });
  await maUpdateQuote(qb, { status: "won", history: [{ at: Date.now(), to: "won" }], spec: spec([{ sku, qty: 1, cost: 50, price: 80 }]) });
  await maCreateQuote({ id: qc, name: "mal draft", customer: "MAL Test" });
  await maUpdateQuote(qc, { spec: spec([{ sku, qty: 3, cost: 100, price: 150 }]) });
  const res = await maLoad();
  const m = res.byKey.get("mfabrand");
  ok(!!m && m.quoted.cost === 250 && m.quoted.sell === 2 * 150 + 80, "mfr analytics: the loader reads real quotes and the catalog (sent + won = quoted cost 250)");
  ok(!!m && m.open.cost === 200 && m.won.cost === 50 && m.draft.cost === 300 && m.quotes === 2, "mfr analytics: the loader splits open, won and draft and counts distinct quotes");
  ok(res.canonical("mfabrand") === "mfabrand" && res.windowStart < res.now, "mfr analytics: the loader returns a canonical resolver and the window");
  const vm = maVendorVm(["MfaBrand", "MFA Brand", "Nobody At All"], res.byKey, res.shopWinRate, res.canonical);
  ok(!!vm && vm.rows.length === 1 && vm.rows[0].key === "mfabrand" && vm.rows[0].name === "MfaBrand" && vm.quoted.cost === 250, "mfr analytics: the vendor card lists a manufacturer once however it is spelled, and skips one with no metrics");
  ok(maVendorVm(["Nobody At All"], res.byKey, res.shopWinRate, res.canonical) === null && maVendorVm([], res.byKey, res.shopWinRate, res.canonical) === null, "mfr analytics: the vendor card is hidden when no claimed manufacturer has metrics");
  ok(res.hasPage("mfabrand") && !res.hasPage("nobodyatall"), "mfr analytics: the loader knows which manufacturer keys have a page");
  ok(!!m && !m.includesCatalogCost, "mfr analytics: estimator-only metrics are not flagged as catalog cost");
  // A Grid quote (flat spec.lines, no sections) counts at today's catalog cost.
  const qg = fixtureId("MAL", "Q-GRID");
  registerFixture("quotes", qg);
  await maCreateQuote({ id: qg, name: "mal grid", customer: "MAL Test" });
  await maUpdateQuote(qg, { status: "sent", spec: { kind: "grid", gridProjectId: "GP-x", gridOptionId: "o1", lines: [{ sku, desc: "x", qty: 2, unit: "ea", price: 300, ext: 600 }, { sku: "allow:x:good", desc: "a", qty: 1, unit: "lot", price: 50, ext: 50, allowance: true }] } as never });
  const resG = await maLoad();
  const mg = resG.byKey.get("mfabrand");
  ok(!!mg && mg.open.cost === 400 && mg.open.sell === 2 * 150 + 600 && mg.quoted.cost === 450 && mg.includesCatalogCost, "mfr analytics: the loader counts a Grid quote's lines at the catalog's current cost (open 200 + 2 × 100)");
}

