/* #300 object symbols — SVG sanitizer (Task 4) */
import { sanitizeSvg, SVG_MAX_BYTES } from "@/lib/part-docs/svg-sanitize";
import { sniffDocumentType as sniff300 } from "@/lib/part-docs/files";
{
  const enc = (s: string) => new TextEncoder().encode(s);
  const S = (inner: string, attrs = "") => `<?xml version="1.0"?><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10"${attrs}>${inner}</svg>`;
  const a = sanitizeSvg(S('<script>alert(1)</script><rect width="5" height="5" onclick="x()"/>'));
  ok(a.ok && !/script|onclick/i.test(a.svg) && a.svg.includes("<rect"), "#300 svg: script element and on* attributes removed");
  const b = sanitizeSvg(S('<foreignObject><div>x</div></foreignObject><image href="https://evil/x.png"/><use xlink:href="#a"/>'));
  ok(b.ok && !/foreignObject|evil/i.test(b.svg) && b.svg.includes('xlink:href="#a"'), "#300 svg: foreignObject + external href removed, #fragment kept");
  const c = sanitizeSvg(S('<style>@import url(https://x/y.css); .st0{fill:url(https://x/p)}</style><a href="javascript:alert(1)"><rect/></a>'));
  ok(c.ok && !/@import|https:\/\/x|javascript:/i.test(c.svg), "#300 svg: style imports, external url() and javascript: hrefs removed");
  ok(!sanitizeSvg("<html><body>hi</body></html>").ok && !sanitizeSvg("x".repeat(SVG_MAX_BYTES + 1)).ok, "#300 svg: non-svg root and oversize refused");
  ok(!sanitizeSvg(S("") + S("")).ok, "#300 svg: two roots refused");
  const real = readFileSync(join(process.cwd(), "docs/test-fixtures/davinci-symbol-sample.svg"), "utf8");
  const r = sanitizeSvg(real);
  ok(r.ok && r.svg.includes("<style") && r.svg.includes("viewBox"), "#300 svg: a real DaVinci drawing survives with its styles and viewBox");
  const scr = sanitizeSvg(readFileSync(join(process.cwd(), "docs/test-fixtures/davinci-symbol-script.svg"), "utf8"));
  ok(scr.ok && !/<script/i.test(scr.svg) && scr.removed.includes("script"), "#300 svg: DaVinci's one scripted drawing is cleaned");
  ok(sniff300(enc("﻿  <?xml version='1.0'?>\n<!-- c --><svg xmlns='http://www.w3.org/2000/svg'/>")) === "svg" && sniff300(enc("<html></html>")) !== "svg", "#300 svg: sniffing recognises SVG text");
  const d = sanitizeSvg(S('<svg:script>alert(1)</svg:script><SCRIPT type="x"><scrIpt>a</scrIpt>b</SCRIPT><rect/onload=alert(1) title="a>b"/><rect\nONMOUSEOVER\n=\n\'x()\' width="1"/><script><![CDATA[ </script> alert(2) ]]></script>'));
  ok(d.ok && !/script|onload|onmouseover|alert/i.test(d.svg) && d.svg.includes('title="a&gt;b"') && d.svg.includes('width="1"'), "#300 svg: namespaced/mixed-case/nested/CDATA scripts and unquoted or newline on* attributes removed");
  const e = sanitizeSvg(S('<a href="&#106;avascript:alert(1)"><rect/></a><set attributeName="href" to="java&#x09;script:alert(1)"/><rect fill="url(&#x27;https://x/p&#x27;)" style="fill:u\\72l(https://x/q)"/>'));
  const e2 = sanitizeSvg(S('<rect><title>&#106;avascript:alert(1)</title></rect>'));
  ok(e.ok && !/&#|javascript|https:\/\/x|<set/i.test(e.svg) && !e2.ok, "#300 svg: entity-encoded javascript:, href animation and CSS-escaped url() never survive");
  const X = (inner: string, attrs = "") => `<svg xmlns="http://www.w3.org/2000/svg"${attrs}>${inner}</svg>`;
  const t0 = Date.now();
  sanitizeSvg(X("<style>url(" + " ".repeat(900_000) + "</style>"));
  ok(Date.now() - t0 < 1000, "#300 svg: a crafted 1 MB style can't stall the server");
  const t1 = Date.now();
  sanitizeSvg(X("<style>" + "url(".repeat(240_000) + "</style>"));
  ok(Date.now() - t1 < 1000, "#300 svg: 1 MB of repeated url( can't stall the server");
  const t2 = Date.now();
  sanitizeSvg(X("", " " + Array.from({ length: 80_000 }, (_, i) => `a${i}="1"`).join(" ")));
  ok(Date.now() - t2 < 1000, "#300 svg: 1 MB of distinct attributes can't stall the server");
  const t3 = Date.now();
  sanitizeSvg(X("<a" + "b".repeat(900_000)));
  ok(Date.now() - t3 < 1000, "#300 svg: a 1 MB unclosed tag can't stall the server");
  const split = [
    sanitizeSvg(X('<style>@imp<![CDATA[ort "https://x/a.css";]]></style>')),
    sanitizeSvg(X('<style>@imp<g/>ort "https://x/b.css";</style>')),
    sanitizeSvg(X("<style>.a{fill:u<![CDATA[rl(https://x/c)]]>}</style>")),
  ];
  ok(split.every((r) => r.ok && !/@import|https:\/\/x|CDATA|<g/i.test(r.svg)) && split[1].ok && split[1].removed.includes("style elements"), "#300 svg: a style split by CDATA or a child element is cleaned as one");
  const cd = sanitizeSvg(X("<desc><![CDATA[><img src=x onerror=alert(1)>]]></desc>"));
  ok(cd.ok && !cd.svg.includes("<![CDATA[") && !cd.svg.includes("<img") && cd.svg.includes("&lt;img"), "#300 svg: CDATA is written as escaped text, never markup");
  const q = sanitizeSvg(X('<style>.a{font-family:"A\\"B"}</style><rect style=\'font-family:"C\\"D"\'/>'));
  ok(q.ok && q.svg.includes('"A\\"B"') && q.svg.includes("&quot;C\\&quot;D&quot;") && q.removed.length === 0, "#300 svg: legitimate CSS escapes are kept as written");
  const fa = sanitizeSvg(X('<image srcset="https://x/1.png 1x" href="#i"/><g xml:base="https://x/"><rect background="https://x/2.png"/></g>'));
  ok(fa.ok && !/srcset|xml:base|background|https:\/\/x/.test(fa.svg) && fa.svg.includes('href="#i"') && fa.removed.includes("external links"), "#300 svg: srcset, xml:base and other fetch attributes dropped");
  const is = sanitizeSvg(X('<rect style="background-image:image-set(&quot;#a&quot; 1x,&quot;https://x/h&quot; 2x)"/>'));
  ok(is.ok && !/image-set/i.test(is.svg) && is.svg.includes("invalid("), "#300 svg: image-set with a leading #fragment still can't fetch a later URL");
  const mm = [sanitizeSvg(X("<style><g></style>@import url(https://x/m.css);</style>")), sanitizeSvg(X("<script><g></script></script>"))];
  ok(mm.every((r) => !r.ok), "#300 svg: a close tag matching nothing inside a dropped element is refused");
  const sp = sanitizeSvg(X("<style>u@import x;rl(https://e)</style>"));
  ok(!sp.ok || !sp.svg.includes("url(https://e"), "#300 svg: a removed @import never splices its neighbours into url(");
}

/* ======================================================================
   #300 Task 5 — symbol / riser drawing kinds (D606–D608): kinds + byte
   rules, SVG allowed for the upload token, the sandboxed serve route, the
   sanitize-to-a-new-blob write path (fake Blob deps), and one current
   drawing link per part per kind (store level).
   ====================================================================== */
import { isPartDocKind as pd300IsKind } from "@/lib/part-docs/types";
import { checkDocumentBytes as pd300Check, UPLOAD_CONTENT_TYPES as pd300UploadTypes } from "@/lib/part-docs/files";
import { storeDrawingUpload as pd300StoreDrawing } from "@/lib/part-docs/drawing-upload";
import {
  attachDocument as pd300Attach,
  createDocument as pd300CreateDoc,
  documentLinkId as pd300LinkId,
  documentLinksForParts as pd300LinksFor,
} from "@/lib/stores/part-documents";
async function partDocSymbolAsyncChecks300(): Promise<void> {
  const svgBytes = new TextEncoder().encode('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10"><rect width="10" height="10"/></svg>');
  ok(pd300IsKind("symbol") && pd300IsKind("riser"), "#300 drawings: symbol and riser are part-document kinds");
  const sym = pd300Check("symbol", svgBytes);
  ok(sym.ok && sym.contentType === "image/svg+xml" && !pd300Check("datasheet", svgBytes).ok, "#300 drawings: a symbol takes SVG bytes; a datasheet still refuses them");
  ok(pd300UploadTypes.includes("image/svg+xml"), "#300 drawings: the upload token allows image/svg+xml (checkDocumentBytes is the authority)");
  const route = readFileSync(join(process.cwd(), "src/app/api/part-documents/[id]/route.ts"), "utf8");
  ok(route.includes("sandbox; default-src 'none'; img-src data:; style-src 'unsafe-inline'") && route.includes('contentType.startsWith("image/svg")'),
    "#300 drawings: the serve route sandboxes an image/svg+xml response (CSP sandbox, default-src 'none')");

  // The SVG write path: sanitized text to a NEW blob, original deleted, what was stripped recorded.
  const blobs = new Map<string, Uint8Array>([["part-docs/PD-sym300a/x.svg", new TextEncoder().encode('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script><rect onclick="x()" width="1"/></svg>')]]);
  const removed: string[] = [];
  const stored = await pd300StoreDrawing("PD-sym300a", { blobKey: "part-docs/PD-sym300a/x.svg", fileName: "x.svg", contentType: "image/svg+xml", size: 99 }, {
    read: async (p) => blobs.get(p) ?? null,
    put: async (p, bytes) => { const q = `${p.replace(/\.svg$/, "")}-r4nd.svg`; blobs.set(q, new Uint8Array(bytes)); return { pathname: q }; },
    remove: async (p) => { removed.push(p); },
  });
  const cleanText = stored.ok ? new TextDecoder().decode(blobs.get(stored.file.blobKey)) : "";
  ok(stored.ok && stored.file.blobKey !== "part-docs/PD-sym300a/x.svg" && removed.includes("part-docs/PD-sym300a/x.svg") && !/script|onclick/i.test(cleanText) && cleanText.includes("<rect") && (stored.file.svgRemoved?.length ?? 0) > 0,
    "#300 drawings: an SVG is sanitized into a new blob, the upload deleted, and what was stripped recorded");

  // One current symbol per part: attaching a second symbol unlinks the first.
  const sku = fixtureId(300, "sku-sym");
  const mk = (n: string) => pd300CreateDoc({ kind: "symbol", fileName: `${n}.svg`, contentType: "image/svg+xml", size: 100, blobKey: `part-docs/PD-fixture-${n}/${n}.svg`, sourceUrl: null, source: "upload", by: "Test" });
  const first = await mk("sym1");
  const second = await mk("sym2");
  if (!first || !second) throw new Error("#300 drawings: fixture documents failed to create");
  registerFixture("part_documents", first.id);
  registerFixture("part_documents", second.id);
  registerFixture("part_document_links", pd300LinkId(sku, first.id));
  registerFixture("part_document_links", pd300LinkId(sku, second.id));
  await pd300Attach(first.id, [sku], "Test");
  await pd300Attach(second.id, [sku], "Test");
  const live = (await pd300LinksFor([sku])).filter((l) => l.kind === "symbol").map((l) => l.documentId);
  ok(live.length === 1 && live[0] === second.id, "#300 drawings: attaching a second symbol to a part leaves only the second linked");
}

/* ======================================================================
   #300 Task 6 — object symbol resolution (D609): part drawing → device-type
   drawing → generic; device types carry a `symbolDocId`; symbolUrlsFor
   builds the per-part URL map server-side for the parts in view.
   ====================================================================== */
import { resolveObjectSymbol as os300Resolve } from "@/lib/design/object-symbols";
{
  const A = "PD-aaaaaa111", B = "PD-bbbbbb222", C = "PD-cccccc333";
  const U = (id: string) => `/api/part-documents/${encodeURIComponent(id)}`;
  const both = os300Resolve({ partSymbol: A, typeSymbol: B });
  ok(both.plan === U(A) && both.riser === U(A), "#300 symbols: the part's own drawing wins over its device type's");
  const typed = os300Resolve({ typeSymbol: B });
  ok(typed.plan === U(B) && typed.riser === U(B), "#300 symbols: a part with no drawing falls back to its device type's");
  const ris = os300Resolve({ partSymbol: A, partRiser: C });
  const risType = os300Resolve({ partRiser: C, typeSymbol: B });
  ok(ris.plan === U(A) && ris.riser === U(C) && risType.plan === U(B) && risType.riser === U(C) && os300Resolve({ partSymbol: A }).riser === U(A),
    "#300 symbols: the riser uses the part's riser drawing, else whatever the plan resolved to");
  ok(JSON.stringify(os300Resolve({})) === "{}" && JSON.stringify(os300Resolve({ partSymbol: "javascript:x", typeSymbol: "../etc" })) === "{}",
    "#300 symbols: nothing (or a malformed id) resolves to {} — the generic symbol draws");
}

